// Interruttore del piatto lato CRM. Volutamente separato dal PUT /dishes/:id
// che riscrive l'anagrafica intera: qui si tocca solo crm_enabled, così il
// toggle non può mai riportare indietro nome o prezzo appena sincronizzati
// dalla cassa.
app.put('/dishes/:id/enabled', authenticate, requirePermission('menu:full'), async (req, res) => {
    try {
        const id = Number(req.params.id);
        if (!Number.isInteger(id)) return res.status(400).json({ error: 'id non valido' });
        const enabled = req.body?.enabled;
        if (typeof enabled !== 'boolean') return res.status(400).json({ error: 'enabled deve essere true o false' });
        const rs = await queryWithRetry(
            `UPDATE dishes SET crm_enabled = $1 WHERE id = $2 AND tenant_id = $3 RETURNING *`,
            [enabled, id, req.tenantId!]
        );
        const dish = rs.rows[0];
        if (!dish) return res.status(404).json({ error: 'Dish not found' });
        // La riga viaggia intera sul socket: senza menu_ids le spunte dei
        // menu si azzererebbero su tutti i client a ogni toggle.
        dish.menu_ids = await dishMenuIds(dish.id);
        if (socketService) socketService.broadcastDishUpdated(req.tenantId!, dish);
        if (req.user) {
            LogService.logActivity(
                req.tenantId!, req.user.userId, req.user.email, req.user.email,
                ActivityAction.UPDATE, ResourceType.DISH, id, dish.name,
                { crm_enabled: enabled }
            ).catch(() => {});
        }
        res.json(dish);
    } catch (err: any) {
        console.error('PUT /dishes/:id/enabled error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Traduce in batch le voci mancanti (piatti attivi + categorie) nelle lingue
// del menu. Idempotente: ritradurre non tocca ciò che è già tradotto — per
// rifare una traduzione si svuota translations dal DB (caso raro, niente UI).
app.post('/menu/translate', authenticate, requirePermission('menu:full'), async (req, res) => {
    try {
        if (!isMenuTranslationConfigured()) {
            return res.status(503).json({ error: 'not_configured', message: 'ANTHROPIC_API_KEY non configurata sul backend' });
        }
        const richieste = Array.isArray(req.body?.langs)
            ? MENU_LANGS.filter((l) => req.body.langs.includes(l))
            : [...MENU_LANGS];
        const dishesRs = await queryWithRetry(
            `SELECT id, name, description, translations FROM dishes
             WHERE tenant_id = $1 AND is_active ORDER BY id`,
            [req.tenantId!]
        );
        const catRs = await queryWithRetry(
            `SELECT DISTINCT category FROM dishes
             WHERE tenant_id = $1 AND is_active AND COALESCE(category, '') <> ''`,
            [req.tenantId!]
        );
        const catTrad = await getMenuCategoryTranslations(req.tenantId!);
        let tradotte = 0;
        let tokens = 0;
        for (const lang of richieste) {
            const daFare = dishesRs.rows
                .filter((d: any) => !d.translations?.[lang]?.name)
                .map((d: any) => ({ id: `d${d.id}`, name: d.name as string, description: d.description as string | null }));
            for (const c of catRs.rows) {
                if (!catTrad[c.category]?.[lang]) daFare.push({ id: `c:${c.category}`, name: c.category, description: null });
            }
            if (daFare.length === 0) continue;
            const mappa = await translateMenuEntries(daFare, lang, (t) => { tokens += t; });
            for (const [id, t] of mappa) {
                if (id.startsWith('d')) {
                    const dishId = Number(id.slice(1));
                    if (!Number.isFinite(dishId)) continue;
                    await queryWithRetry(
                        `UPDATE dishes
                         SET translations = COALESCE(translations, '{}'::jsonb) || jsonb_build_object($3::text, $4::jsonb)
                         WHERE id = $1 AND tenant_id = $2`,
                        [dishId, req.tenantId!, lang, JSON.stringify(t)]
                    );
                    tradotte++;
                } else if (id.startsWith('c:')) {
                    const cat = id.slice(2);
                    catTrad[cat] = { ...(catTrad[cat] ?? {}), [lang]: t.name };
                    tradotte++;
                }
            }
        }
        await saveMenuCategoryTranslations(req.tenantId!, catTrad);
        try { socketService?.broadcastToAll(req.tenantId!, 'dish:synced', { tradotte }); } catch (_) {}
        res.json({ tradotte, lingue: richieste, tokens });
    } catch (err: any) {
        console.error('POST /menu/translate error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Dati del menu per la pagina pubblica: piatti attivi con traduzioni e
// categorie tradotte. Niente id interni, niente campi gestionali.
const handlePublicMenu = async (tenantId: number, _req: express.Request, res: express.Response) => {
    if (!(await getFeatureFlag(tenantId, 'digital_menu_enabled', false))) {
        return res.status(503).json({ error: 'menu_disabled' });
    }
    // Doppio interruttore: is_active è della cassa, crm_enabled del
    // ristoratore — il menu pubblico mostra solo ciò che entrambi accendono.
    // E solo i piatti del menu Alla carta: il QR al tavolo mostra ciò che si
    // può ordinare, non le liste banchetti o i menu stagionali.
    const dishesRs = await queryWithRetry(
        `SELECT d.name, d.description, d.price, d.category, d.allergens, d.photo_url, d.translations
         FROM dishes d WHERE d.tenant_id = $1 AND d.is_active AND d.crm_enabled
           AND EXISTS (SELECT 1 FROM dish_menus dm JOIN menus m ON m.id = dm.menu_id
                       WHERE dm.dish_id = d.id AND m.system_key = 'ALLA_CARTA')
         ORDER BY d.category, d.sort_order NULLS LAST, d.name`,
        [tenantId]
    );
    const prefs = await getMenuCategoryPrefs(tenantId);
    const rows = dishesRs.rows.filter((d: any) => prefs[String(d.category || 'Altro')]?.enabled !== false);
    // L'ordine scelto nel CRM, solo per le categorie effettivamente presenti:
    // la pagina lo usa per prime e tiene la sua euristica per le altre.
    const present = [...new Set(rows.map((d: any) => String(d.category || 'Altro')))] as string[];
    const categorieOrdine = sortCategoriesByPrefs(present, prefs).filter(name => prefs[name] != null);
    res.json({
        restaurant: businessIdentity(tenantId).name,
        lingue: ['it', ...MENU_LANGS],
        categorie: await getMenuCategoryTranslations(tenantId),
        categorie_ordine: categorieOrdine,
        piatti: rows.map((d: any) => ({
            name: d.name,
            description: d.description || null,
            price: Number(d.price),
            category: d.category || 'Altro',
            allergens: Array.isArray(d.allergens) ? d.allergens : [],
            photo_url: d.photo_url || null,
            translations: d.translations || null,
        })),
    });
};
app.get(['/public/menu', '/public/:slug/menu'], withPublicTenant(handlePublicMenu));

const serveMenuDigitale = async (_tenantId: number, _req: express.Request, res: express.Response) => {
    res.sendFile(path.join(process.cwd(), 'public', 'menu.html'));
};
// La variante con slug NON è /menu/:slug: oscurerebbe GET /menu/catalogue
// (il catalogo dell'orderpad). /m/<slug> è anche più corto dentro un QR.
app.get('/menu', withPublicTenant(serveMenuDigitale));
app.get('/m/:slug', withPublicTenant(serveMenuDigitale));

// Porta gli acconti/caparre già PAGATI di una prenotazione dentro il suo conto
// come quote PAID di kind='deposit'. Così l'importo abbassa il residuo (e la
// barra di avanzamento, il SETTLED, la chiusura, il preconto e il self-pay) SENZA
// toccare `total_cents`, che è immutabile e ricalcolato dalle comande.
//
// "Copre la coda": la quota a testa resta totale÷coperti; l'acconto è denaro già
// nel conto che assorbe le ultime quote — non uno sconto spalmato su tutti.
//
// Idempotente (indice unico su payment_request_id WHERE kind='deposit' +
// NOT EXISTS sotto lock): chiamabile ad ogni apertura conto e ad ogni webhook di
// pagamento senza doppioni. Clampa alla capienza residua: un acconto più grande
// del totale non sfonda il trigger di somma; l'eccedenza resta sull'acconto e va
// rimborsata a mano (come un pagamento in eccesso).
// tenantId: quello del conto (req.tenantId! dalle route, il tenant della
// payment_request dai webhook) — scopa conto, acconti e quote sullo stesso
// ristorante.
async function creditPaidDepositsToBill(tenantId: number, billId: number): Promise<{ credited: number; splits: any[]; settled: boolean }> {
    const client = await pool.connect();
    const created: any[] = [];
    let settled = false;
    try {
        await client.query('BEGIN');
        const billRs = await client.query(
            `SELECT id, reservation_id, total_cents, status FROM table_bills WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
            [billId, tenantId]
        );
        if (billRs.rowCount === 0) { await client.query('ROLLBACK'); return { credited: 0, splits: [], settled: false }; }
        const bill = billRs.rows[0];
        // Solo conti ancora incassabili: su SETTLED/CLOSED/VOIDED non si tocca.
        if (!bill.reservation_id || !['OPEN', 'LOCKED'].includes(bill.status)) {
            await client.query('ROLLBACK');
            return { credited: 0, splits: [], settled: false };
        }

        // Acconti PAGATI di questa prenotazione, che sono caparre standalone
        // (non quote di conto) e non ancora accreditati su alcun conto.
        const deposits = await client.query(
            `SELECT pr.id, pr.amount_cents, pr.completed_at
             FROM payment_requests pr
             WHERE pr.reservation_id = $1
               AND pr.tenant_id = $2
               AND pr.table_bill_split_id IS NULL
               AND UPPER(pr.status) IN ('COMPLETED', 'PAID')
               AND pr.completed_at IS NOT NULL
               AND NOT EXISTS (
                   SELECT 1 FROM table_bill_splits s
                   WHERE s.payment_request_id = pr.id AND s.kind = 'deposit'
               )
             ORDER BY pr.completed_at ASC`,
            [bill.reservation_id, tenantId]
        );

        for (const dep of deposits.rows) {
            const capRs = await client.query(
                `SELECT COALESCE(SUM(amount_cents), 0)::int AS live
                 FROM table_bill_splits
                 WHERE table_bill_id = $1 AND status IN ('CLAIMED', 'PAID')`,
                [billId]
            );
            // Anche gli incassi staff occupano capienza: un conto già pagato
            // in contanti non assorbe l'acconto (che resta da rimborsare).
            const staffPaid = await staffPaidCentsForBill(billId, client);
            const capacity = bill.total_cents - capRs.rows[0].live - staffPaid;
            const credit = Math.min(Number(dep.amount_cents), Math.max(0, capacity));
            if (credit <= 0) continue; // conto già coperto: l'acconto resta eccedenza da rimborsare
            const ins = await client.query(
                `INSERT INTO table_bill_splits
                    (tenant_id, table_bill_id, kind, amount_cents, claimant_label, claimed_at, expires_at, payment_request_id, status, paid_at)
                 VALUES ($5, $1, 'deposit', $2, 'Acconto', $3, NULL, $4, 'PAID', $3)
                 ON CONFLICT (payment_request_id) WHERE kind = 'deposit' DO NOTHING
                 RETURNING *`,
                [billId, credit, dep.completed_at, dep.id, tenantId]
            );
            if (ins.rowCount) created.push(ins.rows[0]);
        }

        // Se acconti + incassi staff coprono il totale, il conto è già saldato.
        const settledRs = await client.query(
            `UPDATE table_bills SET status = 'SETTLED'
             WHERE id = $1 AND status IN ('OPEN', 'LOCKED')
               AND total_cents <= (
                     (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_splits WHERE table_bill_id = $1 AND status = 'PAID')
                   + (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_payments WHERE table_bill_id = $1 AND table_bill_split_id IS NULL AND voided_at IS NULL)
               )
             RETURNING id`,
            [billId]
        );
        settled = (settledRs.rowCount ?? 0) > 0;
        await client.query('COMMIT');
    } catch (err) {
        await client.query('ROLLBACK').catch(() => {});
        console.error('[deposit-credit] failed for bill', billId, (err as any)?.message || err);
    } finally {
        client.release();
    }
    const credited = created.reduce((s, r) => s + Number(r.amount_cents), 0);
    return { credited, splits: created, settled };
}

// Vista completa del conto: riga bill + quote + totali già sommati. Fonte unica
// per GET /reservations/:id/bill e per la risposta di apertura conto, così la
// riga "Acconto −€X" (deposit_credit_cents) e il residuo sono calcolati in un
// solo posto. deposit_credit_cents è la somma delle quote PAID di kind='deposit'
// — già incluse in paid_cents e già scalate dal residuo; il campo serve solo a
// far mostrare al client la voce dell'acconto senza reindovinare quali quote lo
// siano.

// Acconto TOTALE pagato su una prenotazione (importo pieno delle caparre
// COMPLETED), a prescindere da quanto se ne è potuto applicare al conto. Serve
// a mostrare l'acconto reale e a calcolare quanto va rimborsato al cliente
// quando la caparra supera il totale del conto.
async function depositPaidCentsForReservation(tenantId: number, reservationId: number | null): Promise<number> {
    if (!reservationId) return 0;
    const r = await queryWithRetry(
        `SELECT COALESCE(SUM(amount_cents), 0)::int AS s
         FROM payment_requests
         WHERE reservation_id = $1
           AND tenant_id = $2
           AND table_bill_split_id IS NULL
           AND UPPER(status) IN ('COMPLETED', 'PAID')
           AND completed_at IS NOT NULL`,
        [reservationId, tenantId]
    );
    return r.rows[0].s;
}

// Somma degli incassi staff attivi sul conto: le righe del libro cassa senza
// specchio quota (table_bill_split_id NULL) e non stornate. Pesano sul residuo
// accanto alle quote CLAIMED/PAID — le righe LINK_ONLINE specchiano quote già
// contate e qui restano fuori per non raddoppiare l'incasso.
async function staffPaidCentsForBill(billId: number, client?: any): Promise<number> {
    const sql = `SELECT COALESCE(SUM(amount_cents), 0)::int AS s
                 FROM table_bill_payments
                 WHERE table_bill_id = $1 AND table_bill_split_id IS NULL AND voided_at IS NULL`;
    const r = client ? await client.query(sql, [billId]) : await queryWithRetry(sql, [billId]);
    return r.rows[0].s;
}

async function loadBillView(tenantId: number, billId: number): Promise<any | null> {
    const billResult = await queryWithRetry(
        `SELECT id, reservation_id, table_id, total_cents, covers, currency,
                items, status, share_token, opened_at, closed_at,
                opened_by_user_id, closed_by_user_id, external_ref,
                cash_settled_cents, tip_cents, notes
         FROM table_bills WHERE id = $1 AND tenant_id = $2`,
        [billId, tenantId]
    );
    if (billResult.rows.length === 0) return null;
    const bill = billResult.rows[0];
    const splitsResult = await queryWithRetry(
        `SELECT id, table_bill_id, kind, amount_cents, item_ids,
                claimant_label, claimed_at, expires_at,
                payment_request_id, status, paid_at, released_at
         FROM table_bill_splits WHERE table_bill_id = $1
         ORDER BY claimed_at ASC`,
        [billId]
    );
    // Libro cassa completo (specchi e storni inclusi): la UI mostra i
    // movimenti; nei totali gli specchi e gli storni non contano.
    const paymentsResult = await queryWithRetry(
        `SELECT id, table_bill_id, method, amount_cents, table_bill_split_id,
                meta, recorded_by_user_id, recorded_at,
                voided_at, voided_by_user_id, void_reason
         FROM table_bill_payments WHERE table_bill_id = $1
         ORDER BY recorded_at ASC`,
        [billId]
    );
    const staff_paid_cents = paymentsResult.rows.reduce(
        (n: number, p: any) => n + (p.table_bill_split_id == null && p.voided_at == null ? p.amount_cents : 0), 0
    );
    // Documenti fiscali del conto (senza request/response: pesano e alla UI
    // servono stato, riferimento ed eventuale errore).
    const fiscalResult = await queryWithRetry(
        `SELECT id, table_bill_id, doc_type, provider, status, provider_ref, error,
                total_cents, attempts, created_at, confirmed_at, voided_at
         FROM fiscal_documents WHERE table_bill_id = $1
         ORDER BY created_at ASC`,
        [billId]
    );
    const totals = splitsResult.rows.reduce(
        (acc, s) => {
            if (s.status === 'PAID') {
                acc.paid_cents += s.amount_cents;
                if (s.kind === 'deposit') acc.deposit_credit_cents += s.amount_cents;
            }
            if (s.status === 'CLAIMED') acc.claimed_cents += s.amount_cents;
            return acc;
        },
        { paid_cents: 0, claimed_cents: 0, deposit_credit_cents: 0 }
    );
    const residual_cents = Math.max(0, bill.total_cents - totals.paid_cents - totals.claimed_cents - staff_paid_cents);
    // Acconto pieno versato e quota non assorbita dal conto (da rimborsare al
    // cliente quando la caparra supera il totale).
    const deposit_paid_cents = await depositPaidCentsForReservation(tenantId, bill.reservation_id);
    const refund_due_cents = Math.max(0, deposit_paid_cents - totals.deposit_credit_cents);
    return {
        bill,
        splits: splitsResult.rows,
        payments: paymentsResult.rows,
        staff_paid_cents,
        paid_cents: totals.paid_cents,
        claimed_cents: totals.claimed_cents,
        deposit_credit_cents: totals.deposit_credit_cents,
        deposit_paid_cents,
        refund_due_cents,
        residual_cents,
        // Vuoto per i conti aperti a mano (niente righe): la UI non mostra
        // la sezione IVA finché non c'è un dettaglio da cui derivarla.
        vat_breakdown: vatBreakdownFromItems(bill.items, bill.total_cents),
        fiscal_documents: fiscalResult.rows,
    };
}

// Conto al tavolo attivo davvero: VENDUTO (entitlement pay_at_table, si
// compra) E ACCESO dal ristoratore (flag operativo in Impostazioni). Ogni
// route del modulo — staff e pubbliche via token — passa da qui: senza
// entitlement il flag operativo non basta più.
async function isPayAtTableActive(tenantId: number): Promise<boolean> {
    if (!(await isFeatureEnabledForTenant(tenantId, 'pay_at_table'))) return false;
    return getFeatureFlag(tenantId, 'pay_at_table_enabled', false);
}

app.post('/reservations/:id/bill', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        if (!(await isPayAtTableActive(req.tenantId!))) {
            return res.status(403).json({
                error: 'feature_disabled',
                message: 'Il conto al tavolo è disattivato. Attivalo da Impostazioni → Conto al tavolo.',
            });
        }

        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid reservation id' });

        const resRow = await queryWithRetry(
            // Scopata sul tenant: un reservation_id altrui cade qui nel 404
            // prima di poter aprire un conto sul tavolo di un altro ristorante.
            'SELECT id, guests, table_id, reservation_time, shift FROM reservations WHERE id = $1 AND tenant_id = $2',
            [id, req.tenantId!]
        );
        if (resRow.rows.length === 0) return res.status(404).json({ error: 'Reservation not found' });

        // Sorgente Passepartout: righe e totale arrivano dalla comanda del
        // gestionale, non dal cameriere. total_cents nel body viene ignorato.
        const fromPassepartout = req.body?.source === 'passepartout';
        let ppPayload: ReturnType<typeof comandaToBillPayload> | null = null;
        if (fromPassepartout) {
            const tavolo = String(req.body?.pp_tavolo || '').trim();
            if (!tavolo) return res.status(400).json({ error: 'pp_tavolo mancante per source=passepartout' });
            let found = await findComandaTavolo(tavolo);
            // Tavoli uniti: in sala la comanda può essere stata aperta su uno
            // qualsiasi dei tavoli dell'unione (25/08: 45+47 uniti, comanda
            // battuta sul 47, prenotazione sul 45 → import a vuoto). Se il
            // tavolo della prenotazione non ha comanda, si provano gli altri
            // tavoli della sua unione per la stessa data e turno.
            if (!found && resRow.rows[0].table_id != null) {
                const mergeDate = getRomeDatePart(resRow.rows[0].reservation_time);
                const siblings = await queryWithRetry(
                    `SELECT t.name
                       FROM table_merges m
                       JOIN tables t ON t.tenant_id = m.tenant_id
                        AND t.id = ANY(array_append(m.merged_ids, m.primary_id))
                      WHERE m.tenant_id = $1 AND m.date = $2::date AND m.shift = $3
                        AND (m.primary_id = $4 OR $4 = ANY(m.merged_ids))
                        AND t.id <> $4`,
                    [req.tenantId!, mergeDate, resRow.rows[0].shift, resRow.rows[0].table_id]
                );
                for (const s of siblings.rows) {
                    found = await findComandaTavolo(String(s.name));
                    if (found) break;
                }
            }
            if (!found) {
                return res.status(404).json({ error: 'no_comanda', message: `Nessuna comanda attiva sul tavolo "${tavolo}" nel gestionale (provati anche gli eventuali tavoli uniti). Il nome deve combaciare con quello di Passepartout (punto e spazi compresi).` });
            }
            ppPayload = comandaToBillPayload(found.comanda);
            if (ppPayload.total_cents <= 0) {
                return res.status(422).json({ error: 'empty_comanda', message: 'La comanda ha totale zero' });
            }
        }

        const totalCents = fromPassepartout ? ppPayload!.total_cents : Number(req.body?.total_cents);
        if (!Number.isFinite(totalCents) || totalCents <= 0) {
            return res.status(400).json({ error: 'total_cents must be a positive integer' });
        }
        const totalRounded = Math.round(totalCents);

        // covers: usa quello passato dal cameriere se valido, poi i coperti
        // della comanda Passepartout, poi i guests della prenotazione. Serve
        // al pubblico per proporre lo split equo di default.
        const requestedCovers = req.body?.covers != null ? Number(req.body.covers) : NaN;
        const fallbackCovers = Number(ppPayload?.covers ?? NaN) > 0
            ? Number(ppPayload!.covers)
            : Number(resRow.rows[0].guests);
        const covers = Number.isFinite(requestedCovers) && requestedCovers > 0
            ? Math.round(requestedCovers)
            : (Number.isFinite(fallbackCovers) && fallbackCovers > 0 ? fallbackCovers : 1);

        // Un bill "attivo" (OPEN/LOCKED/SETTLED*) blocca l'apertura di uno
        // nuovo per evitare che il pubblico veda due QR/URL diversi.
        const existing = await queryWithRetry(
            `SELECT id, status FROM table_bills
             WHERE reservation_id = $1
               AND tenant_id = $2
               AND status IN ('OPEN','LOCKED','SETTLED','SETTLED_PARTIAL')
             LIMIT 1`,
            [id, req.tenantId!]
        );
        if (existing.rows.length > 0) {
            return res.status(409).json({
                error: 'Reservation already has an active bill',
                existing_bill_id: existing.rows[0].id,
                existing_bill_status: existing.rows[0].status,
            });
        }

        const shareToken = crypto.randomBytes(24).toString('base64url');

        const inserted = await queryWithRetry(
            `INSERT INTO table_bills
                (tenant_id, reservation_id, table_id, total_cents, covers, share_token, opened_by_user_id,
                 items, external_ref, service_date, shift)
             VALUES ($11, $1, $2, $3, $4, $5, $6, $7::jsonb, $8, $9, $10)
             RETURNING id, reservation_id, table_id, total_cents, covers, currency,
                       items, status, share_token, opened_at, closed_at,
                       opened_by_user_id, closed_by_user_id, external_ref,
                       cash_settled_cents, tip_cents, notes`,
            [id, resRow.rows[0].table_id, totalRounded, covers, shareToken, req.user?.userId ?? null,
             ppPayload ? JSON.stringify(ppPayload.items) : null,
             ppPayload?.external_ref ?? null,
             resolveService().service_date, resolveService().shift, req.tenantId!]
        );
        const bill = inserted.rows[0];

        try { socketService?.broadcastToAll(req.tenantId!, 'bill:opened', bill); } catch (_) {}

        // Porta subito nel conto gli acconti già pagati sulla prenotazione (una
        // caparra versata prima che il conto esistesse viene raccolta qui).
        const credit = await creditPaidDepositsToBill(req.tenantId!, bill.id).catch(() => ({ credited: 0, settled: false }));
        if (credit.credited > 0) {
            try { socketService?.broadcastToAll(req.tenantId!, 'bill:updated', { id: bill.id, reservation_id: bill.reservation_id }); } catch (_) {}
        }

        const view = await loadBillView(req.tenantId!, bill.id);
        res.status(201).json(view ?? {
            bill, splits: [], paid_cents: 0, claimed_cents: 0, deposit_credit_cents: 0,
            residual_cents: bill.total_cents,
        });
    } catch (err: any) {
        if (sendPassepartoutError(res, err)) return;
        console.error('POST /reservations/:id/bill error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Notifica al cliente il link del conto al tavolo. Idempotente rispetto
// al bill (non ne crea di nuovi), ma NON idempotente sul canale: ogni
// chiamata invia un nuovo messaggio, così il cameriere può "reinviare"
// se il primo tentativo si è perso. La consegna è sincrona qui — a
// differenza di /payments/requests — perché la UI mostra un toast
// esplicito con il canale usato.
app.post('/reservations/:id/bill/notify', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        if (!(await isPayAtTableActive(req.tenantId!))) {
            return res.status(403).json({
                error: 'feature_disabled',
                message: 'Il conto al tavolo è disattivato. Attivalo da Impostazioni → Conto al tavolo.',
            });
        }

        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid reservation id' });

        const resvRow = await queryWithRetry(
            'SELECT id, customer_name, phone FROM reservations WHERE id = $1 AND tenant_id = $2',
            [id, req.tenantId!]
        );
        if (resvRow.rowCount === 0) return res.status(404).json({ error: 'Reservation not found' });
        const reservation = resvRow.rows[0];
        if (!reservation.phone) {
            return res.status(400).json({ error: 'La prenotazione non ha un numero di telefono' });
        }

        const billRow = await queryWithRetry(
            `SELECT id, total_cents, covers, share_token, status
             FROM table_bills
             WHERE reservation_id = $1
               AND tenant_id = $2
               AND status IN ('OPEN','LOCKED')
             ORDER BY opened_at DESC
             LIMIT 1`,
            [id, req.tenantId!]
        );
        if (billRow.rowCount === 0) {
            return res.status(404).json({ error: 'Nessun conto aperto per questa prenotazione' });
        }
        const bill = billRow.rows[0];
        if (!bill.share_token) {
            return res.status(409).json({ error: 'Il conto non ha un link pubblico attivo' });
        }

        const publicUrl = `${payAtTableBaseUrl()}/pay/${bill.share_token}`;
        const message = buildTableBillLinkMessage(
            reservation.customer_name,
            Number(bill.total_cents),
            Number(bill.covers) || 1,
            publicUrl
        );

        try {
            const delivery = await sendBookingConfirmation(req.tenantId!, reservation.phone, message, reservation.id, {
                whatsappTemplate: buildTableBillLinkTemplate(
                    reservation.customer_name,
                    Number(bill.covers) || 1,
                    Number(bill.total_cents),
                    bill.share_token
                ),
            });
            if (req.user) {
                LogService.logActivity(
                    req.tenantId!,
                    req.user.userId,
                    req.user.email,
                    req.user.email,
                    ActivityAction.CREATE,
                    ResourceType.RESERVATION,
                    reservation.id,
                    `${reservation.customer_name} — inviato link conto al tavolo (${delivery.channel})`
                );
            }
            res.json({
                ok: true,
                bill_id: bill.id,
                channel: delivery.channel,
                provider_sid: delivery.sid || null,
                public_url: publicUrl,
            });
        } catch (err: any) {
            console.error('[bill:notify] delivery failed:', err?.message || err);
            res.status(502).json({
                error: 'delivery_failed',
                message: err?.message || 'Invio del messaggio non riuscito',
            });
        }
    } catch (err: any) {
        console.error('POST /reservations/:id/bill/notify error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Chiude un bill (tipicamente perché è stato saldato al 100%, o perché
// il cameriere forza la chiusura registrando l'incasso mancante come
// contante/POS al tavolo). `cash_settled_cents` e `tip_cents` sono
// opzionali: servono al breakdown per la contabilità (in Fase 2 saranno
// il payload della POST /chiudi-conto verso Passepartout). Il token
// pubblico viene invalidato subito (SET NULL) così un QR fotografato
// prima non funziona più.
// Metodi registrabili a mano dallo staff. LINK_ONLINE è escluso: quelle
// righe le scrive solo il webhook come specchio di una quota PAID.
const STAFF_BILL_PAYMENT_METHODS = ['CONTANTI', 'POS_FISICO', 'SATISPAY', 'BUONO_PASTO', 'GIFT_CARD', 'SOSPESO', 'OMAGGIO'] as const;

function parseStaffBillPayment(raw: any): { method: string; amount_cents: number; meta: any } | { error: string } {
    const method = String(raw?.method || '');
    if (!STAFF_BILL_PAYMENT_METHODS.includes(method as any)) {
        return { error: `method must be one of ${STAFF_BILL_PAYMENT_METHODS.join(', ')}` };
    }
    const amount = Number(raw?.amount_cents);
    if (!Number.isFinite(amount) || !Number.isInteger(amount) || amount <= 0) {
        return { error: 'amount_cents must be a positive integer' };
    }
    const meta = raw?.meta && typeof raw.meta === 'object' && !Array.isArray(raw.meta) ? raw.meta : null;
    return { method, amount_cents: amount, meta };
}

app.post('/bills/:id/close', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid bill id' });

        // Corpo nuovo: `payments` è la lista dei movimenti di incasso da
        // registrare contestualmente alla chiusura (metodo + importo).
        // `cash_settled_cents` resta accettato per i client vecchi, che
        // mandano il TOTALE contanti desiderato sul conto: la differenza
        // rispetto ai contanti già a libro diventa una riga CONTANTI.
        const cashRaw = req.body?.cash_settled_cents;
        const tipRaw = req.body?.tip_cents;
        const legacyCashCents = cashRaw != null ? Number(cashRaw) : null;
        const tipCents = tipRaw != null ? Number(tipRaw) : 0;
        if (legacyCashCents != null && (!Number.isFinite(legacyCashCents) || legacyCashCents < 0)) {
            return res.status(400).json({ error: 'cash_settled_cents must be >= 0' });
        }
        if (!Number.isFinite(tipCents) || tipCents < 0) {
            return res.status(400).json({ error: 'tip_cents must be >= 0' });
        }
        const rawPayments = Array.isArray(req.body?.payments) ? req.body.payments : [];
        const parsedPayments: { method: string; amount_cents: number; meta: any }[] = [];
        for (const raw of rawPayments) {
            const p = parseStaffBillPayment(raw);
            if ('error' in p) return res.status(400).json({ error: p.error });
            parsedPayments.push(p);
        }
        const notes = typeof req.body?.notes === 'string' ? req.body.notes.slice(0, 500) : null;

        // Scontrino battuto sull'RT di cassa (periodo ponte senza provider
        // cloud): il numero riportato dal cassiere è testo libero — i
        // formati dei registratori variano — ma corto per costruzione.
        const rtDocRaw = typeof req.body?.rt_doc_number === 'string' ? req.body.rt_doc_number.trim() : '';
        if (rtDocRaw.length > 30) {
            return res.status(400).json({ error: 'rt_doc_number_invalid', message: 'Il numero scontrino supera i 30 caratteri' });
        }
        const rtDocNumber = rtDocRaw || null;

        // Codice lotteria degli scontrini (8 alfanumerici AdE), dettato dal
        // cliente in cassa: viaggia col conto e finisce nel documento
        // commerciale all'emissione cloud. Vuoto = niente lotteria. NB: il
        // codice lotteria non si abbina allo scontrino parlante (col CF).
        const lotteryRaw = typeof req.body?.lottery_code === 'string' ? req.body.lottery_code.trim().toUpperCase() : '';
        if (lotteryRaw && !/^[A-Z0-9]{8}$/.test(lotteryRaw)) {
            return res.status(400).json({ error: 'lottery_code_invalid', message: 'Il codice lotteria sono 8 lettere o cifre' });
        }
        const lotteryCode = lotteryRaw || null;

        // Need the current total + sums to decide between CLOSED and
        // SETTLED_PARTIAL and to sanity-check the caller's values. Fetch
        // under a lock so a webhook-triggered PAID→SETTLED promotion can't
        // race us and flip status underneath.
        const client = await pool.connect();
        let updatedRow: any = null;
        try {
            await client.query('BEGIN');
            const billRs = await client.query(
                // Scopato sul tenant: un bill id altrui fa 404 come un id inesistente.
                `SELECT id, total_cents, status FROM table_bills WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
                [id, req.tenantId!]
            );
            if (billRs.rowCount === 0 || !['OPEN','LOCKED','SETTLED','SETTLED_PARTIAL'].includes(billRs.rows[0].status)) {
                await client.query('ROLLBACK');
                return res.status(404).json({ error: 'Bill not found or already closed/voided' });
            }
            const totalCents: number = billRs.rows[0].total_cents;

            // Sanity caps: a tip above the bill total or a cash amount above
            // 2x is almost certainly a typo. 2x on cash covers the waiter who
            // accidentally records the tip inside cash — still wrong, but not
            // a data-loss-level typo.
            if (tipCents > totalCents) {
                await client.query('ROLLBACK');
                return res.status(400).json({ error: 'tip_cents exceeds total (max 100%)', max_allowed_cents: totalCents });
            }
            if (legacyCashCents != null && legacyCashCents > totalCents * 2) {
                await client.query('ROLLBACK');
                return res.status(400).json({ error: 'cash_settled_cents implausible (>200% of total)', max_allowed_cents: totalCents * 2 });
            }

            const paidRs = await client.query(
                `SELECT COALESCE(SUM(amount_cents), 0)::int AS paid_cents
                 FROM table_bill_splits
                 WHERE table_bill_id = $1 AND status = 'PAID'`,
                [id]
            );
            const paidViaSplits: number = paidRs.rows[0].paid_cents;

            // Traduzione del parametro legacy in un movimento: il client
            // vecchio manda il totale contanti cumulativo, a libro va solo
            // la differenza rispetto ai CONTANTI già registrati.
            if (legacyCashCents != null) {
                const cashRs = await client.query(
                    `SELECT COALESCE(SUM(amount_cents), 0)::int AS s
                     FROM table_bill_payments
                     WHERE table_bill_id = $1 AND method = 'CONTANTI' AND table_bill_split_id IS NULL AND voided_at IS NULL`,
                    [id]
                );
                const cashDelta = Math.round(legacyCashCents) - cashRs.rows[0].s;
                if (cashDelta > 0) parsedPayments.push({ method: 'CONTANTI', amount_cents: cashDelta, meta: null });
            }

            // Registra i movimenti della chiusura. Ogni importo è clampato al
            // residuo corrente: l'eccedenza (resto, arrotondamenti del client)
            // non entra a libro — il resto si calcola in UI, non qui.
            let staffPaid = await staffPaidCentsForBill(id, client);
            for (const p of parsedPayments) {
                const residual = totalCents - paidViaSplits - staffPaid;
                const amount = Math.min(p.amount_cents, Math.max(0, residual));
                if (amount <= 0) continue;
                await client.query(
                    `INSERT INTO table_bill_payments (tenant_id, table_bill_id, method, amount_cents, meta, recorded_by_user_id)
                     VALUES ($1, $2, $3, $4, $5, $6)`,
                    [req.tenantId!, id, p.method, amount, p.meta ? JSON.stringify(p.meta) : null, req.user?.userId ?? null]
                );
                staffPaid += amount;
            }

            const totalSettled = paidViaSplits + staffPaid;
            const finalStatus = totalSettled >= totalCents ? 'CLOSED' : 'SETTLED_PARTIAL';

            // Stamp an audit prefix on notes when closing with a shortfall
            // so the accounting readout has a machine-parseable delta. The
            // waiter-supplied `notes` still wins if provided; otherwise the
            // existing DB notes stay put.
            let notesForDb: string | null = notes;
            if (finalStatus === 'SETTLED_PARTIAL') {
                const delta = totalCents - totalSettled;
                const shortfallTag = `[shortfall:${delta}]`;
                notesForDb = notes ? `${shortfallTag} ${notes}` : shortfallTag;
            }

            // cash_settled_cents resta popolato per i lettori vecchi, ma ora
            // è una PROIEZIONE del libro cassa: somma delle righe CONTANTI.
            const upd = await client.query(
                `UPDATE table_bills
                 SET status = $2,
                     closed_at = CURRENT_TIMESTAMP,
                     closed_by_user_id = $3,
                     cash_settled_cents = (
                         SELECT COALESCE(SUM(amount_cents), 0)::int
                         FROM table_bill_payments
                         WHERE table_bill_id = $1 AND method = 'CONTANTI' AND table_bill_split_id IS NULL AND voided_at IS NULL
                     ),
                     tip_cents = $4,
                     notes = COALESCE($5, notes),
                     lottery_code = COALESCE($7, lottery_code),
                     share_token = NULL
                 WHERE id = $1 AND tenant_id = $6
                 RETURNING id, reservation_id, table_id, total_cents, covers, currency,
                           items, status, share_token, opened_at, closed_at,
                           opened_by_user_id, closed_by_user_id, external_ref,
                           cash_settled_cents, tip_cents, notes`,
                [id, finalStatus, req.user?.userId ?? null, Math.round(tipCents), notesForDb, req.tenantId!, lotteryCode]
            );
            updatedRow = upd.rows[0];
            await client.query('COMMIT');
        } catch (txErr) {
            await client.query('ROLLBACK').catch(() => {});
            throw txErr;
        } finally {
            client.release();
        }

        try { socketService?.broadcastToAll(req.tenantId!, 'bill:closed', updatedRow); } catch (_) {}

        // Documento commerciale: parte in automatico sui conti saldati per
        // intero, fuori dalla risposta — la chiusura non aspetta il fisco.
        // Esito via socket 'fiscal:updated'; retry da POST /bills/:id/fiscal-docs.
        // ECCEZIONE: un conto nato da una comanda Passepartout si chiude sul
        // gestionale, che emette lui il documento fiscale dall'RT di cassa —
        // l'emissione Openapi qui produrrebbe un secondo documento per lo
        // stesso incasso. Retry da POST /bills/:id/passepartout-close.
        if (updatedRow.status === 'CLOSED') {
            const ppComandaId = passepartoutComandaIdFromRef(updatedRow.external_ref);
            if (ppComandaId != null) {
                const ppConfig = getPassepartoutChiusuraConfig();
                // Documento scelto dal cameriere nel dialog di chiusura:
                // Proforma = la chiusura senza scontrino usata di routine in
                // cassa. Assente o non valido → Scontrino.
                const ppDocumento = req.body?.passepartout_documento === 'Proforma' ? 'Proforma' as const : undefined;
                if (ppConfig) {
                    chiudiComandaPassepartoutPerBill(req.tenantId!, id, ppComandaId, ppConfig, ppDocumento)
                        .catch(err => console.error('[passepartout] chiusura comanda fallita per conto', id, err?.message));
                } else {
                    console.warn('[passepartout] conto', id, 'chiuso ma PASSEPARTOUT_TIPO_PAGAMENTO non configurato: comanda', ppComandaId, 'da chiudere in cassa a mano');
                }
            } else if (req.body?.documento === 'Cassa') {
                // Scontrino emesso dall'RT esterno: il documento fiscale
                // esiste davvero, solo che l'ha battuto la cassa — si
                // registra con numero (se riportato) così chiusura cassa e
                // registro quadrano col registratore, senza binario cloud.
                registerExternalRtReceipt(req.tenantId!, id, req.user?.userId ?? null, rtDocNumber)
                    .catch(err => console.error('[fiscal] registrazione scontrino di cassa fallita per conto', id, err?.message));
            } else if (req.body?.documento === 'Proforma') {
                // Proforma anche per i conti nativi: chiusura DELIBERATA
                // senza documento fiscale. La riga PROFORMA registra la
                // scelta (in lista è "proforma", non "senza scontrino" =
                // dimenticato) e resta sostituibile: scontrino o fattura
                // emessi dopo la superano da soli.
                registerNativeProforma(req.tenantId!, id, req.user?.userId ?? null)
                    .catch(err => console.error('[fiscal] registrazione proforma fallita per conto', id, err?.message));
            } else {
                emitFiscalDocForBill(req.tenantId!, id, req.user?.userId ?? null)
                    .catch(err => console.error('[fiscal] emissione post-chiusura fallita per conto', id, err?.message));
            }
        }

        res.json(updatedRow);
    } catch (err: any) {
        console.error('POST /bills/:id/close error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Annulla un bill (errore di battitura del cameriere, tavolo che se n'è
// andato prima di ricevere il QR, ecc.). I claim/PAID splits restano in
// tabella per audit; il token pubblico è invalidato immediatamente.
// Non fa refund automatico degli split PAID — se ne è già stato saldato
// qualcuno, il cameriere deve rimborsare a mano (Fase 5 aggiungerà
// endpoint refund dedicato).
app.post('/bills/:id/void', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid bill id' });

        const notes = typeof req.body?.notes === 'string' ? req.body.notes.slice(0, 500) : null;

        const updated = await queryWithRetry(
            `UPDATE table_bills
             SET status = 'VOIDED',
                 closed_at = CURRENT_TIMESTAMP,
                 closed_by_user_id = $2,
                 notes = COALESCE($3, notes),
                 share_token = NULL
             WHERE id = $1
               AND tenant_id = $4
               AND status IN ('OPEN','LOCKED','SETTLED','SETTLED_PARTIAL')
             RETURNING id, reservation_id, table_id, total_cents, covers, currency,
                       items, status, share_token, opened_at, closed_at,
                       opened_by_user_id, closed_by_user_id, external_ref,
                       cash_settled_cents, tip_cents, notes`,
            [id, req.user?.userId ?? null, notes, req.tenantId!]
        );
        if (updated.rows.length === 0) {
            return res.status(404).json({ error: 'Bill not found or already closed/voided' });
        }

        try { socketService?.broadcastToAll(req.tenantId!, 'bill:voided', updated.rows[0]); } catch (_) {}

        res.json(updated.rows[0]);
    } catch (err: any) {
        console.error('POST /bills/:id/void error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Riapertura di un conto chiuso per errore (docs/cassa-plan.md §3.3).
//
// Finora un conto riapriva solo come EFFETTO COLLATERALE di uno storno di
// incasso o del rimborso di una quota. Serviva l'atto esplicito: si è chiuso
// il tavolo sbagliato, o è arrivato un altro giro dopo il conto.
//
// I movimenti restano tutti: riaprire non è annullare. Quello che torna
// indietro è lo stato del conto, non il libro cassa.
//
// La guardia che conta è il documento fiscale: uno scontrino CONFERMATO è già
// stato trasmesso all'Agenzia, e riaprirci sopra un conto vorrebbe dire
// incassare due volte contro un documento solo. Prima si annulla il
// documento (POST /bills/:id/fiscal-docs/:fid/void), poi si riapre.
app.post('/bills/:id/reopen', authenticate, requirePermission('cash:void_payment'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'id non valido' });

        const cur = await queryWithRetry(
            `SELECT id, status FROM table_bills WHERE id = $1 AND tenant_id = $2`,
            [id, req.tenantId!]
        );
        if (cur.rows.length === 0) return res.status(404).json({ error: 'Conto non trovato' });
        if (!['CLOSED', 'SETTLED_PARTIAL', 'SETTLED'].includes(cur.rows[0].status)) {
            return res.status(409).json({ error: 'Il conto non è chiuso', status: cur.rows[0].status });
        }

        const doc = await queryWithRetry(
            `SELECT id, doc_type FROM fiscal_documents
              WHERE table_bill_id = $1 AND status = 'CONFIRMED' AND doc_type IN ('RECEIPT', 'INVOICE')
              ORDER BY created_at DESC LIMIT 1`,
            [id]
        );
        if (doc.rows.length > 0) {
            return res.status(409).json({
                error: 'Il conto ha un documento fiscale emesso: annullalo prima di riaprirlo.',
                fiscal_doc_id: doc.rows[0].id,
                fiscal_doc_type: doc.rows[0].doc_type,
            });
        }

        const upd = await queryWithRetry(
            `UPDATE table_bills
                SET status = 'OPEN', closed_at = NULL, closed_by_user_id = NULL
              WHERE id = $1 AND tenant_id = $2
              RETURNING id, reservation_id, table_id, total_cents, covers, currency,
                        items, status, share_token, opened_at, closed_at, cash_settled_cents,
                        tip_cents, notes, external_ref`,
            [id, req.tenantId!]
        );

        const row = upd.rows[0];
        // Come le altre route del conto (close, void): l'evento socket e la
        // riga stessa sono il registro — closed_at che torna NULL dice quando.
        try { socketService?.broadcastToAll(req.tenantId!, 'bill:opened', row); } catch (_) {}
        res.json(row);
    } catch (err: any) {
        console.error('POST /bills/:id/reopen error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});


// Registra un movimento di incasso a conto ancora aperto — l'ospite che va
// via prima e paga la sua parte in contanti al banco, il POS passato a metà
// cena. Importo validato sotto lock contro il residuo VERO (quote CLAIMED
// comprese: una quota impegnata da un QR non si incassa anche in cassa).
// Se il movimento copre il residuo il conto passa a SETTLED, come per le
// quote online.
app.post('/bills/:id/payments', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid bill id' });
        const parsed = parseStaffBillPayment(req.body);
        if ('error' in parsed) return res.status(400).json({ error: parsed.error });

        const client = await pool.connect();
        let payment: any = null;
        let settledRow: any = null;
        try {
            await client.query('BEGIN');
            const billRs = await client.query(
                `SELECT id, total_cents, status FROM table_bills WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
                [id, req.tenantId!]
            );
            if (billRs.rowCount === 0 || !['OPEN', 'LOCKED'].includes(billRs.rows[0].status)) {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'Il conto non è aperto: registra gli incassi dalla chiusura.' });
            }
            const liveRs = await client.query(
                `SELECT COALESCE(SUM(amount_cents), 0)::int AS live
                 FROM table_bill_splits
                 WHERE table_bill_id = $1 AND status IN ('CLAIMED', 'PAID')`,
                [id]
            );
            const staffPaid = await staffPaidCentsForBill(id, client);
            const residual = billRs.rows[0].total_cents - liveRs.rows[0].live - staffPaid;
            if (parsed.amount_cents > residual) {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'Importo oltre il residuo', max_allowed_cents: Math.max(0, residual) });
            }
            const ins = await client.query(
                `INSERT INTO table_bill_payments (tenant_id, table_bill_id, method, amount_cents, meta, recorded_by_user_id)
                 VALUES ($1, $2, $3, $4, $5, $6)
                 RETURNING id, table_bill_id, method, amount_cents, table_bill_split_id,
                           meta, recorded_by_user_id, recorded_at, voided_at, voided_by_user_id, void_reason`,
                [req.tenantId!, id, parsed.method, parsed.amount_cents, parsed.meta ? JSON.stringify(parsed.meta) : null, req.user?.userId ?? null]
            );
            payment = ins.rows[0];
            const settled = await client.query(
                `UPDATE table_bills b SET status = 'SETTLED'
                 WHERE b.id = $1 AND b.status IN ('OPEN', 'LOCKED')
                   AND b.total_cents <= (
                         (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_splits WHERE table_bill_id = $1 AND status = 'PAID')
                       + (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_payments WHERE table_bill_id = $1 AND table_bill_split_id IS NULL AND voided_at IS NULL)
                   )
                 RETURNING id, reservation_id, table_id, total_cents, covers, status`,
                [id]
            );
            settledRow = settled.rows[0] ?? null;
            await client.query('COMMIT');
        } catch (txErr) {
            await client.query('ROLLBACK').catch(() => {});
            throw txErr;
        } finally {
            client.release();
        }

        try {
            socketService?.broadcastToAll(req.tenantId!, 'bill:payment-recorded', { bill_id: id, payment });
            if (settledRow) socketService?.broadcastToAll(req.tenantId!, 'bill:settled', settledRow);
        } catch (_) {}

        const view = await loadBillView(req.tenantId!, id);
        res.status(201).json(view ?? { payment });
    } catch (err: any) {
        console.error('POST /bills/:id/payments error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Storno di un movimento: soft-void, la riga resta a libro con voided_at per
// l'audit. Solo righe staff — lo specchio di una quota online si storna col
// rimborso della quota, non da qui. Se il conto era SETTLED (o già chiuso
// CLOSED) grazie a quel movimento, riapre per la parte stornata.
app.post('/bills/:id/payments/:paymentId/void', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        const paymentId = parseInt(req.params.paymentId, 10);
        if (!Number.isFinite(id) || !Number.isFinite(paymentId)) return res.status(400).json({ error: 'Invalid id' });
        const reason = typeof req.body?.reason === 'string' ? req.body.reason.slice(0, 300) : null;

        const client = await pool.connect();
        let voided: any = null;
        let reopenedRow: any = null;
        try {
            await client.query('BEGIN');
            const billRs = await client.query(
                `SELECT id, total_cents, status FROM table_bills WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
                [id, req.tenantId!]
            );
            if (billRs.rowCount === 0 || billRs.rows[0].status === 'VOIDED') {
                await client.query('ROLLBACK');
                return res.status(404).json({ error: 'Bill not found' });
            }
            const upd = await client.query(
                `UPDATE table_bill_payments
                 SET voided_at = CURRENT_TIMESTAMP, voided_by_user_id = $3, void_reason = $4
                 WHERE id = $1 AND table_bill_id = $2 AND tenant_id = $5
                   AND table_bill_split_id IS NULL AND voided_at IS NULL
                 RETURNING id, table_bill_id, method, amount_cents, table_bill_split_id,
                           meta, recorded_by_user_id, recorded_at, voided_at, voided_by_user_id, void_reason`,
                [paymentId, id, req.user?.userId ?? null, reason, req.tenantId!]
            );
            if (upd.rowCount === 0) {
                await client.query('ROLLBACK');
                return res.status(404).json({ error: 'Movimento non trovato, già stornato o non stornabile' });
            }
            voided = upd.rows[0];

            // Il saldo non regge più? Il conto torna incassabile. Vale anche
            // per un CLOSED riaperto per correzione: torna OPEN e si richiude
            // con i movimenti giusti. cash_settled_cents si riallinea al libro.
            const reopen = await client.query(
                `UPDATE table_bills b
                 SET status = 'OPEN', closed_at = NULL, closed_by_user_id = NULL,
                     cash_settled_cents = (
                         SELECT COALESCE(SUM(amount_cents), 0)::int
                         FROM table_bill_payments
                         WHERE table_bill_id = $1 AND method = 'CONTANTI' AND table_bill_split_id IS NULL AND voided_at IS NULL
                     )
                 WHERE b.id = $1 AND b.status IN ('SETTLED', 'SETTLED_PARTIAL', 'CLOSED')
                   AND b.total_cents > (
                         (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_splits WHERE table_bill_id = $1 AND status = 'PAID')
                       + (SELECT COALESCE(SUM(amount_cents), 0) FROM table_bill_payments WHERE table_bill_id = $1 AND table_bill_split_id IS NULL AND voided_at IS NULL)
                   )
                 RETURNING id, reservation_id, table_id, total_cents, covers, currency,
                           items, status, share_token, opened_at, closed_at,
                           opened_by_user_id, closed_by_user_id, external_ref,
                           cash_settled_cents, tip_cents, notes`,
                [id]
            );
            reopenedRow = reopen.rows[0] ?? null;
            await client.query('COMMIT');
        } catch (txErr) {
            await client.query('ROLLBACK').catch(() => {});
            throw txErr;
        } finally {
            client.release();
        }

        try {
            socketService?.broadcastToAll(req.tenantId!, 'bill:payment-voided', { bill_id: id, payment: voided });
            if (reopenedRow) socketService?.broadcastToAll(req.tenantId!, 'bill:opened', reopenedRow);
        } catch (_) {}

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId, req.user.email, req.user.email,
                ActivityAction.UPDATE, ResourceType.RESERVATION,
                undefined,
                `Stornato incasso ${voided.method} ${formatEuroMinor(voided.amount_cents)} (conto #${id}${reason ? ', motivo: ' + reason : ''})`
            );
        }

        const view = await loadBillView(req.tenantId!, id);
        res.json(view ?? { payment: voided });
    } catch (err: any) {
        console.error('POST /bills/:id/payments/:paymentId/void error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Chiusura di cassa giornaliera: quanto è entrato oggi e da dove. Somma i
// movimenti del giorno (Europe/Rome) per metodo — specchi LINK_ONLINE
// inclusi, storni esclusi — più i dati dei conti chiusi nel giorno: mance,
// acconti maturati, ammanchi dei SETTLED_PARTIAL. È il report che si legge
// a fine serata contando il cassetto.
app.get('/reports/cash-closure', authenticate, requirePermission('payments:view'), async (req, res) => {
    try {
        const raw = typeof req.query.date === 'string' ? req.query.date : '';
        const date = /^\d{4}-\d{2}-\d{2}$/.test(raw) ? raw : getRomeDatePart(new Date());

        const methodsRs = await queryWithRetry(
            `SELECT method, SUM(amount_cents)::int AS amount_cents, COUNT(*)::int AS movements
             FROM table_bill_payments
             WHERE tenant_id = $1 AND voided_at IS NULL
               AND (recorded_at AT TIME ZONE 'Europe/Rome')::date = $2::date
             GROUP BY method
             ORDER BY amount_cents DESC`,
            [req.tenantId!, date]
        );

        const billsRs = await queryWithRetry(
            `SELECT COUNT(*)::int AS bills_closed,
                    COALESCE(SUM(b.tip_cents), 0)::int AS tip_cents,
                    COALESCE(SUM(dep.dep), 0)::int AS deposit_credit_cents,
                    COALESCE(SUM(CASE WHEN b.status = 'SETTLED_PARTIAL'
                        THEN GREATEST(0, b.total_cents - paid.paid - staff.staff) ELSE 0 END), 0)::int AS shortfall_cents
             FROM table_bills b
             LEFT JOIN LATERAL (
                 SELECT COALESCE(SUM(amount_cents), 0)::int AS paid
                 FROM table_bill_splits s WHERE s.table_bill_id = b.id AND s.status = 'PAID'
             ) paid ON TRUE
             LEFT JOIN LATERAL (
                 SELECT COALESCE(SUM(amount_cents), 0)::int AS dep
                 FROM table_bill_splits s WHERE s.table_bill_id = b.id AND s.status = 'PAID' AND s.kind = 'deposit'
             ) dep ON TRUE
             LEFT JOIN LATERAL (
                 SELECT COALESCE(SUM(amount_cents), 0)::int AS staff
                 FROM table_bill_payments p WHERE p.table_bill_id = b.id AND p.table_bill_split_id IS NULL AND p.voided_at IS NULL
             ) staff ON TRUE
             WHERE b.tenant_id = $1 AND b.status IN ('CLOSED', 'SETTLED_PARTIAL')
               AND b.closed_at IS NOT NULL
               AND (b.closed_at AT TIME ZONE 'Europe/Rome')::date = $2::date`,
            [req.tenantId!, date]
        );

        // Dettaglio per tavolo: un conto per riga con documento fiscale e
        // incassi, così la chiusura serale si riscontra tavolo per tavolo e
        // si filtra per tipo di chiusura (scontrino/fattura/proforma/senza).
        const billListRs = await queryWithRetry(
            `SELECT b.id, b.total_cents, b.status, b.tip_cents, b.closed_at, b.covers,
                    t.name AS table_name, r.customer_name,
                    -- Turno del conto (dalla comanda, o dedotto dall'apertura
                    -- come in /bills/open): lo stesso tavolo serve pranzo e
                    -- cena, senza turno le righe del giorno si confondono.
                    COALESCE(
                        (SELECT o.shift FROM orders o WHERE o.table_bill_id = b.id ORDER BY o.id LIMIT 1),
                        CASE WHEN EXTRACT(hour FROM (b.opened_at AT TIME ZONE 'Europe/Rome')) BETWEEN 5 AND 16
                             THEN 'LUNCH' ELSE 'DINNER' END
                    ) AS shift,
                    fd.doc_type AS fiscal_doc_type, fd.status AS fiscal_status, fd.doc_number AS fiscal_doc_number,
                    fd.public_token AS fiscal_public_token, fd.provider AS fiscal_provider,
                    COALESCE((SELECT jsonb_agg(jsonb_build_object('method', p.method, 'amount_cents', p.amount_cents) ORDER BY p.recorded_at)
                              FROM table_bill_payments p
                              WHERE p.table_bill_id = b.id AND p.voided_at IS NULL), '[]'::jsonb) AS payments
             FROM table_bills b
             LEFT JOIN tables t ON t.id = b.table_id AND t.tenant_id = b.tenant_id
             LEFT JOIN reservations r ON r.id = b.reservation_id AND r.tenant_id = b.tenant_id
             LEFT JOIN LATERAL (
                 SELECT doc_type, status, doc_number, public_token, provider FROM fiscal_documents
                 WHERE table_bill_id = b.id ORDER BY created_at DESC LIMIT 1
             ) fd ON TRUE
             WHERE b.tenant_id = $1 AND b.status IN ('CLOSED', 'SETTLED_PARTIAL')
               AND b.closed_at IS NOT NULL
               AND (b.closed_at AT TIME ZONE 'Europe/Rome')::date = $2::date
             ORDER BY b.closed_at DESC`,
            [req.tenantId!, date]
        );

        const methods = methodsRs.rows;
        res.json({
            date,
            methods,
            total_cents: methods.reduce((n: number, m: any) => n + m.amount_cents, 0),
            tip_cents: billsRs.rows[0].tip_cents,
            deposit_credit_cents: billsRs.rows[0].deposit_credit_cents,
            bills_closed: billsRs.rows[0].bills_closed,
            shortfall_cents: billsRs.rows[0].shortfall_cents,
            bills: billListRs.rows,
        });
    } catch (err: any) {
        console.error('GET /reports/cash-closure error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// --- Reportistica fiscale (vista Fiscalità) ----------------------------------
// Registro documenti per periodo + corrispettivi per aliquota, per le
// interrogazioni del ristoratore e gli export al commercialista. Permesso
// dedicato fiscal:view: di default ce l'ha il solo titolare, che lo concede
// per ruolo dalla matrice permessi (Utenti) — né payments:view (cassa del
// giorno) né reports:view (report operativi).
//
// Periodo su created_at: è l'unico timestamp indicizzato ((tenant_id,
// created_at)), fiscalmente il documento nasce contestualmente all'emissione,
// e FAILED/PENDING (confirmed_at NULL) devono comunque comparire nel
// registro. Bound sargabili — la forma "(x AT TIME ZONE ...)::date = $2" di
// cash-closure va bene su UN giorno ma butta l'indice su un trimestre.

const parseFiscalPeriod = (req: any): { from: string; to: string } | null => {
    const from = typeof req.query.from === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(req.query.from) ? req.query.from : null;
    const to = typeof req.query.to === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(req.query.to) ? req.query.to : null;
    if (!from || !to || from > to) return null;
    // Cap difensivo: ~400 giorni coprono l'anno fiscale con margine; oltre,
    // l'aggregato jsonb del vat-summary diventa un lavoro da batch.
    const days = (Date.parse(to) - Date.parse(from)) / 86_400_000;
    if (days > 400) return null;
    return { from, to };
};

// WHERE di periodo (parametri $2=from, $3=to sul tenant $1). date::timestamp
// AT TIME ZONE 'Europe/Rome' = l'istante UTC della mezzanotte di Roma.
const FISCAL_PERIOD_WHERE = `fd.tenant_id = $1
    AND fd.created_at >= ($2::date::timestamp AT TIME ZONE 'Europe/Rome')
    AND fd.created_at < (($3::date + 1)::timestamp AT TIME ZONE 'Europe/Rome')`;

const csvCell = (v: unknown): string => `"${String(v ?? '').replace(/"/g, '""')}"`;
const sendCsv = (res: any, filename: string, rows: unknown[][]) => {
    const csv = rows.map(r => r.map(csvCell).join(',')).join('\n');
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    // BOM: senza, Excel legge gli accenti come mojibake (stesso pattern
    // dell'export marketing client-side).
    res.send('\uFEFF' + csv);
};

const FISCAL_TYPE_LABEL: Record<string, string> = {
    RECEIPT: 'scontrino', INVOICE: 'fattura', CREDIT_NOTE: 'nota di credito', PROFORMA: 'proforma',
};

app.get('/reports/fiscal-registry', authenticate, requirePermission('fiscal:view'), async (req, res) => {
    try {
        const period = parseFiscalPeriod(req);
        if (!period) return res.status(400).json({ error: 'invalid_period', message: 'Servono from e to (YYYY-MM-DD), massimo 400 giorni' });
        const docType = typeof req.query.doc_type === 'string' && ['RECEIPT', 'INVOICE', 'CREDIT_NOTE', 'PROFORMA'].includes(req.query.doc_type) ? req.query.doc_type : null;
        const status = typeof req.query.status === 'string' && ['PENDING', 'CONFIRMED', 'FAILED', 'VOIDED'].includes(req.query.status) ? req.query.status : null;
        const wantCsv = req.query.format === 'csv';
        const limit = Math.min(500, Math.max(1, parseInt(String(req.query.limit ?? '200'), 10) || 200));
        const offset = Math.max(0, parseInt(String(req.query.offset ?? '0'), 10) || 0);

        const params: any[] = [req.tenantId!, period.from, period.to];
        let filters = '';
        if (docType) { params.push(docType); filters += ` AND fd.doc_type = $${params.length}`; }
        if (status) { params.push(status); filters += ` AND fd.status = $${params.length}`; }

        // Totali e conteggi sull'INTERO periodo (i KPI e i chip non devono
        // cambiare quando la lista pagina). Semantica — la parte delicata:
        //  - documentato = scontrini CONFIRMED + fatture CONFIRMED − note di
        //    credito CONFIRMED; la proforma (provider 'crm') NON è un
        //    documento fiscale e resta fuori, mostrata a parte;
        //  - VOIDED e FAILED fuori dai totali;
        //  - la fattura VOIDED per storno si riconosce dalla NC che la punta
        //    (related_doc_id), distinta dallo scontrino VOIDED (annullo al
        //    provider, ha voided_at).
        const totalsRs = await queryWithRetry(
            `SELECT fd.doc_type, fd.status, COUNT(*)::int AS count, COALESCE(SUM(fd.total_cents), 0)::bigint AS total_cents
             FROM fiscal_documents fd
             WHERE ${FISCAL_PERIOD_WHERE}
             GROUP BY fd.doc_type, fd.status`,
            [req.tenantId!, period.from, period.to]
        );
        const bucket = (type: string, st: string) => {
            const r = totalsRs.rows.find((x: any) => x.doc_type === type && x.status === st);
            return { count: r?.count ?? 0, total_cents: Number(r?.total_cents ?? 0) };
        };
        const receipts = bucket('RECEIPT', 'CONFIRMED');
        const invoices = bucket('INVOICE', 'CONFIRMED');
        const creditNotes = bucket('CREDIT_NOTE', 'CONFIRMED');
        const sumBy = (pred: (r: any) => boolean, field: 'count' | 'total_cents') =>
            totalsRs.rows.filter(pred).reduce((n: number, r: any) => n + Number(r[field]), 0);
        const totals = {
            documented_total_cents: receipts.total_cents + invoices.total_cents - creditNotes.total_cents,
            receipts, invoices, credit_notes: creditNotes,
            proforma: { count: sumBy(r => r.doc_type === 'PROFORMA', 'count'), total_cents: sumBy(r => r.doc_type === 'PROFORMA', 'total_cents') },
            voided_count: sumBy(r => r.status === 'VOIDED', 'count'),
            failed_count: sumBy(r => r.status === 'FAILED', 'count'),
            pending_count: sumBy(r => r.status === 'PENDING', 'count'),
        };
        const counts = {
            all: sumBy(() => true, 'count'),
            receipt: sumBy(r => r.doc_type === 'RECEIPT', 'count'),
            invoice: sumBy(r => r.doc_type === 'INVOICE', 'count'),
            credit_note: sumBy(r => r.doc_type === 'CREDIT_NOTE', 'count'),
            proforma: sumBy(r => r.doc_type === 'PROFORMA', 'count'),
            voided: sumBy(r => r.status === 'VOIDED', 'count'),
            failed: sumBy(r => r.status === 'FAILED', 'count'),
        };

        const rowsSql = `
            SELECT fd.id, fd.doc_type, fd.provider, fd.status, fd.doc_number, fd.provider_ref,
                   fd.total_cents, fd.created_at, fd.confirmed_at, fd.voided_at, fd.public_token,
                   fd.related_doc_id, fd.table_bill_id,
                   (fd.created_at AT TIME ZONE 'Europe/Rome')::date AS day,
                   t.name AS table_name, r.customer_name,
                   nc.doc_number AS credit_note_number
            FROM fiscal_documents fd
            LEFT JOIN table_bills b ON b.id = fd.table_bill_id AND b.tenant_id = fd.tenant_id
            LEFT JOIN tables t ON t.id = b.table_id AND t.tenant_id = b.tenant_id
            LEFT JOIN reservations r ON r.id = b.reservation_id AND r.tenant_id = b.tenant_id
            LEFT JOIN fiscal_documents nc ON nc.related_doc_id = fd.id AND nc.doc_type = 'CREDIT_NOTE'
                 AND nc.status = 'CONFIRMED' AND nc.tenant_id = fd.tenant_id
            WHERE ${FISCAL_PERIOD_WHERE}${filters}
            ORDER BY fd.created_at DESC`;

        if (wantCsv) {
            // Il CSV va al commercialista: COMPLETO, la paginazione della
            // vista non lo riguarda. Qualche migliaio di righe sta in
            // memoria; se un giorno servirà il multi-anno, cursor.
            const all = await queryWithRetry(rowsSql, params);
            const statusLabel = (row: any) =>
                row.status === 'CONFIRMED' ? 'emesso'
                : row.status === 'VOIDED' ? (row.credit_note_number ? `stornata da NC ${row.credit_note_number}` : 'annullato')
                : row.status === 'FAILED' ? 'errore'
                : 'in corso';
            sendCsv(res, `registro-documenti-${period.from}_${period.to}.csv`, [
                ['data', 'ora', 'tipo', 'numero', 'stato', 'totale', 'provider', 'riferimento provider', 'tavolo', 'cliente', 'conto'],
                ...all.rows.map((row: any) => [
                    getRomeDatePart(row.created_at), getRomeTimePart(row.created_at),
                    FISCAL_TYPE_LABEL[row.doc_type] ?? row.doc_type,
                    row.doc_number ?? '', statusLabel(row),
                    (row.total_cents / 100).toFixed(2).replace('.', ','),
                    row.provider, row.provider_ref ?? '',
                    row.table_name ?? '', row.customer_name ?? '', row.table_bill_id ?? '',
                ]),
            ]);
            return;
        }

        const pageParams = [...params, limit, offset];
        const page = await queryWithRetry(`${rowsSql} LIMIT $${params.length + 1} OFFSET $${params.length + 2}`, pageParams);
        const countRs = await queryWithRetry(
            `SELECT COUNT(*)::int AS n FROM fiscal_documents fd WHERE ${FISCAL_PERIOD_WHERE}${filters}`, params
        );
        res.json({ from: period.from, to: period.to, totals, counts, documents: page.rows, total_count: countRs.rows[0].n });
    } catch (err: any) {
        console.error('GET /reports/fiscal-registry error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Corrispettivi per aliquota: il dato per la liquidazione IVA, ricavato dai
// payload TRASMESSI (request.items) — la stessa verità che ha l'AdE. Solo
// scontrini CONFIRMED: gli annullati escono, fatture e NC non sono
// corrispettivi. Aggregazione in SQL (jsonb_array_elements): per giorno ×
// aliquota viaggiano decine di righe, non i payload interi.
app.get('/reports/fiscal-vat-summary', authenticate, requirePermission('fiscal:view'), async (req, res) => {
    try {
        const period = parseFiscalPeriod(req);
        if (!period) return res.status(400).json({ error: 'invalid_period', message: 'Servono from e to (YYYY-MM-DD), massimo 400 giorni' });
        const params = [req.tenantId!, period.from, period.to];

        const rowsRs = await queryWithRetry(
            `SELECT (fd.created_at AT TIME ZONE 'Europe/Rome')::date AS day,
                    i->>'vat_rate_code' AS vat_rate_code,
                    SUM(ROUND((i->>'unit_price')::numeric * (i->>'quantity')::numeric * 100))::bigint AS gross_cents,
                    COUNT(DISTINCT fd.id)::int AS docs
             FROM fiscal_documents fd
             CROSS JOIN LATERAL jsonb_array_elements(fd.request->'items') AS i
             WHERE ${FISCAL_PERIOD_WHERE}
               AND fd.doc_type = 'RECEIPT' AND fd.status = 'CONFIRMED'
               AND fd.request IS NOT NULL AND jsonb_typeof(fd.request->'items') = 'array'
             GROUP BY 1, 2 ORDER BY 1, 2`,
            params
        );
        // Sconto globale (sconti comanda + omaggi): riduce il documentato ma
        // non è attribuibile per aliquota — colonna a parte, per giorno.
        const discountRs = await queryWithRetry(
            `SELECT (fd.created_at AT TIME ZONE 'Europe/Rome')::date AS day,
                    SUM(ROUND(COALESCE((fd.request->>'discount')::numeric, 0) * 100))::bigint AS discount_cents
             FROM fiscal_documents fd
             WHERE ${FISCAL_PERIOD_WHERE}
               AND fd.doc_type = 'RECEIPT' AND fd.status = 'CONFIRMED' AND fd.request IS NOT NULL
             GROUP BY 1 HAVING SUM(ROUND(COALESCE((fd.request->>'discount')::numeric, 0) * 100)) > 0`,
            params
        );
        // Scontrini emessi dall'RT di cassa (Passepartout): request NULL, i
        // loro corrispettivi vivono nel registratore — esclusi con conteggio,
        // mai sommati in silenzio.
        const excludedRs = await queryWithRetry(
            `SELECT COUNT(*)::int AS docs, COALESCE(SUM(fd.total_cents), 0)::bigint AS total_cents
             FROM fiscal_documents fd
             WHERE ${FISCAL_PERIOD_WHERE}
               AND fd.doc_type = 'RECEIPT' AND fd.status = 'CONFIRMED' AND fd.provider IN ('passepartout', 'external_rt')`,
            params
        );

        // Scorporo in Node: codice numerico → imponibile = lordo/(1+aliquota);
        // natura (N2, N2.2, ...) → imposta zero, chiave separata così N2 e
        // N2.2 non si mischiano mai.
        const rows = rowsRs.rows.map((row: any) => {
            const gross = Number(row.gross_cents);
            const numeric = /^\d/.test(String(row.vat_rate_code));
            const rate = numeric ? parseFloat(row.vat_rate_code) : null;
            const net = rate != null ? Math.round(gross / (1 + rate / 100)) : gross;
            return {
                day: row.day, vat_rate_code: row.vat_rate_code, is_nature: !numeric,
                gross_cents: gross, net_cents: net, tax_cents: rate != null ? gross - net : 0, docs: row.docs,
            };
        });
        const excluded = { passepartout_docs: excludedRs.rows[0].docs, passepartout_total_cents: Number(excludedRs.rows[0].total_cents) };
        const discounts = discountRs.rows.map((row: any) => ({ day: row.day, discount_cents: Number(row.discount_cents) }));

        if (req.query.format === 'csv') {
            const vatLabel = (code: string, nature: boolean) => nature ? `natura ${code}` : `iva ${code.replace('.', ',')}%`;
            const eur = (c: number) => (c / 100).toFixed(2).replace('.', ',');
            sendCsv(res, `corrispettivi-iva-${period.from}_${period.to}.csv`, [
                ['giorno', 'aliquota/natura', 'imponibile', 'imposta', 'lordo', 'documenti'],
                ...rows.map(row => [row.day, vatLabel(row.vat_rate_code, row.is_nature), eur(row.net_cents), eur(row.tax_cents), eur(row.gross_cents), row.docs]),
                ...discounts.map(d => [d.day, 'sconti e omaggi (fuori riparto)', '', '', '-' + eur(d.discount_cents), '']),
                ...(excluded.passepartout_docs > 0
                    ? [['', `scontrini dall'RT di cassa esclusi: ${excluded.passepartout_docs}`, '', '', eur(excluded.passepartout_total_cents), '']]
                    : []),
            ]);
            return;
        }
        res.json({ from: period.from, to: period.to, rows, discounts, excluded });
    } catch (err: any) {
        console.error('GET /reports/fiscal-vat-summary error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Drill-down di un documento del registro: la riga completa più le righe
// articolo parsate dal payload trasmesso (stessa conversione euro→cents
// della pagina pubblica /scontrino/:token) e il documento correlato.
app.get('/reports/fiscal-documents/:id', authenticate, requirePermission('fiscal:view'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });
        const rs = await queryWithRetry(
            `SELECT fd.id, fd.doc_type, fd.provider, fd.status, fd.doc_number, fd.provider_ref,
                    fd.total_cents, fd.fiscal_id_snapshot, fd.request, fd.response, fd.error,
                    fd.created_at, fd.confirmed_at, fd.voided_at, fd.public_token,
                    fd.related_doc_id, fd.table_bill_id, fd.table_bill_split_id,
                    t.name AS table_name, r.customer_name, b.closed_at AS bill_closed_at,
                    rel.doc_type AS related_doc_type, rel.doc_number AS related_doc_number,
                    nc.doc_number AS credit_note_number
             FROM fiscal_documents fd
             LEFT JOIN table_bills b ON b.id = fd.table_bill_id AND b.tenant_id = fd.tenant_id
             LEFT JOIN tables t ON t.id = b.table_id AND t.tenant_id = b.tenant_id
             LEFT JOIN reservations r ON r.id = b.reservation_id AND r.tenant_id = b.tenant_id
             LEFT JOIN fiscal_documents rel ON rel.id = fd.related_doc_id AND rel.tenant_id = fd.tenant_id
             LEFT JOIN fiscal_documents nc ON nc.related_doc_id = fd.id AND nc.doc_type = 'CREDIT_NOTE'
                  AND nc.status = 'CONFIRMED' AND nc.tenant_id = fd.tenant_id
             WHERE fd.id = $1 AND fd.tenant_id = $2`,
            [id, req.tenantId!]
        );
        const doc = rs.rows[0];
        if (!doc) return res.status(404).json({ error: 'Documento non trovato' });
        const payload = doc.request ?? {};
        const euroToCents = (s: unknown): number => Math.round((parseFloat(String(s ?? '0')) || 0) * 100);
        res.json({
            document: {
                id: doc.id, doc_type: doc.doc_type, provider: doc.provider, status: doc.status,
                doc_number: doc.doc_number, provider_ref: doc.provider_ref, total_cents: doc.total_cents,
                fiscal_id: doc.fiscal_id_snapshot, error: doc.error,
                created_at: doc.created_at, confirmed_at: doc.confirmed_at, voided_at: doc.voided_at,
                public_token: doc.public_token, table_bill_id: doc.table_bill_id,
                table_name: doc.table_name, customer_name: doc.customer_name, bill_closed_at: doc.bill_closed_at,
                related: doc.related_doc_id ? { id: doc.related_doc_id, doc_type: doc.related_doc_type, doc_number: doc.related_doc_number } : null,
                credit_note_number: doc.credit_note_number,
            },
            items: (Array.isArray(payload.items) ? payload.items : []).map((i: any) => ({
                description: String(i.description ?? ''),
                quantity: parseFloat(String(i.quantity ?? '1')) || 1,
                unit_price_cents: euroToCents(i.unit_price),
                vat_rate_code: String(i.vat_rate_code ?? ''),
            })),
            payments: {
                cash_cents: euroToCents(payload.cash_payment_amount),
                electronic_cents: euroToCents(payload.electronic_payment_amount),
                ticket_cents: euroToCents(payload.ticket_restaurant_payment_amount),
                uncollected_cents: euroToCents(payload.services_uncollected_amount),
                discount_cents: euroToCents(payload.discount),
            },
        });
    } catch (err: any) {
        console.error('GET /reports/fiscal-documents/:id error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// ============================================
// DOCUMENTI FISCALI — documento commerciale (fase 3 fatturazione)
// ============================================
// Il driver (Openapi sandbox / mock) e il payload builder stanno in
// services/fiscalService.ts; qui vivono persistenza, idempotenza e flusso.
// Regola del piano: la trasmissione non blocca MAI l'operatività — il conto
// chiude comunque, il documento resta PENDING/FAILED da ritentare.

const FISCAL_PROVIDER_KEY = 'fiscal_provider';
const FISCAL_VAT_NUMBER_KEY = 'fiscal_vat_number';
const FISCAL_PROVIDERS = ['none', 'openapi', 'mock', 'rt-local'] as const;

async function getFiscalProviderSetting(tenantId: number): Promise<string> {
    try {
        const r = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, FISCAL_PROVIDER_KEY]
        );
        const raw = r.rows[0]?.text_value;
        return (FISCAL_PROVIDERS as readonly string[]).includes(raw) ? raw : 'none';
    } catch (err) {
        console.error('[fiscal] lettura provider fallita:', (err as any)?.message);
        return 'none';
    }
}

async function getFiscalVatNumber(tenantId: number): Promise<string> {
    try {
        const r = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, FISCAL_VAT_NUMBER_KEY]
        );
        return typeof r.rows[0]?.text_value === 'string' ? r.rows[0].text_value : '';
    } catch (_) {
        return '';
    }
}

// Dati del cedente per la fattura (denominazione, regime, sede): blob JSON
// in app_settings. Il regime di default è RF01 (ordinario).
const FISCAL_SELLER_KEY = 'fiscal_seller';
type FiscalSellerSetting = { business_name?: string; regime?: string; address?: { street?: string; zip?: string; city?: string; province?: string } };

async function getFiscalSellerSetting(tenantId: number): Promise<FiscalSellerSetting> {
    try {
        const r = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, FISCAL_SELLER_KEY]
        );
        const raw = r.rows[0]?.text_value;
        const parsed = typeof raw === 'string' ? JSON.parse(raw) : null;
        return parsed && typeof parsed === 'object' ? parsed : {};
    } catch (_) {
        return {};
    }
}

// Mappatura IVA del tenant: aliquota di default dei nuovi piatti e aliquote
// delle voci di sistema (coperto, servizio, riga "Consumazione" dei conti
// senza righe). Blob JSON in app_settings; il 10 di somministrazione resta
// il fallback di ogni campo. Gli sconti NON stanno qui: riducono
// l'imponibile delle righe su cui cadono, non hanno un'aliquota propria.
const FISCAL_VAT_MAP_KEY = 'fiscal_vat_map';
type FiscalVatMap = { dish_default: number; cover: number; service: number; fallback: number };
const FISCAL_VAT_MAP_DEFAULTS: FiscalVatMap = { dish_default: 10, cover: 10, service: 10, fallback: 10 };

async function getFiscalVatMap(tenantId: number): Promise<FiscalVatMap> {
    try {
        const r = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, FISCAL_VAT_MAP_KEY]
        );
        const raw = r.rows[0]?.text_value;
        const parsed = typeof raw === 'string' ? JSON.parse(raw) : null;
        const norm = (v: any, dflt: number) => {
            const n = Number(v);
            return Number.isInteger(n) && n >= 0 && n <= 100 ? n : dflt;
        };
        return {
            dish_default: norm(parsed?.dish_default, FISCAL_VAT_MAP_DEFAULTS.dish_default),
            cover: norm(parsed?.cover, FISCAL_VAT_MAP_DEFAULTS.cover),
            service: norm(parsed?.service, FISCAL_VAT_MAP_DEFAULTS.service),
            fallback: norm(parsed?.fallback, FISCAL_VAT_MAP_DEFAULTS.fallback),
        };
    } catch (_) {
        return { ...FISCAL_VAT_MAP_DEFAULTS };
    }
}

// Cedente completo o l'elenco di cosa manca: la fattura non parte con i
// dati a metà, e il messaggio d'errore deve dire COSA compilare.
async function resolveFiscalSeller(tenantId: number): Promise<{ seller: FiscalSeller } | { missing: string[] }> {
    const vat = await getFiscalVatNumber(tenantId);
    const s = await getFiscalSellerSetting(tenantId);
    const missing: string[] = [];
    if (!vat) missing.push('P.IVA');
    if (!s.business_name?.trim()) missing.push('denominazione');
    if (!s.address?.street?.trim()) missing.push('indirizzo');
    if (!s.address?.zip?.trim()) missing.push('CAP');
    if (!s.address?.city?.trim()) missing.push('comune');
    if (missing.length > 0) return { missing };
    return {
        seller: {
            vat_number: vat,
            business_name: s.business_name!.trim(),
            regime: s.regime?.trim() || 'RF01',
            address: {
                street: s.address!.street!.trim(),
                zip: s.address!.zip!.trim(),
                city: s.address!.city!.trim(),
                province: s.address?.province?.trim() || undefined,
            },
        },
    };
}

// Prossimo numero fattura del tenant per l'anno: contatore dedicato sotto
// lock di riga — MAX+1 senza lock produce doppioni, e il numero fattura è
// un obbligo di legge. Formato "N/ANNO".
async function nextInvoiceNumber(tenantId: number, year: number): Promise<string> {
    const r = await queryWithRetry(
        `INSERT INTO invoice_counters (tenant_id, year, last_number)
         VALUES ($1, $2, 1)
         ON CONFLICT (tenant_id, year)
         DO UPDATE SET last_number = invoice_counters.last_number + 1
         RETURNING last_number`,
        [tenantId, year]
    );
    return `${r.rows[0].last_number}/${year}`;
}

const FISCAL_DOC_COLUMNS = `id, table_bill_id, table_bill_split_id, doc_type, doc_number, provider, fiscal_id_snapshot, status,
    provider_ref, error, total_cents, attempts, created_by_user_id, created_at, confirmed_at, voided_at, public_token`;

// Il token che l'ospite riceve nel QR: una capability sul singolo documento,
// come lo share_token del conto (che però muore alla chiusura — questo no,
// lo scontrino si mostra anche il giorno dopo).
const newFiscalPublicToken = () => crypto.randomBytes(32).toString('hex');

// Chiusura proforma di un conto NATIVO (fuori Passepartout): nessun
// documento fiscale, ma la scelta resta scritta come riga PROFORMA
// (provider 'crm'). È un segnaposto, non un atto fiscale: chi emette
// scontrino o fattura dopo la supera automaticamente (VOIDED).
async function registerNativeProforma(tenantId: number, billId: number, userId: number | null): Promise<{ doc?: any; skipped?: string }> {
    const billRs = await queryWithRetry(
        `SELECT id, total_cents, status, external_ref FROM table_bills WHERE id = $1 AND tenant_id = $2`,
        [billId, tenantId]
    );
    const bill = billRs.rows[0];
    if (!bill || bill.status !== 'CLOSED') return { skipped: 'bill_not_closed' };
    if (passepartoutComandaIdFromRef(bill.external_ref) != null) return { skipped: 'passepartout' }; // il PP ha la sua proforma di cassa
    const ins = await queryWithRetry(
        `INSERT INTO fiscal_documents (tenant_id, table_bill_id, doc_type, provider, status, total_cents, created_by_user_id, confirmed_at)
         VALUES ($1, $2, 'PROFORMA', 'crm', 'CONFIRMED', $3, $4, CURRENT_TIMESTAMP)
         ON CONFLICT (table_bill_id) WHERE status IN ('PENDING', 'CONFIRMED') AND table_bill_split_id IS NULL AND doc_type <> 'CREDIT_NOTE' DO NOTHING
         RETURNING ${FISCAL_DOC_COLUMNS}`,
        [tenantId, billId, bill.total_cents, userId]
    );
    if (!ins.rows[0]) return { skipped: 'doc_exists' };
    try { socketService?.broadcastToAll(tenantId, 'fiscal:updated', { bill_id: billId, doc: ins.rows[0] }); } catch (_) {}
    return { doc: ins.rows[0] };
}

// Scontrino battuto a mano sull'RT di cassa su un conto NATIVO (periodo
// ponte: comande nel CRM, fiscale ancora sul registratore). A differenza
// della proforma È un documento fiscale — provider 'external_rt', numero
// del registratore in doc_number — e sta nei totali documentati come i
// receipt Passepartout. Supera l'eventuale proforma segnaposto.
async function registerExternalRtReceipt(tenantId: number, billId: number, userId: number | null, docNumber: string | null): Promise<{ doc?: any; skipped?: string }> {
    const billRs = await queryWithRetry(
        `SELECT id, total_cents, status, external_ref FROM table_bills WHERE id = $1 AND tenant_id = $2`,
        [billId, tenantId]
    );
    const bill = billRs.rows[0];
    if (!bill || bill.status !== 'CLOSED') return { skipped: 'bill_not_closed' };
    if (passepartoutComandaIdFromRef(bill.external_ref) != null) return { skipped: 'passepartout' }; // il bridge registra da solo l'esito della cassa
    await supersedeNativeProforma(tenantId, billId);
    const ins = await queryWithRetry(
        `INSERT INTO fiscal_documents (tenant_id, table_bill_id, doc_type, provider, status, doc_number, total_cents, created_by_user_id, confirmed_at)
         VALUES ($1, $2, 'RECEIPT', 'external_rt', 'CONFIRMED', $5, $3, $4, CURRENT_TIMESTAMP)
         ON CONFLICT (table_bill_id) WHERE status IN ('PENDING', 'CONFIRMED') AND table_bill_split_id IS NULL AND doc_type <> 'CREDIT_NOTE' DO NOTHING
         RETURNING ${FISCAL_DOC_COLUMNS}`,
        [tenantId, billId, bill.total_cents, userId, docNumber]
    );
    if (!ins.rows[0]) return { skipped: 'doc_exists' };
    try { socketService?.broadcastToAll(tenantId, 'fiscal:updated', { bill_id: billId, doc: ins.rows[0] }); } catch (_) {}
    return { doc: ins.rows[0] };
}

// La proforma nativa cede il posto al documento vero: VOID del segnaposto
// vivo (se c'è) prima di emettere scontrino o fattura. Ritorna true se
// qualcosa è stato superato — chi chiama può ricalcolare le guardie.
async function supersedeNativeProforma(tenantId: number, billId: number): Promise<boolean> {
    const upd = await queryWithRetry(
        `UPDATE fiscal_documents
         SET status = 'VOIDED', voided_at = CURRENT_TIMESTAMP
         WHERE table_bill_id = $1 AND tenant_id = $2 AND doc_type = 'PROFORMA' AND provider = 'crm'
           AND table_bill_split_id IS NULL AND status IN ('PENDING', 'CONFIRMED')
         RETURNING id`,
        [billId, tenantId]
    );
    return (upd.rowCount ?? 0) > 0;
}

// Emissione del documento commerciale per un conto CHIUSO. Idempotente:
// l'indice unico ammette un documento vivo per conto — il replay ritorna il
// CONFIRMED esistente, il retry riusa il PENDING, un FAILED lascia spazio a
// un tentativo nuovo. Chiamata fire-and-forget dalla chiusura e in modo
// esplicito da POST /bills/:id/fiscal-docs.
async function emitFiscalDocForBill(tenantId: number, billId: number, userId: number | null): Promise<{ doc?: any; skipped?: string }> {
    const providerName = await getFiscalProviderSetting(tenantId);
    if (providerName === 'none') return { skipped: 'not_configured' };
    const fiscalId = await getFiscalVatNumber(tenantId);
    if (!fiscalId) return { skipped: 'missing_vat_number' };

    const billRs = await queryWithRetry(
        `SELECT id, total_cents, items, status, external_ref, lottery_code FROM table_bills WHERE id = $1 AND tenant_id = $2`,
        [billId, tenantId]
    );
    const bill = billRs.rows[0];
    // Solo conti CLOSED (saldati per intero): un SETTLED_PARTIAL ha un
    // ammanco che non quadrerebbe col documento.
    if (!bill || bill.status !== 'CLOSED') return { skipped: 'bill_not_closed' };
    // Conto nato da una comanda Passepartout: il documento fiscale lo emette
    // il gestionale (RT di cassa) alla chiusura comanda — emetterlo anche via
    // Openapi farebbe due documenti per lo stesso incasso.
    if (passepartoutComandaIdFromRef(bill.external_ref) != null) return { skipped: 'passepartout' };

    // Un solo binario fiscale: se sul conto vive una fattura (sull'intero o
    // su una quota), lo scontrino non parte — sarebbe un secondo documento
    // sullo stesso importo. L'indice unico copre solo il livello conto,
    // quindi la fattura su quota va controllata qui.
    const liveInvoices = await queryWithRetry(
        `SELECT 1 FROM fiscal_documents
         WHERE table_bill_id = $1 AND doc_type = 'INVOICE' AND status IN ('PENDING', 'CONFIRMED')
         LIMIT 1`,
        [billId]
    );
    if ((liveInvoices.rowCount ?? 0) > 0) return { skipped: 'invoice_exists' };

    // La proforma nativa è un segnaposto: lo scontrino vero la supera.
    await supersedeNativeProforma(tenantId, billId);

    let ins = await queryWithRetry(
        // Arbitro sull'indice a livello conto (predicato con split IS NULL,
        // vedi migration fattura-elettronica che ha sdoppiato l'indice).
        `INSERT INTO fiscal_documents (tenant_id, table_bill_id, provider, fiscal_id_snapshot, total_cents, created_by_user_id, public_token)
         VALUES ($1, $2, $3, $4, $5, $6, $7)
         ON CONFLICT (table_bill_id) WHERE status IN ('PENDING', 'CONFIRMED') AND table_bill_split_id IS NULL AND doc_type <> 'CREDIT_NOTE' DO NOTHING
         RETURNING ${FISCAL_DOC_COLUMNS}`,
        [tenantId, billId, providerName, fiscalId, bill.total_cents, userId, newFiscalPublicToken()]
    );
    let doc = ins.rows[0] ?? null;
    if (!doc) {
        const existing = await queryWithRetry(
            `SELECT ${FISCAL_DOC_COLUMNS} FROM fiscal_documents
             WHERE table_bill_id = $1 AND tenant_id = $2 AND status IN ('PENDING', 'CONFIRMED')
               AND doc_type <> 'CREDIT_NOTE'
             LIMIT 1`,
            [billId, tenantId]
        );
        doc = existing.rows[0] ?? null;
        if (!doc) return { skipped: 'race' };
        if (doc.status === 'CONFIRMED') return { doc };
    }

    // Incassi attivi (specchi LINK_ONLINE inclusi) + acconto: sono i numeri
    // che devono quadrare col totale delle righe nel documento.
    const paymentsRs = await queryWithRetry(
        `SELECT method, amount_cents, meta FROM table_bill_payments
         WHERE table_bill_id = $1 AND voided_at IS NULL`,
        [billId]
    );
    const depositRs = await queryWithRetry(
        `SELECT COALESCE(SUM(amount_cents), 0)::int AS s FROM table_bill_splits
         WHERE table_bill_id = $1 AND status = 'PAID' AND kind = 'deposit'`,
        [billId]
    );

    const payload = buildEReceiptPayload({
        fiscalId,
        totalCents: bill.total_cents,
        items: Array.isArray(bill.items) ? bill.items : null,
        payments: paymentsRs.rows,
        depositCreditCents: depositRs.rows[0].s,
        fallbackVatRate: (await getFiscalVatMap(tenantId)).fallback,
        lotteryCode: bill.lottery_code ?? null,
    });

    // Claim atomico del tentativo: emissione automatica (post-chiusura) e
    // POST manuale possono correre sulla stessa riga PENDING, e senza questo
    // guard ENTRAMBE chiamerebbero il provider — due scontrini reali per lo
    // stesso conto (successo davvero nella prova sandbox del 24/08). Vince
    // chi bumpa attempts per primo; l'altro esce con 'in_progress'. Un
    // PENDING orfano di un processo morto resta reclamabile: il retry vede
    // gli attempts correnti e passa.
    const claim = await queryWithRetry(
        `UPDATE fiscal_documents SET attempts = attempts + 1, request = $2::jsonb
         WHERE id = $1 AND status = 'PENDING' AND attempts = $3
         RETURNING id`,
        [doc.id, JSON.stringify(payload), doc.attempts]
    );
    if ((claim.rowCount ?? 0) === 0) return { skipped: 'in_progress' };

    // rt-local: l'RT Epson sta nella LAN del ristorante, il backend no —
    // in mezzo c'è la coda dell'agente di stampa. Il documento resta
    // PENDING; l'ack del job (kind RT_FISCALE) lo porta a CONFIRMED col
    // numero del registratore, o a FAILED con l'errore fiscale.
    if (providerName === 'rt-local') {
        // Un solo job RT per documento, garantito dall'indice unico
        // print_jobs_rt_one_per_doc: l'emissione RT è ASINCRONA (il doc resta
        // PENDING finché l'agente non risponde) e più trigger sullo stesso
        // conto — chiusura + webhook di pagamento — accoderebbero due job e
        // due scontrini. Il guard applicativo non bastava (race fra trigger
        // concorrenti, e il primo job già PRINTED quando arriva il secondo);
        // l'indice chiude tutto atomicamente. Il secondo INSERT viola
        // l'unico (23505): è la conferma che il job c'è già, non un errore.
        try {
            await queryWithRetry(
                `INSERT INTO print_jobs (tenant_id, kind, payload, printer, created_by_user_id)
                 VALUES ($1, 'RT_FISCALE', $2::jsonb, 'rt', $3)`,
                [tenantId, JSON.stringify({ fiscal_doc_id: doc.id, bill_id: billId, payload }), userId]
            );
        } catch (err: any) {
            if (err?.code !== '23505') throw err;
            // Job già in coda per questo documento: nessun secondo scontrino.
        }
        const pending = await queryWithRetry(
            `SELECT ${FISCAL_DOC_COLUMNS} FROM fiscal_documents WHERE id = $1`, [doc.id]
        );
        try { socketService?.broadcastToAll(tenantId, 'fiscal:updated', { bill_id: billId, doc: pending.rows[0] }); } catch (_) {}
        return { doc: pending.rows[0] };
    }

    let finalRow: any;
    try {
        const driver = getFiscalDriver(providerName);
        const result = await driver.issueEReceipt(payload);
        // Il numero del documento commerciale (es. "0005-0005") Openapi lo
        // mette solo nel corpo della risposta: senza estrarlo qui la colonna
        // doc_number restava NULL e l'esito diceva "emesso" senza numero.
        const docNumber = String((result.raw as any)?.data?.document_number ?? '') || null;
        const upd = await queryWithRetry(
            `UPDATE fiscal_documents
             SET status = 'CONFIRMED', provider_ref = $2, response = $3::jsonb,
                 doc_number = COALESCE($4, doc_number),
                 confirmed_at = CURRENT_TIMESTAMP, error = NULL
             WHERE id = $1
             RETURNING ${FISCAL_DOC_COLUMNS}`,
            [doc.id, result.provider_ref, JSON.stringify(result.raw ?? null), docNumber]
        );
        finalRow = upd.rows[0];
    } catch (err: any) {
        const upd = await queryWithRetry(
            `UPDATE fiscal_documents SET status = 'FAILED', error = $2 WHERE id = $1
             RETURNING ${FISCAL_DOC_COLUMNS}`,
            [doc.id, String(err?.message ?? err).slice(0, 1000)]
        );
        finalRow = upd.rows[0];
        console.error('[fiscal] emissione fallita per conto', billId, err?.message);
    }

    try { socketService?.broadcastToAll(tenantId, 'fiscal:updated', { bill_id: billId, doc: finalRow }); } catch (_) {}
    return { doc: finalRow };
}

// Configurazione fiscale del tenant. Il token API del provider resta in env
// (piattaforma); qui vivono la scelta del driver e la P.IVA dell'esercente.
app.get('/settings/fiscal', authenticate, async (req, res) => {
    try {
        res.json({
            provider: await getFiscalProviderSetting(req.tenantId!),
            vat_number: await getFiscalVatNumber(req.tenantId!),
            seller: await getFiscalSellerSetting(req.tenantId!),
            vat_map: await getFiscalVatMap(req.tenantId!),
            providers: FISCAL_PROVIDERS,
            openapi_token_configured: Boolean(process.env.OPENAPI_INVOICE_TOKEN),
        });
    } catch (err: any) {
        console.error('GET /settings/fiscal error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.put('/settings/fiscal', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const provider = req.body?.provider;
        const vatNumber = req.body?.vat_number;
        if (provider !== undefined) {
            if (!(FISCAL_PROVIDERS as readonly string[]).includes(provider)) {
                return res.status(400).json({ error: 'invalid_provider' });
            }
            if (provider === 'mock' && process.env.NODE_ENV === 'production') {
                return res.status(400).json({ error: 'Il driver mock non è ammesso in produzione' });
            }
            await queryWithRetry(
                `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
                 VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                 ON CONFLICT (tenant_id, key) DO UPDATE
                   SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
                [req.tenantId!, FISCAL_PROVIDER_KEY, provider]
            );
        }
        if (vatNumber !== undefined) {
            const v = String(vatNumber).trim();
            if (v !== '' && !/^\d{11}$/.test(v)) {
                return res.status(400).json({ error: 'vat_number deve essere una P.IVA di 11 cifre (senza prefisso IT)' });
            }
            await queryWithRetry(
                `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
                 VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                 ON CONFLICT (tenant_id, key) DO UPDATE
                   SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
                [req.tenantId!, FISCAL_VAT_NUMBER_KEY, v]
            );
        }
        // Cedente per la fattura: merge sul salvato, così un PUT parziale
        // (solo la denominazione) non azzera l'indirizzo.
        if (req.body?.seller !== undefined) {
            const raw = req.body.seller;
            if (raw == null || typeof raw !== 'object' || Array.isArray(raw)) {
                return res.status(400).json({ error: 'seller deve essere un oggetto' });
            }
            const current = await getFiscalSellerSetting(req.tenantId!);
            const str = (v: any) => typeof v === 'string' ? v.trim().slice(0, 200) : undefined;
            const next: FiscalSellerSetting = {
                business_name: str(raw.business_name) ?? current.business_name,
                regime: str(raw.regime) ?? current.regime,
                address: {
                    street: str(raw.address?.street) ?? current.address?.street,
                    zip: str(raw.address?.zip) ?? current.address?.zip,
                    city: str(raw.address?.city) ?? current.address?.city,
                    province: str(raw.address?.province) ?? current.address?.province,
                },
            };
            await queryWithRetry(
                `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
                 VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                 ON CONFLICT (tenant_id, key) DO UPDATE
                   SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
                [req.tenantId!, FISCAL_SELLER_KEY, JSON.stringify(next)]
            );
        }
        // Mappatura IVA: merge sul salvato come per il cedente — un PUT
        // parziale (solo il coperto) non tocca gli altri campi. Aliquote
        // intere 0..100, come parseVatRate dei piatti.
        if (req.body?.vat_map !== undefined) {
            const raw = req.body.vat_map;
            if (raw == null || typeof raw !== 'object' || Array.isArray(raw)) {
                return res.status(400).json({ error: 'vat_map deve essere un oggetto' });
            }
            const current = await getFiscalVatMap(req.tenantId!);
            const next: FiscalVatMap = { ...current };
            for (const field of ['dish_default', 'cover', 'service', 'fallback'] as const) {
                if (raw[field] === undefined) continue;
                const n = Number(raw[field]);
                if (!Number.isInteger(n) || n < 0 || n > 100) {
                    return res.status(400).json({ error: `vat_map.${field} deve essere un intero fra 0 e 100` });
                }
                next[field] = n;
            }
            await queryWithRetry(
                `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
                 VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                 ON CONFLICT (tenant_id, key) DO UPDATE
                   SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
                [req.tenantId!, FISCAL_VAT_MAP_KEY, JSON.stringify(next)]
            );
        }
        res.json({
            provider: await getFiscalProviderSetting(req.tenantId!),
            vat_number: await getFiscalVatNumber(req.tenantId!),
            seller: await getFiscalSellerSetting(req.tenantId!),
            vat_map: await getFiscalVatMap(req.tenantId!),
            providers: FISCAL_PROVIDERS,
            openapi_token_configured: Boolean(process.env.OPENAPI_INVOICE_TOKEN),
        });
    } catch (err: any) {
        console.error('PUT /settings/fiscal error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Emissione manuale / retry. La chiusura la innesca già da sola; questo
// endpoint serve al bottone "Emetti scontrino" e a ritentare un FAILED.
app.post('/bills/:id/fiscal-docs', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid bill id' });

        // Codice lotteria arrivato col retry manuale (conto chiuso senza, o
        // cliente che lo porge dopo): si salva sul conto PRIMA di emettere,
        // così emitFiscalDocForBill lo trova come in chiusura.
        const lotteryRaw = typeof req.body?.lottery_code === 'string' ? req.body.lottery_code.trim().toUpperCase() : '';
        if (lotteryRaw) {
            if (!/^[A-Z0-9]{8}$/.test(lotteryRaw)) {
                return res.status(400).json({ error: 'lottery_code_invalid', message: 'Il codice lotteria sono 8 lettere o cifre' });
            }
            await queryWithRetry(
                `UPDATE table_bills SET lottery_code = $1 WHERE id = $2 AND tenant_id = $3`,
                [lotteryRaw, id, req.tenantId!]
            );
        }

        // documento: 'Cassa' → scontrino battuto sull'RT esterno, anche a
        // posteriori (conto chiuso senza registrare, o numero riportato il
        // giorno dopo). Nessuna emissione: si scrive il documento com'è.
        if (req.body?.documento === 'Cassa') {
            const rtRaw = typeof req.body?.rt_doc_number === 'string' ? req.body.rt_doc_number.trim() : '';
            if (rtRaw.length > 30) {
                return res.status(400).json({ error: 'rt_doc_number_invalid', message: 'Il numero scontrino supera i 30 caratteri' });
            }
            const marked = await registerExternalRtReceipt(req.tenantId!, id, req.user?.userId ?? null, rtRaw || null);
            if (marked.skipped) {
                const cassaMessages: Record<string, string> = {
                    bill_not_closed: 'Lo scontrino di cassa si registra su un conto chiuso e saldato per intero',
                    passepartout: 'Conto del gestionale: l\'esito della cassa lo registra il bridge (chiusura Passepartout)',
                    doc_exists: 'Il conto ha già un documento vivo',
                };
                return res.status(409).json({ error: cassaMessages[marked.skipped] ?? marked.skipped, reason: marked.skipped });
            }
            return res.status(200).json({ doc: marked.doc, request: null });
        }

        // documento: 'Proforma' → niente emissione: si registra (anche a
        // posteriori) il segnaposto sul conto chiuso senza documento. Serve
        // per i conti chiusi prima della scelta in dialog, o dimenticati.
        if (req.body?.documento === 'Proforma') {
            const marked = await registerNativeProforma(req.tenantId!, id, req.user?.userId ?? null);
            if (marked.skipped) {
                const proformaMessages: Record<string, string> = {
                    bill_not_closed: 'La proforma si segna su un conto chiuso e saldato per intero',
                    passepartout: 'Conto del gestionale: la proforma la batte la cassa (chiusura Passepartout)',
                    doc_exists: 'Il conto ha già un documento: la proforma non serve',
                };
                return res.status(409).json({ error: proformaMessages[marked.skipped] ?? marked.skipped, reason: marked.skipped });
            }
            return res.status(200).json({ doc: marked.doc, request: null });
        }

        const outcome = await emitFiscalDocForBill(req.tenantId!, id, req.user?.userId ?? null);
        if (outcome.skipped) {
            const messages: Record<string, string> = {
                not_configured: 'Nessun provider fiscale configurato (Impostazioni → Fiscale)',
                missing_vat_number: 'P.IVA mancante nelle impostazioni fiscali',
                bill_not_closed: 'Il documento si emette solo su un conto chiuso e saldato per intero',
                race: 'Emissione già in corso, riprova',
                in_progress: 'Emissione già in corso, riprova tra qualche secondo',
                passepartout: 'Conto del gestionale: lo scontrino lo emette la cassa alla chiusura comanda (POST /bills/:id/passepartout-close)',
                invoice_exists: 'Il conto ha una fattura: lo scontrino non si emette sullo stesso importo',
            };
            return res.status(409).json({ error: messages[outcome.skipped] ?? outcome.skipped, reason: outcome.skipped });
        }
        // Il payload trasmesso viaggia nella risposta dell'emissione manuale:
        // è quello che si guarda quando lo scontrino non torna.
        const reqRs = await queryWithRetry(`SELECT request FROM fiscal_documents WHERE id = $1`, [outcome.doc.id]);
        // PENDING è un esito valido per rt-local: il registratore risponde
        // via ack dell'agente, l'UI segue dal socket.
        res.status(outcome.doc.status === 'FAILED' ? 502 : 200).json({ doc: outcome.doc, request: reqRs.rows[0]?.request ?? null });
    } catch (err: any) {
        console.error('POST /bills/:id/fiscal-docs error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Annullo del documento presso il provider (DELETE /IT-e-receipts/:id lato
// Openapi). Il conto non si tocca: annullare lo scontrino è un atto fiscale,
// riaprire il conto è un atto operativo, e non sempre vanno insieme.
app.post('/bills/:id/fiscal-docs/:fid/void', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        const fid = parseInt(req.params.fid, 10);
        if (!Number.isFinite(id) || !Number.isFinite(fid)) return res.status(400).json({ error: 'Invalid id' });

        const docRs = await queryWithRetry(
            `SELECT ${FISCAL_DOC_COLUMNS} FROM fiscal_documents
             WHERE id = $1 AND table_bill_id = $2 AND tenant_id = $3`,
            [fid, id, req.tenantId!]
        );
        const doc = docRs.rows[0];
        if (!doc) return res.status(404).json({ error: 'Documento non trovato' });
        // I documenti del registratore (Passepartout o RT battuto a mano)
        // PRIMA della guardia sul provider_ref: quello di cassa non ne ha
        // uno — il numero vive in doc_number — e senza questo ordine il 409
        // uscirebbe col messaggio sbagliato.
        if (doc.provider === 'passepartout' || doc.provider === 'external_rt' || doc.provider === 'rt-local') {
            return res.status(409).json({ error: 'Scontrino emesso dal registratore: l\'annullo si fa dall\'RT (o dalla cassa), non da qui' });
        }
        if (doc.status !== 'CONFIRMED' || !doc.provider_ref) {
            return res.status(409).json({ error: `Solo un documento confermato si può annullare (stato ${doc.status})` });
        }
        // Una fattura trasmessa a SDI non si "annulla": si storna con nota
        // di credito (TD04), che oggi non emettiamo — fase successiva del
        // piano. Meglio un no chiaro che un DELETE sul binario sbagliato.
        if (doc.doc_type === 'INVOICE') {
            return res.status(409).json({ error: 'Una fattura inviata a SDI si storna con nota di credito, non si annulla da qui' });
        }
        if (doc.doc_type === 'CREDIT_NOTE') {
            return res.status(409).json({ error: 'Una nota di credito è un atto contabile definitivo: non si annulla' });
        }
        // Documento emesso dall'RT di cassa alla chiusura Passepartout: il
        // reso/annullo è un'operazione del registratore, non c'è un provider
        // cloud da chiamare.
        const driver = getFiscalDriver(doc.provider);
        const raw = await driver.voidEReceipt(doc.provider_ref);
        const upd = await queryWithRetry(
            `UPDATE fiscal_documents
             SET status = 'VOIDED', voided_at = CURRENT_TIMESTAMP, response = $2::jsonb
             WHERE id = $1
             RETURNING ${FISCAL_DOC_COLUMNS}`,
            [fid, JSON.stringify(raw ?? null)]
        );
        try { socketService?.broadcastToAll(req.tenantId!, 'fiscal:updated', { bill_id: id, doc: upd.rows[0] }); } catch (_) {}

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId, req.user.email, req.user.email,
                ActivityAction.UPDATE, ResourceType.RESERVATION,
                undefined,
                `Annullato documento fiscale #${fid} (conto #${id})`
            );
        }
        res.json({ doc: upd.rows[0] });
    } catch (err: any) {
        console.error('POST /bills/:id/fiscal-docs/:fid/void error:', err);
        res.status(502).json({ error: 'Annullo non riuscito', detail: err?.message });
    }
});

// Storno di una fattura con nota di credito TD04 (storno TOTALE: stessi
// importi, stesso cessionario, tipo documento a dare il segno). La nota
// prende un numero dalla stessa numerazione annuale delle fatture e viaggia
// sullo stesso canale SDI del provider. A conferma avvenuta la fattura passa
// VOIDED e la nota resta CONFIRMED per sempre — fuori dall'indice "one live
// per bill" (predicato doc_type <> 'CREDIT_NOTE'), così il conto torna
// libero di riemettere scontrino o fattura corretta.
app.post('/bills/:id/fiscal-docs/:fid/credit-note', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        const fid = parseInt(req.params.fid, 10);
        if (!Number.isFinite(id) || !Number.isFinite(fid)) return res.status(400).json({ error: 'Invalid id' });

        const docRs = await queryWithRetry(
            `SELECT ${FISCAL_DOC_COLUMNS}, request FROM fiscal_documents
             WHERE id = $1 AND table_bill_id = $2 AND tenant_id = $3`,
            [fid, id, req.tenantId!]
        );
        const doc = docRs.rows[0];
        if (!doc) return res.status(404).json({ error: 'Documento non trovato' });
        if (doc.doc_type !== 'INVOICE') return res.status(409).json({ error: 'La nota di credito storna una fattura' });
        if (doc.status !== 'CONFIRMED') return res.status(409).json({ error: `Solo una fattura confermata si storna (stato ${doc.status})` });
        if (doc.provider === 'passepartout') {
            return res.status(409).json({ error: 'Documento del gestionale: lo storno passa dalla cassa Passepartout' });
        }
        const buyer = doc.request?.buyer;
        if (!buyer?.name) {
            return res.status(409).json({ error: 'La fattura non ha il cessionario registrato: nota di credito non componibile' });
        }
        const sellerRes = await resolveFiscalSeller(req.tenantId!);
        if ('missing' in sellerRes) {
            return res.status(409).json({ error: `Dati del cedente incompleti: manca ${sellerRes.missing.join(', ')}`, reason: 'missing_seller' });
        }

        // Stessa scomposizione IVA della fattura: righe del conto
        // riproporzionate sull'importo del documento stornato.
        const billRs = await queryWithRetry(
            `SELECT items, total_cents, external_ref FROM table_bills WHERE id = $1 AND tenant_id = $2`,
            [id, req.tenantId!]
        );
        if (!billRs.rows[0]) return res.status(404).json({ error: 'Conto non trovato' });
        const vatRows = vatBreakdownFromItems(Array.isArray(billRs.rows[0].items) ? billRs.rows[0].items : null, doc.total_cents);
        if (vatRows.length === 0) {
            vatRows.push({ rate: 10, gross_cents: doc.total_cents, net_cents: Math.round(doc.total_cents / 1.1), vat_cents: doc.total_cents - Math.round(doc.total_cents / 1.1) });
        }

        // Claim sul doppio submit, come per lo scontrino: vince chi bumpa
        // attempts per primo, l'altro esce senza chiamare il provider.
        const claim = await queryWithRetry(
            `UPDATE fiscal_documents SET attempts = attempts + 1
             WHERE id = $1 AND status = 'CONFIRMED' AND attempts = $2
             RETURNING id`,
            [fid, doc.attempts]
        );
        if ((claim.rowCount ?? 0) === 0) return res.status(409).json({ error: 'Storno già in corso', reason: 'in_progress' });

        const year = Number(getRomeDatePart(new Date()).slice(0, 4));
        const docNumber = await nextInvoiceNumber(req.tenantId!, year);
        const docDate = getRomeDatePart(new Date());
        const xml = buildFatturaPaXml({
            seller: sellerRes.seller,
            buyer,
            doc_number: docNumber,
            doc_date: docDate,
            vat_rows: vatRows,
            total_gross_cents: doc.total_cents,
            description: `Storno fattura ${doc.doc_number ?? ''}`.trim(),
            doc_type: 'TD04',
            related: { number: String(doc.doc_number ?? ''), date: getRomeDatePart(doc.confirmed_at) },
        });

        let providerRef: string; let raw: any;
        try {
            const driver = getFiscalDriver(doc.provider);
            const result = await driver.issueInvoice(xml);
            providerRef = result.provider_ref; raw = result.raw ?? null;
        } catch (err: any) {
            // Il numero è bruciato ma va a registro col suo FAILED: un buco
            // di numerazione senza traccia è un problema legale, uno col suo
            // motivo scritto è una nota a verbale.
            const failIns = await queryWithRetry(
                `INSERT INTO fiscal_documents (tenant_id, table_bill_id, doc_type, doc_number, provider, fiscal_id_snapshot, status, total_cents, created_by_user_id, request, error, related_doc_id, attempts)
                 VALUES ($1, $2, 'CREDIT_NOTE', $3, $4, $5, 'FAILED', $6, $7, $8::jsonb, $9, $10, 1)
                 RETURNING ${FISCAL_DOC_COLUMNS}`,
                [req.tenantId!, id, docNumber, doc.provider, sellerRes.seller.vat_number, doc.total_cents,
                 req.user?.userId ?? null, JSON.stringify({ xml, buyer }), String(err?.message ?? err).slice(0, 1000), fid]
            );
            try { socketService?.broadcastToAll(req.tenantId!, 'fiscal:updated', { bill_id: id, doc: failIns.rows[0] }); } catch (_) {}
            return res.status(502).json({ error: 'Nota di credito non emessa', detail: err?.message, doc: failIns.rows[0] });
        }

        // Provider ok: fattura VOIDED e nota CONFIRMED nella stessa
        // transazione — mai l'una senza l'altra a registro.
        const client = await pool.connect();
        let voidedInvoice: any; let creditNote: any;
        try {
            await client.query('BEGIN');
            const upd = await client.query(
                `UPDATE fiscal_documents SET status = 'VOIDED', voided_at = CURRENT_TIMESTAMP
                 WHERE id = $1 AND tenant_id = $2 RETURNING ${FISCAL_DOC_COLUMNS}`,
                [fid, req.tenantId!]
            );
            voidedInvoice = upd.rows[0];
            const ins = await client.query(
                `INSERT INTO fiscal_documents (tenant_id, table_bill_id, doc_type, doc_number, provider, fiscal_id_snapshot, status, provider_ref, response, total_cents, created_by_user_id, request, related_doc_id, confirmed_at, attempts)
                 VALUES ($1, $2, 'CREDIT_NOTE', $3, $4, $5, 'CONFIRMED', $6, $7::jsonb, $8, $9, $10::jsonb, $11, CURRENT_TIMESTAMP, 1)
                 RETURNING ${FISCAL_DOC_COLUMNS}`,
                [req.tenantId!, id, docNumber, doc.provider, sellerRes.seller.vat_number, providerRef,
                 JSON.stringify(raw), doc.total_cents, req.user?.userId ?? null, JSON.stringify({ xml, buyer }), fid]
            );
            creditNote = ins.rows[0];
            await client.query('COMMIT');
        } catch (err) {
            await client.query('ROLLBACK').catch(() => {});
            throw err;
        } finally {
            client.release();
        }

        try {
            socketService?.broadcastToAll(req.tenantId!, 'fiscal:updated', { bill_id: id, doc: voidedInvoice });
            socketService?.broadcastToAll(req.tenantId!, 'fiscal:updated', { bill_id: id, doc: creditNote });
        } catch (_) {}

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId, req.user.email, req.user.email,
                ActivityAction.CREATE, ResourceType.RESERVATION,
                undefined,
                `Nota di credito ${docNumber} emessa: stornata fattura ${doc.doc_number} (conto #${id})`
            );
        }
        res.status(201).json({ doc: creditNote, voided_invoice: voidedInvoice });
    } catch (err: any) {
        console.error('POST /bills/:id/fiscal-docs/:fid/credit-note error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});


// --- Lookup P.IVA (API Imprese di Openapi) -----------------------------------
// Il cameriere digita la P.IVA nel dialog fattura e i campi si riempiono:
// GET /base/{piva} porta denominazione, sede e codice destinatario SDI in una
// chiamata sola; la PEC si chiede a parte solo se l'SDI manca (ogni chiamata
// costa, in produzione). Token con scope imprese via OPENAPI_COMPANY_TOKEN
// (fallback sul token invoice: se non ha lo scope l'errore lo dice chiaro).
// Base sandbox di default: la produzione è una scelta esplicita, come per il
// driver fiscale.
const companyLookupCache = new Map<string, { data: any; refreshedAt: number }>();
const COMPANY_LOOKUP_TTL_MS = 24 * 60 * 60 * 1000; // i dati camerali non cambiano in serata; il doppio tap non paga due volte

app.get('/company-lookup/:piva', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const piva = String(req.params.piva || '').replace(/\s/g, '');
        if (!/^\d{11}$/.test(piva)) return res.status(400).json({ error: 'piva_invalid', message: 'La P.IVA sono 11 cifre' });

        const cached = companyLookupCache.get(piva);
        if (cached && Date.now() - cached.refreshedAt <= COMPANY_LOOKUP_TTL_MS) return res.json(cached.data);

        const token = process.env.OPENAPI_COMPANY_TOKEN || process.env.OPENAPI_INVOICE_TOKEN;
        if (!token) return res.status(503).json({ error: 'not_configured', message: 'Lookup P.IVA non configurato (OPENAPI_COMPANY_TOKEN)' });
        const base = (process.env.OPENAPI_COMPANY_BASE_URL || 'https://test.imprese.openapi.it').replace(/\/$/, '');
        const get = async (path: string) => {
            const r = await fetch(`${base}${path}`, { headers: { 'Authorization': `Bearer ${token}` } });
            const j: any = await r.json().catch(() => null);
            return { status: r.status, json: j };
        };

        const baseRes = await get(`/base/${piva}`);
        if (baseRes.status === 401 || baseRes.status === 403) {
            return res.status(503).json({ error: 'not_configured', message: 'Il token Openapi non ha lo scope Imprese: aggiungilo da console.openapi.com o imposta OPENAPI_COMPANY_TOKEN' });
        }
        if (baseRes.status === 404 || baseRes.json?.data == null) {
            return res.status(404).json({ error: 'not_found', message: 'P.IVA non trovata' });
        }
        if (baseRes.status >= 400) {
            return res.status(502).json({ error: 'lookup_failed', message: String(baseRes.json?.message ?? `HTTP ${baseRes.status}`).slice(0, 200) });
        }
        const d = baseRes.json.data;

        let pec: string | null = null;
        if (!d.codice_destinatario) {
            const pecRes = await get(`/pec/${piva}`);
            const p = pecRes.json?.data;
            pec = typeof p?.pec === 'string' ? p.pec : (Array.isArray(p?.pec) ? p.pec[0] : null);
        }

        const street = [d.toponimo, d.via ?? d.indirizzo, d.civico].filter(Boolean).join(' ').trim();
        const out = {
            name: d.denominazione ?? '',
            vat_number: d.piva ?? piva,
            tax_code: d.cf ?? '',
            sdi_code: d.codice_destinatario ?? '',
            pec: pec ?? '',
            address: {
                street,
                zip: d.cap ?? '',
                city: d.comune ?? '',
                province: d.provincia ?? '',
            },
        };
        if (companyLookupCache.size > 500) companyLookupCache.clear();
        companyLookupCache.set(piva, { data: out, refreshedAt: Date.now() });
        res.json(out);
    } catch (err: any) {
        console.error('GET /company-lookup error:', err?.message);
        res.status(502).json({ error: 'lookup_failed', message: 'Servizio non raggiungibile' });
    }
});

// --- Webhook esiti Openapi ---------------------------------------------------
// SDI può scartare una fattura GIORNI dopo l'invio, e sul binario classico
// dello scontrino (/IT-receipts) numero documento ed esito arrivano in
// asincrono: senza questo callback il documento resterebbe CONFIRMED per
// sempre su una fattura scartata, e lo scontrino classico resterebbe senza
// numero. L'URL va registrato nella IT-configuration del provider
// (api_configurations, eventi customer-invoice / receipt / receipt-error,
// method JSON) — scripts/collaudo-fiscale.mjs webhook <url>.
//
// Mappatura: REJECTED o state ERROR → FAILED (l'UI ha già il ramo errore con
// "Riprova"); tutto il resto (DELIVERED, ACCEPTED, NOT_DELIVERED = in
// cassetto fiscale, TERMS_EXPIRED = decorrenza termini, receipt ready) è un
// esito valido: risposta aggiornata, doc_number backfillato se il provider
// lo ha appena assegnato. Sempre 200 in uscita: un errore nostro non deve
// far ritentare Openapi all'infinito.
app.post('/webhook/t/:tenantToken/openapi-fiscale', express.urlencoded({ extended: false }), async (req, res) => {
    const tenantId = await resolveWebhookTenantOr404(req, res);
    if (tenantId == null) return;
    try {
        // method JSON → l'entità è il body; method POST → JSON incodato nel
        // campo 'data' (default del sistema di callback Openapi).
        let entity: any = req.body;
        if (entity && typeof entity.data === 'string') {
            try { entity = JSON.parse(entity.data); } catch (_) { /* resta com'è */ }
        }
        if (entity?.data && typeof entity.data === 'object') entity = entity.data;
        const ref = entity?.id ?? entity?.uuid;
        if (!ref) return res.json({ ok: true, ignored: 'no_id' });

        // 'mock' incluso: i test API esercitano questo stesso percorso; fuori
        // restano i documenti di cassa (passepartout) e i segnaposto (crm).
        const docRs = await queryWithRetry(
            `SELECT id, table_bill_id, doc_type, status FROM fiscal_documents
             WHERE provider_ref = $1 AND tenant_id = $2 AND provider IN ('openapi', 'mock')`,
            [String(ref), tenantId]
        );
        const doc = docRs.rows[0];
        if (!doc) return res.json({ ok: true, ignored: 'unknown_ref' });

        const sdiStatus = String(entity?.details?.sdi_status ?? '').toUpperCase();
        const state = String(entity?.state ?? entity?.status ?? '').toUpperCase();
        const failed = sdiStatus === 'REJECTED' || state === 'ERROR' || state === 'FAILED'
            || Boolean(entity?.error_code) || Boolean(entity?.error_message);
        const docNumber = typeof entity?.document_number === 'string' && entity.document_number.trim()
            ? entity.document_number.trim() : null;
        // Un documento VOIDED resta VOIDED qualunque cosa dica il callback:
        // l'annullo è un atto nostro, l'esito arrivato dopo è storia vecchia.
        const upd = await queryWithRetry(
            `UPDATE fiscal_documents
             SET response = $2::jsonb,
                 doc_number = COALESCE(doc_number, $5),
                 status = CASE WHEN status = 'VOIDED' THEN status WHEN $3 THEN 'FAILED' ELSE status END,
                 error = CASE WHEN $3 THEN $4 ELSE error END
             WHERE id = $1
             RETURNING ${FISCAL_DOC_COLUMNS}`,
            [doc.id, JSON.stringify({ data: entity }), failed,
             failed ? `Provider: ${sdiStatus || state}${entity?.details?.sdi_message ?? entity?.error_message ? ` — ${String(entity?.details?.sdi_message ?? entity?.error_message).slice(0, 500)}` : ''}` : null,
             docNumber]
        );
        try { socketService?.broadcastToAll(tenantId, 'fiscal:updated', { bill_id: doc.table_bill_id, doc: upd.rows[0] }); } catch (_) {}
        if (failed) console.warn(`[fiscal] webhook: documento ${doc.id} (conto ${doc.table_bill_id}) segnato FAILED da ${sdiStatus || state}`);
        res.json({ ok: true });
    } catch (err: any) {
        console.error('POST /webhook/openapi-fiscale error:', err?.message);
        res.json({ ok: true, ignored: 'error' });
    }
});

// Emissione fattura elettronica (SDI) su un conto CHIUSO o su una singola
// quota PAGATA (l'azienda al tavolo misto che paga la sua parte con
// fattura). Il cessionario arriva dalla rubrica (customers.billing) o
// inline nel body — l'inline vince campo per campo, così il cameriere può
// correggere al volo senza toccare l'anagrafica.
//
// Regola fiscale MVP: sullo stesso importo non viaggiano due documenti.
// La fattura (su conto o su quota) esige che NON ci sia uno scontrino vivo
// sul conto: prima si annulla quello, poi si fattura. Il caso "fattura
// sulla quota + scontrino sul resto" richiede lo scontrino parziale, che
// oggi non esiste — segnalato nel piano come domanda per il commercialista.
app.post('/bills/:id/invoices', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid bill id' });

        const providerName = await getFiscalProviderSetting(req.tenantId!);
        if (providerName === 'none') {
            return res.status(409).json({ error: 'Nessun provider fiscale configurato (Impostazioni → Scontrino elettronico)', reason: 'not_configured' });
        }
        if (providerName === 'rt-local') {
            // Il registratore emette scontrini, non fatture SDI: la fattura
            // resta sul binario cloud (o sul gestionale, durante il ponte).
            return res.status(409).json({ error: 'Col registratore di cassa la fattura non parte da qui: serve il provider cloud', reason: 'rt_local_no_invoice' });
        }
        const sellerRes = await resolveFiscalSeller(req.tenantId!);
        if ('missing' in sellerRes) {
            return res.status(409).json({
                error: `Dati del cedente incompleti nelle impostazioni fiscali: manca ${sellerRes.missing.join(', ')}`,
                reason: 'missing_seller',
            });
        }

        const billRs = await queryWithRetry(
            `SELECT b.id, b.total_cents, b.items, b.status, b.external_ref, t.name AS table_name
             FROM table_bills b
             LEFT JOIN tables t ON t.id = b.table_id AND t.tenant_id = b.tenant_id
             WHERE b.id = $1 AND b.tenant_id = $2`,
            [id, req.tenantId!]
        );
        const bill = billRs.rows[0];
        if (!bill) return res.status(404).json({ error: 'Conto non trovato' });
        // Conto del gestionale Passepartout: come per lo scontrino, i
        // documenti fiscali li emette la cassa — non si raddoppia via Openapi.
        if (passepartoutComandaIdFromRef(bill.external_ref) != null) {
            return res.status(409).json({ error: 'Conto del gestionale: la fattura si emette dalla cassa Passepartout', reason: 'passepartout' });
        }

        // Quota (facoltativa): la fattura copre solo quell'importo.
        const splitIdRaw = req.body?.split_id;
        const splitId = splitIdRaw != null ? Number(splitIdRaw) : null;
        let amountCents = bill.total_cents;
        if (splitId != null) {
            if (!Number.isFinite(splitId)) return res.status(400).json({ error: 'split_id non valido' });
            const splitRs = await queryWithRetry(
                `SELECT id, amount_cents, status, kind FROM table_bill_splits
                 WHERE id = $1 AND table_bill_id = $2 AND tenant_id = $3`,
                [splitId, id, req.tenantId!]
            );
            const split = splitRs.rows[0];
            if (!split) return res.status(404).json({ error: 'Quota non trovata' });
            if (split.status !== 'PAID' || split.kind === 'deposit') {
                return res.status(409).json({ error: 'Si fattura solo una quota pagata da un cliente' });
            }
            amountCents = split.amount_cents;
        } else if (bill.status !== 'CLOSED') {
            return res.status(409).json({ error: 'La fattura sull\'intero conto si emette a conto chiuso e saldato', reason: 'bill_not_closed' });
        }

        // Un solo binario fiscale: niente scontrino vivo sul conto, e mai
        // fattura-intero sopra fatture-quota (o viceversa: l'indice unico a
        // livello conto copre già intero-su-intero).
        const liveDocs = await queryWithRetry(
            `SELECT id, doc_type, table_bill_split_id FROM fiscal_documents
             WHERE table_bill_id = $1 AND status IN ('PENDING', 'CONFIRMED')`,
            [id]
        );
        // Tutte le guardie PRIMA della numerazione: un tentativo destinato al
        // 409 non deve bruciare un numero fattura (buchi = problemi legali).
        // La proforma nativa non è un documento fiscale e non blocca: esce
        // dalle guardie qui e viene superata (VOID) prima dell'inserimento.
        const proformaLive = liveDocs.rows.some((d: any) => d.doc_type === 'PROFORMA');
        // La nota di credito resta CONFIRMED per sempre come atto contabile:
        // non è un documento vivo e non blocca la fattura corretta.
        liveDocs.rows = liveDocs.rows.filter((d: any) => d.doc_type !== 'PROFORMA' && d.doc_type !== 'CREDIT_NOTE');
        const liveReceipt = liveDocs.rows.find((d: any) => d.doc_type === 'RECEIPT');
        if (liveReceipt) {
            return res.status(409).json({
                error: 'Il conto ha già uno scontrino: annullalo prima di emettere la fattura',
                reason: 'receipt_exists',
            });
        }
        if (splitId == null && liveDocs.rows.some((d: any) => d.table_bill_split_id == null)) {
            return res.status(409).json({ error: 'Il conto ha già una fattura', reason: 'invoice_exists' });
        }
        if (splitId == null && liveDocs.rows.some((d: any) => d.table_bill_split_id != null)) {
            return res.status(409).json({ error: 'Esistono fatture su singole quote: non si può fatturare anche l\'intero', reason: 'split_invoices_exist' });
        }
        if (splitId != null && liveDocs.rows.some((d: any) => d.table_bill_split_id == null)) {
            return res.status(409).json({ error: 'Esiste già un documento sull\'intero conto', reason: 'bill_doc_exists' });
        }
        if (splitId != null && liveDocs.rows.some((d: any) => d.table_bill_split_id === splitId)) {
            return res.status(409).json({ error: 'Questa quota ha già una fattura', reason: 'invoice_exists' });
        }

        // Cessionario: rubrica come base, body come override campo per campo.
        let base: any = {};
        const customerId = req.body?.customer_id != null ? Number(req.body.customer_id) : null;
        let customerName = '';
        if (customerId != null && Number.isFinite(customerId)) {
            const c = await queryWithRetry(
                `SELECT name, billing FROM customers WHERE id = $1 AND tenant_id = $2`,
                [customerId, req.tenantId!]
            );
            if (c.rowCount === 0) return res.status(404).json({ error: 'Cliente non trovato' });
            base = c.rows[0].billing ?? {};
            customerName = c.rows[0].name;
        }
        const inline = req.body?.buyer && typeof req.body.buyer === 'object' ? req.body.buyer : {};
        const str = (v: any) => typeof v === 'string' && v.trim() ? v.trim() : undefined;
        const buyer: InvoiceBuyer = {
            name: str(inline.name) ?? str(base.name) ?? customerName,
            vat_number: str(inline.vat_number) ?? str(base.vat_number) ?? null,
            tax_code: str(inline.tax_code) ?? str(base.tax_code) ?? null,
            sdi_code: str(inline.sdi_code) ?? str(base.sdi_code) ?? null,
            pec: str(inline.pec) ?? str(base.pec) ?? null,
            address: {
                street: str(inline.address?.street) ?? str(base.address?.street) ?? '',
                zip: str(inline.address?.zip) ?? str(base.address?.zip) ?? '',
                city: str(inline.address?.city) ?? str(base.address?.city) ?? '',
                province: str(inline.address?.province) ?? str(base.address?.province),
            },
        };
        const buyerMissing: string[] = [];
        if (!buyer.name) buyerMissing.push('denominazione');
        if (!buyer.vat_number && !buyer.tax_code) buyerMissing.push('P.IVA o codice fiscale');
        if (buyer.vat_number && !/^\d{11}$/.test(buyer.vat_number)) {
            return res.status(400).json({ error: 'P.IVA del cliente non valida (11 cifre senza IT)' });
        }
        if (!buyer.address.street || !buyer.address.zip || !buyer.address.city) buyerMissing.push('indirizzo completo');
        if (buyerMissing.length > 0) {
            return res.status(400).json({ error: `Dati del cliente incompleti: manca ${buyerMissing.join(', ')}`, reason: 'missing_buyer' });
        }

        // Scomposizione IVA sull'importo fatturato: per la quota lo scorporo
        // viene riproporzionato dalle stesse righe del conto.
        const vatRows = vatBreakdownFromItems(Array.isArray(bill.items) ? bill.items : null, amountCents);
        if (vatRows.length === 0) {
            // Conto aperto a mano senza righe: riga unica al 10, come lo scontrino.
            vatRows.push({ rate: 10, gross_cents: amountCents, net_cents: Math.round(amountCents / 1.1), vat_cents: amountCents - Math.round(amountCents / 1.1) });
        }

        // Validazioni passate: il segnaposto proforma cede il posto alla
        // fattura sull'INTERO (VOID prima di consumare il numero). Sulla
        // quota invece resta: continua a marcare il resto del conto come
        // "chiuso senza documento, di proposito".
        if (proformaLive && splitId == null) await supersedeNativeProforma(req.tenantId!, id);

        const year = Number(getRomeDatePart(new Date()).slice(0, 4));
        const docNumber = await nextInvoiceNumber(req.tenantId!, year);
        const docDate = getRomeDatePart(new Date());
        const xml = buildFatturaPaXml({
            seller: sellerRes.seller,
            buyer,
            doc_number: docNumber,
            doc_date: docDate,
            vat_rows: vatRows,
            total_gross_cents: amountCents,
            description: `Somministrazione alimenti e bevande${bill.table_name ? ` — tavolo ${bill.table_name}` : ''}`,
        });

        // La riga nasce direttamente col payload e viene reclamata come per
        // lo scontrino (claim su attempts) — qui il chiamante è uno solo, ma
        // il doppio submit del bottone è lo stesso race.
        const ins = await queryWithRetry(
            `INSERT INTO fiscal_documents (tenant_id, table_bill_id, table_bill_split_id, doc_type, doc_number, provider, fiscal_id_snapshot, total_cents, created_by_user_id, request, attempts)
             VALUES ($1, $2, $3, 'INVOICE', $4, $5, $6, $7, $8, $9::jsonb, 1)
             ON CONFLICT DO NOTHING
             RETURNING ${FISCAL_DOC_COLUMNS}`,
            [req.tenantId!, id, splitId, docNumber, providerName, sellerRes.seller.vat_number, amountCents,
             req.user?.userId ?? null, JSON.stringify({ xml, buyer })]
        );
        if (ins.rowCount === 0) {
            return res.status(409).json({ error: 'Emissione già in corso o documento già presente', reason: 'in_progress' });
        }
        const doc = ins.rows[0];

        let finalRow: any;
        try {
            const driver = getFiscalDriver(providerName);
            const result = await driver.issueInvoice(xml);
            const upd = await queryWithRetry(
                `UPDATE fiscal_documents
                 SET status = 'CONFIRMED', provider_ref = $2, response = $3::jsonb,
                     confirmed_at = CURRENT_TIMESTAMP, error = NULL
                 WHERE id = $1
                 RETURNING ${FISCAL_DOC_COLUMNS}`,
                [doc.id, result.provider_ref, JSON.stringify(result.raw ?? null)]
            );
            finalRow = upd.rows[0];
        } catch (err: any) {
            const upd = await queryWithRetry(
                `UPDATE fiscal_documents SET status = 'FAILED', error = $2 WHERE id = $1
                 RETURNING ${FISCAL_DOC_COLUMNS}`,
                [doc.id, String(err?.message ?? err).slice(0, 1000)]
            );
            finalRow = upd.rows[0];
            console.error('[fiscal] fattura fallita per conto', id, err?.message);
        }

        try { socketService?.broadcastToAll(req.tenantId!, 'fiscal:updated', { bill_id: id, doc: finalRow }); } catch (_) {}

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId, req.user.email, req.user.email,
                ActivityAction.CREATE, ResourceType.RESERVATION,
                undefined,
                `Fattura ${docNumber} ${finalRow.status === 'CONFIRMED' ? 'emessa' : 'NON emessa'} · ${formatEuroMinor(amountCents)} a ${buyer.name} (conto #${id}${splitId ? `, quota #${splitId}` : ''})`
            );
        }

        res.status(finalRow.status === 'CONFIRMED' ? 201 : 502).json({ doc: finalRow });
    } catch (err: any) {
        console.error('POST /bills/:id/invoices error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// PR 6 — rimborso di una quota. Copre due casi:
//   a) split PAID normale: refund sul gateway, split → REFUNDED, e se il
//      conto era SETTLED riapre (OPEN) per l'importo rimborsato;
//   b) overpayment (split ABANDONED ma pagamento COMPLETED, il caso del
//      checkout completato dopo la scadenza del claim): refund sul gateway
//      e marcatura REFUNDED, il conto non si tocca perché la quota non
//      contribuiva al saldo.
// Il refund parte PRIMA della scrittura DB: se il gateway fallisce non
// cambiamo nulla; se la scrittura fallisse dopo, i log del gateway restano
// la fonte di verità e un retry dell'endpoint è idempotente lato nostro
// (lo split non è più in stato rimborsabile).
app.post('/bills/splits/:id/refund', authenticate, requirePermission('payments:full'), async (req, res) => {
    try {
        const splitId = parseInt(req.params.id, 10);
        if (!Number.isFinite(splitId)) return res.status(400).json({ error: 'Invalid split id' });

        const rs = await queryWithRetry(
            `SELECT s.id, s.kind, s.status AS split_status, s.amount_cents, s.claimant_label, s.table_bill_id,
                    b.status AS bill_status, b.reservation_id, b.total_cents, b.currency,
                    pr.id AS payment_request_id, pr.status AS pr_status, pr.provider,
                    pr.provider_order_id, pr.metadata AS pr_metadata
             FROM table_bill_splits s
             JOIN table_bills b ON b.id = s.table_bill_id
             LEFT JOIN payment_requests pr ON pr.id = s.payment_request_id
             WHERE s.id = $1 AND b.tenant_id = $2`,
            [splitId, req.tenantId!]
        );
        if (rs.rowCount === 0) return res.status(404).json({ error: 'Quota non trovata' });
        const row = rs.rows[0];

        // La quota 'deposit' è l'acconto della prenotazione portato nel conto:
        // il suo rimborso passa dalla sezione Pagamenti (POST /payments/:id/refund),
        // che storna anche il credito e riapre il conto. Qui lo blocchiamo così il
        // cameriere non lo rimborsa scambiandolo per la quota di un cliente.
        if (row.kind === 'deposit') {
            return res.status(409).json({
                error: 'Questa voce è l\'acconto della prenotazione: rimborsalo dalla sezione Pagamenti, non dal conto.',
            });
        }

        const prPaid = ['COMPLETED', 'PAID'].includes(String(row.pr_status || '').toUpperCase());
        const refundablePaid = row.split_status === 'PAID';
        const refundableOverpaid = row.split_status === 'ABANDONED' && prPaid;
        if (!refundablePaid && !refundableOverpaid) {
            return res.status(409).json({ error: `La quota non è rimborsabile (stato ${row.split_status})` });
        }
        if (!isPaymentProvider(row.provider) || !row.provider_order_id) {
            return res.status(409).json({ error: 'Nessun ordine di pagamento collegato alla quota' });
        }

        // Refund through the provider that took the money, not the one that
        // happens to be active now.
        await refundPaymentOrder(
            req.tenantId!,
            row.provider,
            row.provider_order_id,
            row.amount_cents,
            row.currency || 'EUR',
            `Rimborso quota${row.claimant_label ? ' ' + row.claimant_label : ''} - conto #${row.table_bill_id}`,
            row.pr_metadata?.sumup_transaction_id ?? null
        );

        const updSplit = await queryWithRetry(
            `UPDATE table_bill_splits
             SET status = 'REFUNDED', released_at = CURRENT_TIMESTAMP
             WHERE id = $1
             RETURNING id, table_bill_id, amount_cents`,
            [splitId]
        );
        // Lo specchio LINK_ONLINE nel libro cassa segue la quota: stornato,
        // così la chiusura di cassa non conta denaro restituito.
        await queryWithRetry(
            `UPDATE table_bill_payments
             SET voided_at = CURRENT_TIMESTAMP, voided_by_user_id = $2, void_reason = 'Rimborso quota'
             WHERE table_bill_split_id = $1 AND voided_at IS NULL`,
            [splitId, req.user?.userId ?? null]
        );
        let updatedPr: any = null;
        if (row.payment_request_id) {
            const prUpd = await queryWithRetry(
                `UPDATE payment_requests
                 SET status = 'REFUNDED', updated_at = CURRENT_TIMESTAMP
                 WHERE id = $1
                 RETURNING *`,
                [row.payment_request_id]
            );
            updatedPr = prUpd.rows[0] || null;
            if (updatedPr?.reservation_id) broadcastReservationsUpdatedByIds([updatedPr.reservation_id]).catch(() => {});
        }

        // Il conto torna incassabile per la parte rimborsata solo se la
        // quota contava nel saldo (caso a) e il conto era SETTLED.
        let reopened = false;
        if (refundablePaid && row.bill_status === 'SETTLED') {
            const billUpd = await queryWithRetry(
                `UPDATE table_bills SET status = 'OPEN', closed_at = NULL
                 WHERE id = $1 AND status = 'SETTLED'
                 RETURNING *`,
                [row.table_bill_id]
            );
            reopened = (billUpd.rowCount ?? 0) > 0;
            if (reopened && socketService) {
                try { socketService.broadcastToAll(req.tenantId!, 'bill:opened', billUpd.rows[0]); } catch (_) {}
            }
        }

        const socketId = req.headers['x-socket-id'] as string;
        if (socketService) {
            try {
                socketService.broadcastToAll(req.tenantId!, 'bill:split-refunded', {
                    bill_id: row.table_bill_id, split_id: splitId, amount_cents: row.amount_cents,
                }, socketId);
                if (updatedPr) socketService.broadcastToAll(req.tenantId!, 'paymentRequest:updated', updatedPr);
            } catch (_) {}
        }

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId, req.user.email, req.user.email,
                ActivityAction.UPDATE, ResourceType.RESERVATION,
                row.reservation_id,
                `Rimborsata quota ${formatEuroMinor(row.amount_cents)}${row.claimant_label ? ' di ' + row.claimant_label : ''} (conto #${row.table_bill_id}${reopened ? ', conto riaperto' : ''})`
            );
        }

        res.json({ ok: true, split_id: splitId, bill_id: row.table_bill_id, reopened });
    } catch (err: any) {
        console.error('POST /bills/splits/:id/refund error:', err);
        res.status(502).json({ error: 'Rimborso non riuscito', detail: err?.message });
    }
});


// ============================================
// PUBLIC PAY-AT-TABLE (no auth, share_token gated)
// ============================================
// The endpoints below back the /pay/:token mobile page guests hit after
// scanning the QR. No login: the opaque `share_token` (~192 bit entropy,
// nulled on close/void) is the only credential. We rate-limit per IP to
// discourage token-brute-forcing and to shield Revolut from claim
// storms; the token itself is unguessable so the limit is generous.

const publicPayLimiter = rateLimit({
    windowMs: 60 * 1000,
    limit: 60,
    standardHeaders: 'draft-7',
    legacyHeaders: false,
    message: { error: 'rate_limited', message: 'Troppe richieste, riprova tra qualche secondo.' },
});

// Second, tighter limit specifically for the claim endpoint keyed by
// share_token: an attacker who knows one token can't lock every split by
// spamming CLAIMED+release cycles (each claim briefly holds capacity for
// the 5-min TTL). Applied *in addition* to publicPayLimiter — the IP
// limit stays as a broader shield against token-enumeration.
const publicPayClaimLimiter = rateLimit({
    windowMs: 60 * 1000,
    limit: 10,
    standardHeaders: 'draft-7',
    legacyHeaders: false,
    keyGenerator: (req) => `token:${req.params.token || 'unknown'}`,
    message: { error: 'rate_limited', message: 'Troppe richieste per questo conto, riprova tra qualche secondo.' },
});

// Sanitizes a split for public consumption: hides ids that could enable
// tampering, keeps only what the UI needs to render "someone claimed X€".
const publicSplitView = (s: any) => ({
    kind: s.kind,
    amount_cents: s.amount_cents,
    claimant_label: s.claimant_label,
    status: s.status,
});

// Helper: fetches a bill by share_token limited to active states. Returns
// null if not found / not active — callers respond with 404 in both cases
// so we don't leak whether the token ever existed.
// Lookup GLOBALE di proposito: lo share_token È il meccanismo con cui il
// flusso senza JWT risale alla riga, e quindi al tenant — la riga trovata
// porta il suo tenant_id e tutto ciò che segue è scopato su quello.
async function loadBillByToken(token: string) {
    const rs = await queryWithRetry(
        `SELECT id, tenant_id, reservation_id, table_id, total_cents, covers, currency,
                items, status, share_token, opened_at, closed_at,
                opened_by_user_id, closed_by_user_id, external_ref,
                cash_settled_cents, tip_cents, notes
         FROM table_bills
         WHERE share_token = $1
           AND status IN ('OPEN','LOCKED')
         LIMIT 1`,
        [token]
    );
    return rs.rows[0] || null;
}

// GET /pay/:token — the mobile page fetches this on load and after any
// action. Response mirrors the authenticated GET, minus internal ids on
// the splits.
app.get('/pay/:token', publicPayLimiter, async (req, res) => runAsPlatform(async () => {
    try {
        const token = String(req.params.token || '');
        if (!token || token.length < 20) return res.status(404).json({ error: 'Not found' });

        const bill = await loadBillByToken(token);
        if (!bill) return res.status(404).json({ error: 'Not found' });

        // When the operator disables the feature mid-service, guests scanning
        // a still-valid QR get a 404 like any expired token — the waiter
        // handles the payment through the normal channel. Il flag è quello del
        // ristorante del conto, risolto dalla riga stessa.
        if (!(await isPayAtTableActive(bill.tenant_id))) {
            return res.status(404).json({ error: 'Not found' });
        }

        const splitsRows = await queryWithRetry(
            `SELECT kind, amount_cents, claimant_label, status
             FROM table_bill_splits
             WHERE table_bill_id = $1
             ORDER BY claimed_at ASC`,
            [bill.id]
        );
        // Incassi registrati in cassa dallo staff (contanti, POS, …): per
        // l'ospite sono denaro già versato come le quote PAID — entrano nella
        // barra e nel residuo, ma non nella lista dei paganti (come l'acconto).
        const staffPaidCents = await staffPaidCentsForBill(bill.id);
        const paidCents = splitsRows.rows
            .filter((r: any) => r.status === 'PAID')
            .reduce((sum: number, r: any) => sum + Number(r.amount_cents || 0), 0) + staffPaidCents;
        const claimedCents = splitsRows.rows
            .filter((r: any) => r.status === 'CLAIMED' || r.status === 'PAID')
            .reduce((sum: number, r: any) => sum + Number(r.amount_cents || 0), 0) + staffPaidCents;
        const residual = Math.max(0, bill.total_cents - claimedCents);
        // Acconto già versato: quota PAID di kind='deposit'. Già dentro
        // paidCents/claimedCents (quindi già scalato dal residuo e dalla barra);
        // esposto a parte per la riga "Acconto −€X" e tolto dalla lista dei
        // paganti, dove sarebbe letto come una persona che ha pagato la sua parte.
        const depositCreditCents = splitsRows.rows
            .filter((r: any) => r.status === 'PAID' && r.kind === 'deposit')
            .reduce((sum: number, r: any) => sum + Number(r.amount_cents || 0), 0);

        // Righe del conto e quali sono già prese: sbloccano lo split per
        // piatto, che è il modo in cui la gente divide davvero il conto
        // ("io ho preso solo l'antipasto"). Disponibile solo quando il
        // dettaglio esiste (comanda dal gestionale) e la somma delle righe
        // coincide col totale: con uno sconto in mezzo, pagare "la propria
        // riga" addebiterebbe più del dovuto.
        const claimedItemRows = await queryWithRetry(
            `SELECT item_ids FROM table_bill_splits
             WHERE table_bill_id = $1 AND status IN ('CLAIMED','PAID') AND item_ids IS NOT NULL`,
            [bill.id]
        );
        const takenItemIds = new Set<number>();
        for (const r of claimedItemRows.rows) {
            for (const id of (Array.isArray(r.item_ids) ? r.item_ids : [])) takenItemIds.add(Number(id));
        }
        const billItems: any[] = Array.isArray(bill.items) ? bill.items : [];
        const itemsSum = billItems.reduce(
            (n: number, i: any) => n + Number(i.unit_price_cents || 0) * Number(i.qty || 0), 0
        );
        const perItemAvailable = billItems.length > 0 && itemsSum === bill.total_cents;

        res.json({
            bill: {
                total_cents: bill.total_cents,
                covers: bill.covers,
                currency: bill.currency,
                status: bill.status,
            },
            splits: splitsRows.rows.filter((r: any) => r.kind !== 'deposit').map(publicSplitView),
            paid_cents: paidCents,
            claimed_cents: claimedCents,
            deposit_credit_cents: depositCreditCents,
            residual_cents: residual,
            per_item_available: perItemAvailable,
            items: perItemAvailable
                ? billItems.map((i: any) => ({
                    id: Number(i.order_item_id),
                    name: i.name,
                    qty: Number(i.qty),
                    total_cents: Number(i.unit_price_cents) * Number(i.qty),
                    taken: takenItemIds.has(Number(i.order_item_id)),
                }))
                : [],
        });
    } catch (err: any) {
        console.error('GET /pay/:token error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
}));

// GET /pay/:token/qr.png — publicly-fetchable PNG of the pay page URL,
// used as the header media in the WhatsApp template so guests see the
// QR inline in the chat. Deliberately does NOT load the bill: the QR
// only encodes the same URL that was already in the request path (no
// data leak), and Meta's template approval / cache warm-up hits this
// endpoint with the sample token, which won't correspond to any real
// bill. Gated on the feature flag and on a minimum token shape.
app.get('/pay/:token/qr.png', publicPayLimiter, async (req, res) => runAsPlatform(async () => {
    try {
        const token = String(req.params.token || '');
        if (!token || token.length < 20 || !/^[A-Za-z0-9_-]+$/.test(token)) {
            return res.status(404).send('Not found');
        }
        // Il PNG non carica il conto di proposito (vedi sopra), quindi non c'è
        // una riga da cui risalire al tenant: si risolve dal dominio chiamato
        // (tenant_domains, Fase C3); senza dominio custom resta il tenant 1
        // finché il token del conto non porterà il tenant nell'URL.
        const qrTenantId = (await resolveTenantForPublicRequest(req)) ?? PUBLIC_TENANT_ID;
        if (!(await isPayAtTableActive(qrTenantId))) {
            return res.status(404).send('Not found');
        }
        const publicUrl = `${payAtTableBaseUrl()}/pay/${token}`;
        const png = await QRCode.toBuffer(publicUrl, {
            errorCorrectionLevel: 'M',
            margin: 2,
            width: 512,
        });
        res.setHeader('Content-Type', 'image/png');
        // Long cache: the PNG is a pure function of the token, so it
        // never changes; freshness only matters when a bill is voided,
        // and in that case Meta has already delivered the message.
        res.setHeader('Cache-Control', 'public, max-age=86400, immutable');
        res.send(png);
    } catch (err: any) {
        console.error('GET /pay/:token/qr.png error:', err);
        res.status(500).send('Internal server error');
    }
}));

// POST /pay/:token/claim — reserves a split and creates a Revolut order.
// Body: { kind: 'equal_share'|'fixed_amount', amount_cents?: number,
//         claimant_label?: string }
//   - equal_share → amount = ceil(total/covers) (per invariance we round
//     up so the last claimant doesn't get stuck with a fractional euro;
//     residual is still enforced by the trigger)
//   - fixed_amount → uses the supplied amount_cents
// Concurrency: SELECT ... FOR UPDATE on the bill row serializes concurrent
// claims (two guests scanning at the same instant). The trigger from PR 1
// is the ultimate authority — if it fires we surface a 409 with the
// current max_allowed.
// Lo scontrino digitale dell'ospite: il QR sull'esito di chiusura porta la
// SPA su /scontrino/<token>, che legge questo JSON. Il token è la capability
// (256 bit, mai riusato): mostra SOLO quel documento, senza login — lo stesso
// schema dello share_token del conto, ma sopravvive alla chiusura perché lo
// scontrino si mostra anche il giorno dopo. Lookup globale e runAsPlatform
// come le altre route per token: è la riga trovata a dire il tenant.
app.get('/scontrino/:token', publicPayLimiter, async (req, res) => runAsPlatform(async () => {
    try {
        const token = String(req.params.token || '');
        if (!token || token.length < 32) return res.status(404).json({ error: 'Not found' });
        const rs = await queryWithRetry(
            // Solo scontrini nativi: quelli Passepartout li stampa l'RT di
            // cassa e la riga qui non ha il dettaglio (request NULL) — la
            // pagina mostrerebbe un documento vuoto.
            `SELECT fd.tenant_id, fd.status, fd.doc_number, fd.total_cents,
                    fd.fiscal_id_snapshot, fd.request, fd.response, fd.confirmed_at, fd.voided_at,
                    t.name AS table_name
             FROM fiscal_documents fd
             JOIN table_bills b ON b.id = fd.table_bill_id AND b.tenant_id = fd.tenant_id
             LEFT JOIN tables t ON t.id = b.table_id AND t.tenant_id = b.tenant_id
             WHERE fd.public_token = $1 AND fd.doc_type = 'RECEIPT'
               AND fd.provider NOT IN ('passepartout', 'external_rt') AND fd.status IN ('CONFIRMED', 'VOIDED')`,
            [token]
        );
        const doc = rs.rows[0];
        if (!doc) return res.status(404).json({ error: 'Not found' });
        const identity = businessIdentity(doc.tenant_id);
        const payload = doc.request ?? {};
        const respData = doc.response?.data ?? {};
        const euroToCents = (s: unknown): number => Math.round((parseFloat(String(s ?? '0')) || 0) * 100);
        res.json({
            business: {
                name: identity.name,
                address: identity.address || null,
                vat_number: doc.fiscal_id_snapshot ?? null,
            },
            receipt: {
                status: doc.status,
                doc_number: doc.doc_number ?? respData.document_number ?? null,
                document_date: respData.document_date ?? doc.confirmed_at,
                voided_at: doc.voided_at,
                table_name: doc.table_name ?? null,
                total_cents: doc.total_cents,
                items: (Array.isArray(payload.items) ? payload.items : []).map((i: any) => ({
                    description: String(i.description ?? ''),
                    quantity: parseFloat(String(i.quantity ?? '1')) || 1,
                    unit_price_cents: euroToCents(i.unit_price),
                    vat_rate_code: String(i.vat_rate_code ?? ''),
                })),
                cash_cents: euroToCents(payload.cash_payment_amount),
                electronic_cents: euroToCents(payload.electronic_payment_amount),
                ticket_cents: euroToCents(payload.ticket_restaurant_payment_amount),
            },
        });
    } catch (err: any) {
        console.error('GET /scontrino/:token error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
}));

app.post('/pay/:token/claim', publicPayLimiter, publicPayClaimLimiter, async (req, res) => runAsPlatform(async () => {
    const client = await pool.connect();
    try {
        const token = String(req.params.token || '');
        if (!token || token.length < 20) return res.status(404).json({ error: 'Not found' });

        const kind = String(req.body?.kind || '');
        if (kind !== 'equal_share' && kind !== 'fixed_amount' && kind !== 'per_item') {
            return res.status(400).json({ error: 'kind must be equal_share, fixed_amount or per_item' });
        }
        const rawLabel = typeof req.body?.claimant_label === 'string' ? req.body.claimant_label.trim().slice(0, 40) : '';
        const claimantLabel = rawLabel || null;

        await client.query('BEGIN');

        // Lock the bill row so a parallel claim can't oversubscribe.
        // t.name is the REAL table number shown in the room (e.g. "23"), not
        // the internal id — it feeds the payment descriptions below.
        const billRs = await client.query(
            `SELECT b.id, b.tenant_id, b.total_cents, b.covers, b.status, b.reservation_id, b.items,
                    t.name AS table_name
             FROM table_bills b
             LEFT JOIN tables t ON t.id = b.table_id AND t.tenant_id = b.tenant_id
             WHERE b.share_token = $1
               AND b.status IN ('OPEN','LOCKED')
             FOR UPDATE OF b`,
            [token]
        );
        if (billRs.rowCount === 0) {
            await client.query('ROLLBACK');
            return res.status(404).json({ error: 'Not found' });
        }
        const bill = billRs.rows[0];
        // Il flag del ristorante del conto: risolto DOPO il lookup per token,
        // perché è la riga a dire di chi è il conto.
        if (!(await isPayAtTableActive(bill.tenant_id))) {
            await client.query('ROLLBACK');
            return res.status(404).json({ error: 'Not found' });
        }
        const billLabel = bill.table_name ? `tavolo ${bill.table_name}` : `conto #${bill.id}`;

        // Compute claimed_cents under the lock so the residual is
        // authoritative at insert time. Gli incassi staff del libro cassa
        // contano come le quote: quello che il cameriere ha già preso in
        // contanti non è più reclamabile dal QR.
        const sumRs = await client.query(
            `SELECT COALESCE(SUM(amount_cents), 0)::int AS claimed_cents
             FROM table_bill_splits
             WHERE table_bill_id = $1 AND status IN ('CLAIMED','PAID')`,
            [bill.id]
        );
        const staffPaid = await staffPaidCentsForBill(bill.id, client);
        const claimed = Number(sumRs.rows[0].claimed_cents || 0) + staffPaid;
        const residual = bill.total_cents - claimed;
        if (residual <= 0) {
            await client.query('ROLLBACK');
            return res.status(409).json({ error: 'Bill already fully claimed', max_allowed_cents: 0 });
        }

        let amount: number;
        let claimedItemIds: number[] | null = null;
        if (kind === 'per_item') {
            const requested = Array.isArray(req.body?.item_ids)
                ? req.body.item_ids.map((n: any) => Number(n)).filter((n: number) => Number.isFinite(n))
                : [];
            if (requested.length === 0) {
                await client.query('ROLLBACK');
                return res.status(400).json({ error: 'item_ids must be a non-empty array' });
            }
            const billItems: any[] = Array.isArray(bill.items) ? bill.items : [];
            const itemsSum = billItems.reduce(
                (n: number, i: any) => n + Number(i.unit_price_cents || 0) * Number(i.qty || 0), 0
            );
            // Con uno sconto sul conto la somma delle righe non torna: pagare
            // "la propria riga" addebiterebbe più del dovuto, quindi lo split
            // per piatto non è disponibile.
            if (billItems.length === 0 || itemsSum !== bill.total_cents) {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'Per-item split not available for this bill' });
            }

            // Righe già impegnate da altri: due ospiti non possono pagare lo
            // stesso piatto.
            const takenRs = await client.query(
                `SELECT item_ids FROM table_bill_splits
                 WHERE table_bill_id = $1 AND status IN ('CLAIMED','PAID') AND item_ids IS NOT NULL`,
                [bill.id]
            );
            const taken = new Set<number>();
            for (const r of takenRs.rows) {
                for (const id of (Array.isArray(r.item_ids) ? r.item_ids : [])) taken.add(Number(id));
            }
            const conflict = requested.filter((id: number) => taken.has(id));
            if (conflict.length > 0) {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'Some items are already claimed', conflicting_item_ids: conflict });
            }

            const byId = new Map(billItems.map((i: any) => [Number(i.order_item_id), i]));
            let sum = 0;
            for (const id of requested) {
                const it = byId.get(id);
                if (!it) {
                    await client.query('ROLLBACK');
                    return res.status(400).json({ error: 'Unknown item', item_id: id });
                }
                sum += Number(it.unit_price_cents) * Number(it.qty);
            }
            if (sum <= 0) {
                await client.query('ROLLBACK');
                return res.status(400).json({ error: 'Selected items total zero' });
            }
            if (sum > residual) {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'Amount exceeds residual', max_allowed_cents: residual });
            }
            amount = sum;
            claimedItemIds = requested;
        } else if (kind === 'equal_share') {
            const covers = Math.max(1, Number(bill.covers) || 1);
            amount = Math.min(residual, Math.ceil(bill.total_cents / covers));
        } else {
            const raw = Number(req.body?.amount_cents);
            if (!Number.isFinite(raw) || raw <= 0) {
                await client.query('ROLLBACK');
                return res.status(400).json({ error: 'amount_cents must be a positive integer' });
            }
            amount = Math.round(raw);
            if (amount > residual) {
                await client.query('ROLLBACK');
                return res.status(409).json({ error: 'Amount exceeds residual', max_allowed_cents: residual });
            }
        }

        // 5-minute TTL on the reservation. Reconcile job (PR 4) will flip
        // stale CLAIMED rows to ABANDONED so their capacity is released.
        const expiresAt = new Date(Date.now() + 5 * 60 * 1000);

        let splitId: number;
        try {
            const ins = await client.query(
                `INSERT INTO table_bill_splits
                    (tenant_id, table_bill_id, kind, amount_cents, claimant_label, expires_at, status, item_ids)
                 VALUES ($7, $1, $2, $3, $4, $5, 'CLAIMED', $6::jsonb)
                 RETURNING id`,
                [bill.id, kind, amount, claimantLabel, expiresAt.toISOString(),
                 claimedItemIds ? JSON.stringify(claimedItemIds) : null, bill.tenant_id]
            );
            splitId = ins.rows[0].id;
        } catch (err: any) {
            // Trigger enforces sum ≤ total: if a parallel writer slipped
            // between our SELECT and INSERT (shouldn't happen given the
            // FOR UPDATE but the trigger is our belt-and-braces), surface
            // a friendly 409.
            await client.query('ROLLBACK');
            if (err?.code === '23514') {
                return res.status(409).json({ error: 'Bill capacity changed, retry', detail: err?.message });
            }
            throw err;
        }

        await client.query('COMMIT');

        // Create the gateway order AFTER commit — if the API call fails
        // the split stays CLAIMED and the reconcile job will abandon it
        // once expires_at passes, freeing the capacity.
        let checkoutUrl: string | null = null;
        let paymentRequestId: number | null = null;
        try {
            // Gateway e credenziali del ristorante del conto, non del tenant
            // storico: il denaro deve arrivare sul merchant giusto.
            if (!(await isPaymentConfiguredForFlow(bill.tenant_id, 'bill'))) {
                throw new Error(`${providerLabel(await getPaymentProviderForFlow(bill.tenant_id, 'bill'))} not configured`);
            }
            const order = await createPaymentOrder(bill.tenant_id, {
                amount,
                currency: 'EUR',
                description: `Conto ${billLabel} - quota${claimantLabel ? ' ' + claimantLabel : ''}`,
                reference: `bill_split:${splitId}`,
                flow: 'bill',
                // Back to the bill page after checkout (whatever method the
                // guest picked), so they see the progress bar advance
                // instead of landing on the provider default.
                redirectUrl: `${payAtTableBaseUrl()}/pay/${token}`,
            });
            checkoutUrl = order.checkoutUrl;

            const prIns = await queryWithRetry(
                `INSERT INTO payment_requests
                    (tenant_id, reservation_id, amount_cents, currency, description, status, provider,
                     provider_order_id, checkout_url, table_bill_split_id, metadata)
                 VALUES ($10, $1, $2, 'EUR', $3, $4, $5, $6, $7, $8, $9)
                 RETURNING id`,
                [
                    bill.reservation_id || null,
                    amount,
                    `Conto ${billLabel}`,
                    order.status,
                    order.provider,
                    order.id,
                    order.checkoutUrl,
                    splitId,
                    JSON.stringify({ ...order.metadata, bill_split_id: splitId }),
                    bill.tenant_id,
                ]
            );
            paymentRequestId = prIns.rows[0].id;

            await queryWithRetry(
                `UPDATE table_bill_splits SET payment_request_id = $1 WHERE id = $2`,
                [paymentRequestId, splitId]
            );
        } catch (err: any) {
            console.error('[pay] payment order creation failed for split', splitId, err?.message || err);
            // Non-fatal for the API response: the client gets the split
            // but no checkout_url — the UI can offer "riprova" via a new
            // claim after release.
        }

        try {
            socketService?.broadcastToAll(bill.tenant_id, 'bill:split-claimed', {
                bill_id: bill.id,
                split_id: splitId,
                kind,
                amount_cents: amount,
                claimant_label: claimantLabel,
            });
        } catch (_) {}

        res.status(201).json({
            split_id: splitId,
            amount_cents: amount,
            claimant_label: claimantLabel,
            expires_at: expiresAt.toISOString(),
            checkout_url: checkoutUrl,
            payment_request_id: paymentRequestId,
        });
    } catch (err: any) {
        try { await client.query('ROLLBACK'); } catch { /* noop */ }
        console.error('POST /pay/:token/claim error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    } finally {
        client.release();
    }
}));

// POST /pay/:token/release — voluntarily gives up an unpaid claim. Both
// the split_id and the token must match — this prevents someone with the
// token from cancelling a split they didn't create (still not
// authenticated, but at least you need to know the id you're releasing).
app.post('/pay/:token/release', publicPayLimiter, async (req, res) => runAsPlatform(async () => {
    try {
        const token = String(req.params.token || '');
        if (!token || token.length < 20) return res.status(404).json({ error: 'Not found' });

        const splitId = Number(req.body?.split_id);
        if (!Number.isFinite(splitId) || splitId <= 0) {
            return res.status(400).json({ error: 'split_id required' });
        }

        const bill = await loadBillByToken(token);
        if (!bill) return res.status(404).json({ error: 'Not found' });
        // Flag del ristorante del conto, risolto dalla riga (vedi GET /pay/:token).
        if (!(await isPayAtTableActive(bill.tenant_id))) {
            return res.status(404).json({ error: 'Not found' });
        }

        const upd = await queryWithRetry(
            `UPDATE table_bill_splits
             SET status = 'RELEASED', released_at = CURRENT_TIMESTAMP
             WHERE id = $1
               AND table_bill_id = $2
               AND status = 'CLAIMED'
             RETURNING id`,
            [splitId, bill.id]
        );
        if (upd.rowCount === 0) {
            return res.status(409).json({ error: 'Split not found or not releasable' });
        }

        try {
            socketService?.broadcastToAll(bill.tenant_id, 'bill:split-released', {
                bill_id: bill.id,
                split_id: splitId,
            });
        } catch (_) {}

        res.json({ released: true, split_id: splitId });
    } catch (err: any) {
        console.error('POST /pay/:token/release error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
}));


// ============================================
// INBOX (SMS / WhatsApp conversations)
// ============================================
// Conversations are grouped by the last 10 digits of the customer phone so
// that +39 / 39 / 0 prefix variants collapse into a single thread. We union
// outbound.to_phone_digits with inbound.from_phone_digits, pick the most
// recent message per group, and left-join reservations to surface the most
// recent customer_name for that number.

app.get('/messages/conversations', authenticate, requirePermission('reservations:view'), async (req, res) => {
    try {
        const result = await queryWithRetry(`
            WITH pairs AS (
                SELECT id, provider, channel, direction, body, sent_at, read_at,
                       reservation_id,
                       COALESCE(from_phone_digits, to_phone_digits) AS digits,
                       COALESCE(from_phone, to_phone) AS phone
                FROM outbound_messages
                WHERE tenant_id = $1
                  AND channel IN ('sms','whatsapp')
                  AND COALESCE(from_phone_digits, to_phone_digits) IS NOT NULL
                  -- Finestra di 12 mesi: non per velocità oggi (33ms su tutto
                  -- lo storico) ma per tenere stabile l'aggregazione quando la
                  -- tabella sarà 10x. Un thread fermo da un anno sparisce
                  -- dalla lista, non dal DB: riscrive il cliente e ricompare.
                  AND sent_at > now() - interval '12 months'
            ),
            keyed AS (
                SELECT *, right(digits, 10) AS phone_key
                FROM pairs
                WHERE length(digits) >= 8
            ),
            latest AS (
                SELECT DISTINCT ON (phone_key)
                    phone_key, phone, channel, direction, body, sent_at, reservation_id
                FROM keyed
                ORDER BY phone_key, sent_at DESC
            ),
            counts AS (
                SELECT phone_key,
                       COUNT(*) FILTER (WHERE direction = 'inbound' AND read_at IS NULL)::int AS unread_count,
                       MAX(sent_at) FILTER (WHERE direction = 'inbound') AS last_inbound_at
                FROM keyed
                GROUP BY phone_key
            ),
            -- Il link prenotazione del thread è il reservation_id più recente
            -- NON nullo, non quello dell'ultimo messaggio: così l'aggancio
            -- sopravvive a un nuovo messaggio in arrivo (che entra con
            -- reservation_id NULL e altrimenti azzererebbe il link).
            last_res AS (
                SELECT DISTINCT ON (phone_key) phone_key, reservation_id
                FROM keyed
                WHERE reservation_id IS NOT NULL
                ORDER BY phone_key, sent_at DESC
            )
            SELECT l.phone_key AS phone_digits,
                   l.phone,
                   l.channel      AS last_channel,
                   l.direction    AS last_direction,
                   l.body         AS last_body,
                   l.sent_at      AS last_sent_at,
                   lr.reservation_id AS last_reservation_id,
                   COALESCE(c.unread_count, 0)::int AS unread_count,
                   c.last_inbound_at,
                   r.customer_name
            FROM latest l
            LEFT JOIN counts c ON c.phone_key = l.phone_key
            LEFT JOIN last_res lr ON lr.phone_key = l.phone_key
            LEFT JOIN LATERAL (
                SELECT customer_name FROM reservations
                WHERE tenant_id = $1
                  AND right(regexp_replace(COALESCE(phone,''), '\D', '', 'g'), 10) = l.phone_key
                ORDER BY reservation_time DESC
                LIMIT 1
            ) r ON true
            ORDER BY l.sent_at DESC
            LIMIT 200
        `, [req.tenantId!]);
        res.json({ conversations: result.rows });
    } catch (err) {
        console.error('GET /messages/conversations error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Total unread inbound messages. Same number the InboxPage's header shows
