app.patch('/rooms/:id', authenticate, requirePermission('floorplan:full'), async (req, res) => {
    try {
        const { id } = req.params;
        const { is_closed } = req.body;
        if (typeof is_closed !== 'boolean') {
            return res.status(400).json({ error: 'is_closed must be boolean' });
        }
        const result = await queryWithRetry(
            'UPDATE rooms SET is_closed = $1 WHERE id = $2 AND tenant_id = $3 RETURNING *',
            [is_closed, id, req.tenantId!]
        );
        const updatedRoom = result.rows[0];
        if (!updatedRoom) {
            return res.status(404).json({ error: 'Room not found' });
        }

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.UPDATE,
                ResourceType.ROOM,
                parseInt(id, 10),
                updatedRoom.name,
                { is_closed }
            );
        }

        if (socketService) socketService.broadcastRoomUpdated(req.tenantId!, updatedRoom);

        res.json(updatedRoom);
    } catch (err) {
        console.error(err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

