// ============================================
// VOICE CALLS (ElevenLabs conversations)
// ============================================
// Browse the voice_calls table populated by the post-call webhook, plus a
// manual sync that pulls recent conversations from the ElevenLabs API for
// rows the webhook missed (timeouts, redeploys). Audio is streamed through
// the server so the ElevenLabs API key never reaches the browser.

const ELEVENLABS_API_KEY = process.env.ELEVENLABS_API_KEY || '';
const ELEVENLABS_AGENT_ID = process.env.ELEVENLABS_AGENT_ID || '';
const ELEVENLABS_API_BASE = 'https://api.elevenlabs.io/v1';

const VOICE_CALLS_ROLES: UserRole[] = [UserRole.OWNER, UserRole.GENERAL_MANAGER, UserRole.MANAGER];

const voiceCallsAuthorize = authorize(...VOICE_CALLS_ROLES);

// ============================================
// CONSUMI AI — telemetria token (pagina "Consumi AI", solo account admin)
// ============================================
// Due sorgenti, una per provider:
//  - Gemini: la tabella ai_token_usage, alimentata dal client a ogni chiamata
//    (usageMetadata). Nessuno storico prima dell'introduzione del tracking.
//  - ElevenLabs (Sofia): consumo live dall'API /user/subscription (crediti/
//    caratteri e reset) + aggregati dalle nostre voice_calls (n° chiamate,
//    secondi). Non serve una tabella nostra: ElevenLabs è la fonte di verità.

// Numero giorni della finestra, default 30, limitato a 1..365.
const parseUsageWindowDays = (raw: unknown): number => {
    const n = parseInt(String(raw ?? '30'), 10);
    if (!Number.isFinite(n)) return 30;
    return Math.min(Math.max(n, 1), 365);
};

// Registrazione di un evento d'uso token. Qualsiasi utente autenticato può
// scrivere: è il client (es. il report Dashboard) a segnalare il proprio
// consumo appena Gemini risponde. La lettura/aggregazione resta admin-only.
app.post('/ai-usage', authenticate, async (req: any, res) => {
    try {
        const clampToken = (v: any): number => {
            const n = Math.round(Number(v));
            if (!Number.isFinite(n) || n < 0) return 0;
            // Tetto di sicurezza contro valori assurdi da un client compromesso.
            return Math.min(n, 100_000_000);
        };
        const provider = String(req.body?.provider || '').trim().toLowerCase().slice(0, 20);
        const feature = String(req.body?.feature || '').trim().slice(0, 60);
        // ElevenLabs si legge live dalla sua API, non si logga qui.
        if (provider !== 'anthropic' && provider !== 'gemini') {
            return res.status(400).json({ error: 'Provider non supportato' });
        }
        if (!feature) {
            return res.status(400).json({ error: 'Feature obbligatoria' });
        }
        const model = req.body?.model ? String(req.body.model).trim().slice(0, 80) : null;
        const promptTokens = clampToken(req.body?.prompt_tokens);
        const outputTokens = clampToken(req.body?.output_tokens);
        // Se il client non manda il totale, lo ricaviamo dai due parziali.
        const totalTokens = clampToken(req.body?.total_tokens) || (promptTokens + outputTokens);

        await queryWithRetry(
            `INSERT INTO ai_token_usage (provider, feature, model, prompt_tokens, output_tokens, total_tokens, user_email, tenant_id)
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
            [provider, feature, model, promptTokens, outputTokens, totalTokens, (req.user?.email || null), req.tenantId!]
        );
        res.status(201).json({ ok: true });
    } catch (err) {
        console.error('POST /ai-usage error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Aggregati d'uso Gemini per la finestra richiesta.
app.get('/ai-usage/gemini', authenticate, requireDevBoardAdmin, async (req, res) => {
    try {
        const days = parseUsageWindowDays(req.query.days);

        const totalsQ = queryWithRetry(
            `SELECT COALESCE(SUM(prompt_tokens),0)::int AS prompt_tokens,
                    COALESCE(SUM(output_tokens),0)::int AS output_tokens,
                    COALESCE(SUM(total_tokens),0)::int  AS total_tokens,
                    COUNT(*)::int                        AS calls,
                    COALESCE(SUM(${COST_USD_SQL}),0)::float AS cost_usd,
                    COUNT(*) FILTER (WHERE ${UNPRICED_SQL})::int AS unpriced_calls,
                    MAX(created_at)                      AS last_at
             FROM ai_token_usage
             WHERE tenant_id = $2
               AND provider <> 'elevenlabs'
               AND created_at >= NOW() - make_interval(days => $1::int)`,
            [days, req.tenantId!]
        );
        const dailyQ = queryWithRetry(
            `SELECT to_char(created_at AT TIME ZONE 'Europe/Rome', 'YYYY-MM-DD') AS day,
                    COALESCE(SUM(prompt_tokens),0)::int AS prompt_tokens,
                    COALESCE(SUM(output_tokens),0)::int AS output_tokens,
                    COALESCE(SUM(total_tokens),0)::int  AS total_tokens,
                    COUNT(*)::int                        AS calls,
                    COALESCE(SUM(${COST_USD_SQL}),0)::float AS cost_usd
             FROM ai_token_usage
             WHERE tenant_id = $2
               AND provider <> 'elevenlabs'
               AND created_at >= NOW() - make_interval(days => $1::int)
             GROUP BY day
             ORDER BY day`,
            [days, req.tenantId!]
        );
        const byFeatureQ = queryWithRetry(
            `SELECT feature,
                    COALESCE(MAX(model), '') AS model,
                    COALESCE(SUM(total_tokens),0)::int AS total_tokens,
                    COUNT(*)::int AS calls,
                    COALESCE(SUM(${COST_USD_SQL}),0)::float AS cost_usd,
                    COUNT(*) FILTER (WHERE ${UNPRICED_SQL})::int AS unpriced_calls
             FROM ai_token_usage
             WHERE tenant_id = $2
               AND provider <> 'elevenlabs'
               AND created_at >= NOW() - make_interval(days => $1::int)
             GROUP BY feature
             ORDER BY total_tokens DESC`,
            [days, req.tenantId!]
        );

        const [totals, daily, byFeature] = await Promise.all([totalsQ, dailyQ, byFeatureQ]);
        res.json({
            days,
            totals: totals.rows[0],
            daily: daily.rows,
            byFeature: byFeature.rows,
            // Il tasso viaggia col dato: la pagina non deve avere una sua
            // idea di quanto vale un dollaro.
            usdEur: USD_EUR,
        });
    } catch (err) {
        console.error('GET /ai-usage/gemini error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Consumo Sofia/ElevenLabs: quota live dall'API + statistiche chiamate locali.
app.get('/ai-usage/elevenlabs', authenticate, requireDevBoardAdmin, async (req, res) => {
    try {
        const days = parseUsageWindowDays(req.query.days);

        // --- Quota live dall'API ElevenLabs (crediti/caratteri e reset) ------
        let subscription: any = null;
        let subscriptionError: string | null = null;
        if (!ELEVENLABS_API_KEY) {
            subscriptionError = 'ELEVENLABS_API_KEY non configurata';
        } else {
            try {
                const r = await fetch(`${ELEVENLABS_API_BASE}/user/subscription`, {
                    headers: { 'xi-api-key': ELEVENLABS_API_KEY },
                });
                if (r.ok) {
                    const d: any = await r.json();
                    subscription = {
                        tier: d.tier ?? null,
                        status: d.status ?? null,
                        character_count: d.character_count ?? null,
                        character_limit: d.character_limit ?? null,
                        next_reset_unix: d.next_character_count_reset_unix ?? null,
                        currency: d.currency ?? null,
                    };
                } else {
                    subscriptionError = `ElevenLabs ha risposto ${r.status}`;
                }
            } catch (e) {
                console.error('ElevenLabs subscription fetch error:', e);
                subscriptionError = 'Impossibile contattare ElevenLabs';
            }
        }

        // --- Statistiche chiamate dalla nostra tabella voice_calls ------------
        const callTotalsQ = queryWithRetry(
            `SELECT COUNT(*)::int AS calls,
                    COALESCE(SUM(duration_seconds),0)::int AS seconds,
                    MAX(created_at) AS last_at
             FROM voice_calls
             WHERE tenant_id = $2
               AND created_at >= NOW() - make_interval(days => $1::int)`,
            [days, req.tenantId!]
        );
        const callDailyQ = queryWithRetry(
            `SELECT to_char(created_at AT TIME ZONE 'Europe/Rome', 'YYYY-MM-DD') AS day,
                    COUNT(*)::int AS calls,
                    COALESCE(SUM(duration_seconds),0)::int AS seconds
             FROM voice_calls
             WHERE tenant_id = $2
               AND created_at >= NOW() - make_interval(days => $1::int)
             GROUP BY day
             ORDER BY day`,
            [days, req.tenantId!]
        );
        const callAllTimeQ = queryWithRetry(
            `SELECT COUNT(*)::int AS calls,
                    COALESCE(SUM(duration_seconds),0)::int AS seconds
             FROM voice_calls
             WHERE tenant_id = $1`,
            [req.tenantId!]
        );

        const [callTotals, callDaily, callAllTime] = await Promise.all([callTotalsQ, callDailyQ, callAllTimeQ]);
        res.json({
            days,
            subscription,
            subscriptionError,
            calls: {
                window: callTotals.rows[0],
                daily: callDaily.rows,
                allTime: callAllTime.rows[0],
            },
        });
    } catch (err) {
        console.error('GET /ai-usage/elevenlabs error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// List with optional filters. Default newest-first, capped to 200 rows.
app.get('/voice-calls', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const { from, to, q, linked, follow_up, phantom } = req.query as Record<string, string | undefined>;
        const limit = Math.min(Math.max(parseInt(String(req.query.limit ?? '50'), 10) || 50, 1), 200);
        const offset = Math.max(parseInt(String(req.query.offset ?? '0'), 10) || 0, 0);

        // Primo filtro sempre presente: il tenant. Entra in params prima di
        // limit/offset, così whereSql vale anche per la COUNT più sotto.
        const where: string[] = ['vc.tenant_id = $1'];
        const params: any[] = [req.tenantId!];

        if (from && /^\d{4}-\d{2}-\d{2}$/.test(from)) {
            params.push(from);
            where.push(`vc.created_at >= $${params.length}::date`);
        }
        if (to && /^\d{4}-\d{2}-\d{2}$/.test(to)) {
            params.push(to);
            where.push(`vc.created_at < ($${params.length}::date + INTERVAL '1 day')`);
        }
        if (q && q.trim()) {
            // Search across phone, summary, transcript, notes, and the linked
            // customer name so users can type "Mario" and find calls even when
            // the caller only appears in the customer registry, not the raw
            // ElevenLabs payload.
            params.push(`%${q.trim()}%`);
            const idx = params.length;
            where.push(
                `(vc.phone ILIKE $${idx}
                  OR vc.summary ILIKE $${idx}
                  OR vc.transcript ILIKE $${idx}
                  OR vc.notes ILIKE $${idx}
                  OR r.customer_name ILIKE $${idx}
                  OR EXISTS (
                      SELECT 1 FROM customers c2
                      WHERE c2.tenant_id = vc.tenant_id
                        AND c2.phone IS NOT NULL
                        AND vc.phone IS NOT NULL
                        AND length(regexp_replace(c2.phone, '\\D', '', 'g')) >= 8
                        AND right(regexp_replace(c2.phone, '\\D', '', 'g'), 10)
                          = right(regexp_replace(vc.phone, '\\D', '', 'g'), 10)
                        AND c2.name ILIKE $${idx}
                  ))`
            );
        }
        if (linked === 'true') where.push('vc.reservation_id IS NOT NULL');
        else if (linked === 'false') where.push('vc.reservation_id IS NULL');
        // Follow-up filter only makes sense on unlinked calls (calls with a
        // reservation don't need to be contacted back). We don't force
        // reservation_id IS NULL here so the UI can combine filters freely.
        if (follow_up === 'contacted') where.push("vc.follow_up_status = 'CONTACTED'");
        else if (follow_up === 'pending') where.push("(vc.follow_up_status IS NULL OR vc.follow_up_status = 'PENDING')");
        // "Da recuperare" filter — calls where the agent verbally confirmed
        // but never invoked the create-reservation tool. Excludes calls
        // already marked as recovered so the chip only surfaces open cases.
        if (phantom === 'true') where.push('vc.phantom_confirmation = TRUE AND vc.phantom_recovered = FALSE');

        const whereSql = where.length ? `WHERE ${where.join(' AND ')}` : '';

        params.push(limit);
        params.push(offset);
        // Match customers on the last 10 digits of the phone. `customers.phone`
        // is stored in mixed formats (E.164, national, bare digits) so we can't
        // rely on equality — right(10) covers Italian mobile/landline reliably.
        // LATERAL + LIMIT 1 avoids row explosion if two rows share a number.
        const result = await queryWithRetry(
            `SELECT vc.id,
                    vc.conversation_id,
                    vc.phone,
                    vc.duration_seconds,
                    vc.summary,
                    vc.reservation_id,
                    vc.created_at,
                    vc.follow_up_status,
                    vc.notes,
                    vc.follow_up_updated_at,
                    vc.phantom_confirmation,
                    vc.phantom_recovered,
                    vc.large_group_handoff,
                    vc.callback_requested,
                    vc.callback_name,
                    vc.callback_reason,
                    vc.callback_details,
                    u.full_name AS follow_up_updated_by_name,
                    r.customer_name AS reservation_customer_name,
                    r.reservation_time AS reservation_time,
                    r.guests AS reservation_guests,
                    r.reservation_status AS reservation_status,
                    cust.customer_id,
                    cust.customer_name
             FROM voice_calls vc
             LEFT JOIN reservations r ON r.id = vc.reservation_id AND r.tenant_id = vc.tenant_id
             LEFT JOIN users u ON u.id = vc.follow_up_updated_by
             LEFT JOIN LATERAL (
                 SELECT c.id AS customer_id, c.name AS customer_name
                 FROM customers c
                 WHERE vc.phone IS NOT NULL
                   AND c.phone IS NOT NULL
                   AND c.tenant_id = vc.tenant_id
                   AND length(regexp_replace(c.phone, '\\D', '', 'g')) >= 8
                   AND right(regexp_replace(c.phone, '\\D', '', 'g'), 10)
                     = right(regexp_replace(vc.phone, '\\D', '', 'g'), 10)
                 LIMIT 1
             ) cust ON true
             ${whereSql}
             ORDER BY vc.created_at DESC
             LIMIT $${params.length - 1} OFFSET $${params.length}`,
            params
        );

        const countResult = await queryWithRetry(
            `SELECT COUNT(*)::int AS total
             FROM voice_calls vc
             LEFT JOIN reservations r ON r.id = vc.reservation_id AND r.tenant_id = vc.tenant_id
             ${whereSql}`,
            params.slice(0, params.length - 2)
        );

        res.json({
            items: result.rows,
            total: countResult.rows[0]?.total ?? 0,
            limit,
            offset,
        });
    } catch (err) {
        console.error('GET /voice-calls error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Count of calls that need a follow-up: no reservation was created and the
// call is recent enough to still be actionable (last 7 days). Surfaces as a
// badge on the sidebar phone icon. Must be declared before `/voice-calls/:id`
// so Express doesn't route "pending-count" into the :id handler.
// Distinct on the last 10 phone digits so the badge matches the Chiamate
// list, which collapses repeated attempts from the same number into one
// card; calls without a phone still count one each.
app.get('/voice-calls/pending-count', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const result = await queryWithRetry(
            `SELECT COUNT(DISTINCT COALESCE(NULLIF(right(regexp_replace(phone, '\\D', '', 'g'), 10), ''), 'call-' || id))::int AS count
             FROM voice_calls
             WHERE tenant_id = $1
               AND reservation_id IS NULL
               AND (follow_up_status IS NULL OR follow_up_status = 'PENDING')
               AND created_at >= NOW() - INTERVAL '7 days'`,
            [req.tenantId!]
        );
        res.json({ count: result.rows[0]?.count ?? 0 });
    } catch (err) {
        console.error('GET /voice-calls/pending-count error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Bulk: flip every call still awaiting follow-up (no linked reservation,
// status NULL/PENDING) to CONTACTED in one shot. Powers the "segna tutte
// come ricontattate" button in Conversazioni — returns how many rows
// changed so the UI can report it. Declared before the `:id` routes.
app.post('/voice-calls/mark-all-contacted', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const result = await queryWithRetry(
            `UPDATE voice_calls
             SET follow_up_status = 'CONTACTED',
                 follow_up_updated_by = $1,
                 follow_up_updated_at = NOW()
             WHERE tenant_id = $2
               AND reservation_id IS NULL
               AND (follow_up_status IS NULL OR follow_up_status = 'PENDING')
             RETURNING id`,
            [req.user?.userId ?? null, req.tenantId!]
        );
        res.json({ updated: result.rows.length });
    } catch (err) {
        console.error('POST /voice-calls/mark-all-contacted error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Update follow-up state for a call: mark as contacted / pending, and store
// free-text notes for whoever picks it up next. Fields are patched
// individually — omitted fields stay as-is.
app.patch('/voice-calls/:id/follow-up', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const { status, notes } = req.body ?? {};
        const sets: string[] = [];
        const params: any[] = [];

        if (status !== undefined) {
            if (status !== 'PENDING' && status !== 'CONTACTED') {
                return res.status(400).json({ error: 'Invalid status' });
            }
            params.push(status);
            sets.push(`follow_up_status = $${params.length}`);
        }
        if (notes !== undefined) {
            if (notes !== null && typeof notes !== 'string') {
                return res.status(400).json({ error: 'Invalid notes' });
            }
            params.push(notes === null || notes.trim() === '' ? null : notes);
            sets.push(`notes = $${params.length}`);
        }
        if (sets.length === 0) return res.status(400).json({ error: 'No fields to update' });

        params.push(req.user?.userId ?? null);
        sets.push(`follow_up_updated_by = $${params.length}`);
        sets.push(`follow_up_updated_at = NOW()`);

        params.push(id);
        params.push(req.tenantId!);
        const result = await queryWithRetry(
            `UPDATE voice_calls SET ${sets.join(', ')}
             WHERE id = $${params.length - 1} AND tenant_id = $${params.length}
             RETURNING id, follow_up_status, notes, follow_up_updated_at`,
            params
        );
        if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        res.json(result.rows[0]);
    } catch (err) {
        console.error('PATCH /voice-calls/:id/follow-up error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Link a voice call to a reservation created from it (e.g. after a manual
// call-back). Also flips the follow-up state to CONTACTED so the call drops
// out of the pending queue.
app.patch('/voice-calls/:id/link', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const reservationIdRaw = req.body?.reservation_id;
        const reservationId = typeof reservationIdRaw === 'number'
            ? reservationIdRaw
            : parseInt(reservationIdRaw, 10);
        if (!Number.isFinite(reservationId)) return res.status(400).json({ error: 'Invalid reservation_id' });

        // Guardia FK cross-tenant (pattern B3): una prenotazione altrui non
        // si aggancia — 404, come se non esistesse.
        const resvOk = await queryWithRetry(
            'SELECT 1 FROM reservations WHERE id = $1 AND tenant_id = $2',
            [reservationId, req.tenantId!]
        );
        if (resvOk.rowCount === 0) return res.status(404).json({ error: 'Reservation not found' });

        // Also clears the phantom-recovery banner: if this call was flagged
        // as a phantom confirmation, linking a real reservation is exactly
        // the recovery we were asking staff to perform.
        const result = await queryWithRetry(
            `UPDATE voice_calls
             SET reservation_id = $1,
                 follow_up_status = 'CONTACTED',
                 follow_up_updated_at = NOW(),
                 follow_up_updated_by = $2,
                 phantom_recovered = CASE WHEN phantom_confirmation THEN TRUE ELSE phantom_recovered END
             WHERE id = $3 AND tenant_id = $4
             RETURNING id, reservation_id, follow_up_status, follow_up_updated_at, phantom_recovered`,
            [reservationId, req.user?.userId ?? null, id, req.tenantId!]
        );
        if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        res.json(result.rows[0]);
    } catch (err) {
        console.error('PATCH /voice-calls/:id/link error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Manual recovery: staff has verified the phantom confirmation (called back
// the customer, decided to leave it as cancelled, etc.) without necessarily
// linking a new reservation. Just flips phantom_recovered so the banner
// disappears from the detail modal.
app.patch('/voice-calls/:id/recover', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const result = await queryWithRetry(
            `UPDATE voice_calls
             SET phantom_recovered = TRUE
             WHERE id = $1 AND tenant_id = $2
             RETURNING id, phantom_confirmation, phantom_recovered`,
            [id, req.tenantId!]
        );
        if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        res.json(result.rows[0]);
    } catch (err) {
        console.error('PATCH /voice-calls/:id/recover error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Detail with full transcript.
app.get('/voice-calls/:id', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const result = await queryWithRetry(
            `SELECT vc.id,
                    vc.conversation_id,
                    vc.phone,
                    vc.duration_seconds,
                    vc.transcript,
                    vc.summary,
                    vc.reservation_id,
                    vc.created_at,
                    vc.follow_up_status,
                    vc.notes,
                    vc.follow_up_updated_at,
                    vc.phantom_confirmation,
                    vc.phantom_recovered,
                    vc.large_group_handoff,
                    vc.callback_requested,
                    vc.callback_name,
                    vc.callback_reason,
                    vc.callback_details,
                    u.full_name AS follow_up_updated_by_name,
                    r.customer_name AS reservation_customer_name,
                    r.reservation_time AS reservation_time,
                    r.guests AS reservation_guests,
                    r.reservation_status AS reservation_status,
                    cust.customer_id,
                    cust.customer_name
             FROM voice_calls vc
             LEFT JOIN reservations r ON r.id = vc.reservation_id AND r.tenant_id = vc.tenant_id
             LEFT JOIN users u ON u.id = vc.follow_up_updated_by
             LEFT JOIN LATERAL (
                 SELECT c.id AS customer_id, c.name AS customer_name
                 FROM customers c
                 WHERE vc.phone IS NOT NULL
                   AND c.phone IS NOT NULL
                   AND c.tenant_id = vc.tenant_id
                   AND length(regexp_replace(c.phone, '\\D', '', 'g')) >= 8
                   AND right(regexp_replace(c.phone, '\\D', '', 'g'), 10)
                     = right(regexp_replace(vc.phone, '\\D', '', 'g'), 10)
                 LIMIT 1
             ) cust ON true
             WHERE vc.id = $1 AND vc.tenant_id = $2`,
            [id, req.tenantId!]
        );
        if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        res.json(result.rows[0]);
    } catch (err) {
        console.error('GET /voice-calls/:id error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Stream the call recording from ElevenLabs. The browser hits this endpoint
// so the API key stays on the server. Audio is gated by the same RBAC as the
// transcript so a leaked URL can't be hot-linked from outside the app.
app.get('/voice-calls/:id/audio', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        if (!ELEVENLABS_API_KEY) {
            return res.status(503).json({ error: 'ELEVENLABS_API_KEY not configured' });
        }

        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const row = await queryWithRetry(
            'SELECT conversation_id FROM voice_calls WHERE id = $1 AND tenant_id = $2',
            [id, req.tenantId!]
        );
        if (row.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        const conversationId = row.rows[0].conversation_id;

        const upstream = await fetch(
            `${ELEVENLABS_API_BASE}/convai/conversations/${encodeURIComponent(conversationId)}/audio`,
            { headers: { 'xi-api-key': ELEVENLABS_API_KEY } }
        );

        if (!upstream.ok || !upstream.body) {
            const text = await upstream.text().catch(() => '');
            console.warn('[ElevenLabs] audio fetch failed', upstream.status, text.slice(0, 200));
            return res.status(upstream.status === 404 ? 404 : 502).json({
                error: upstream.status === 404 ? 'Audio not available' : 'Upstream audio fetch failed',
            });
        }

        const contentType = upstream.headers.get('content-type') || 'audio/mpeg';
        res.setHeader('Content-Type', contentType);
        const contentLength = upstream.headers.get('content-length');
        if (contentLength) res.setHeader('Content-Length', contentLength);
        res.setHeader('Cache-Control', 'private, max-age=300');

        const { Readable } = await import('stream');
        Readable.fromWeb(upstream.body as any).pipe(res);
    } catch (err) {
        console.error('GET /voice-calls/:id/audio error:', err);
        if (!res.headersSent) res.status(500).json({ error: 'Internal server error' });
    }
});

// Outbound SMS/WhatsApp history for a given call. We match on the last 10
// digits of the recipient phone against the call's phone so operator can see
// every message ever sent to that customer regardless of reservation linkage.
app.get('/voice-calls/:id/messages', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'Invalid id' });

        const callRow = await queryWithRetry(
            'SELECT phone FROM voice_calls WHERE id = $1 AND tenant_id = $2',
            [id, req.tenantId!]
        );
        if (callRow.rows.length === 0) return res.status(404).json({ error: 'Not found' });
        const phone: string | null = callRow.rows[0].phone;
        if (!phone) return res.json({ items: [] });

        const digits = String(phone).replace(/\D/g, '');
        if (digits.length < 8) return res.json({ items: [] });
        const suffix = digits.slice(-10);

        const result = await queryWithRetry(
            `SELECT id, provider, channel, to_phone, body, status, provider_sid,
                    reservation_id, sent_at, delivered_at, failed_at,
                    error_code, error_message
             FROM outbound_messages
             WHERE tenant_id = $2
               AND right(to_phone_digits, 10) = $1
             ORDER BY sent_at DESC
             LIMIT 50`,
            [suffix, req.tenantId!]
        );
        res.json({ items: result.rows });
    } catch (err) {
        console.error('GET /voice-calls/:id/messages error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Manual sync: pulls the agent's recent conversations from ElevenLabs and
// upserts any conversation_id we're missing (post-call webhook timeouts /
// redeploys lose calls otherwise). For each new conversation we fetch the
// detail to get transcript + summary + phone + duration; existing rows are
// left untouched so manual edits aren't clobbered.
app.post('/voice-calls/sync', authenticate, requireFeature('voice'), voiceCallsAuthorize, async (req, res) => {
    try {
        if (!ELEVENLABS_API_KEY) return res.status(503).json({ error: 'ELEVENLABS_API_KEY not configured' });
        if (!ELEVENLABS_AGENT_ID) return res.status(503).json({ error: 'ELEVENLABS_AGENT_ID not configured' });

        const listUrl = `${ELEVENLABS_API_BASE}/convai/conversations?agent_id=${encodeURIComponent(ELEVENLABS_AGENT_ID)}&page_size=30`;
        const listRes = await fetch(listUrl, { headers: { 'xi-api-key': ELEVENLABS_API_KEY } });
        if (!listRes.ok) {
            const text = await listRes.text().catch(() => '');
            console.warn('[ElevenLabs] sync list failed', listRes.status, text.slice(0, 200));
            return res.status(502).json({ error: 'Upstream list failed' });
        }
        const listJson = await listRes.json() as any;
        const conversations: any[] = Array.isArray(listJson?.conversations) ? listJson.conversations : [];

        const existing = await queryWithRetry(
            `SELECT conversation_id, phone FROM voice_calls WHERE conversation_id = ANY($1::text[]) AND tenant_id = $2`,
            [conversations.map(c => c.conversation_id).filter(Boolean), req.tenantId!]
        );
        const savedWithPhone = new Set<string>(existing.rows.filter(r => r.phone).map(r => r.conversation_id));
        const savedWithoutPhone = new Set<string>(existing.rows.filter(r => !r.phone).map(r => r.conversation_id));

        let imported = 0;
        let backfilled = 0;
        let skipped = 0;
        let failed = 0;

        for (const conv of conversations) {
            const conversationId: string | undefined = conv.conversation_id;
            if (!conversationId) { failed++; continue; }
            if (savedWithPhone.has(conversationId)) { skipped++; continue; }

            try {
                const detailRes = await fetch(
                    `${ELEVENLABS_API_BASE}/convai/conversations/${encodeURIComponent(conversationId)}`,
                    { headers: { 'xi-api-key': ELEVENLABS_API_KEY } }
                );
                if (!detailRes.ok) { failed++; continue; }
                const detail = await detailRes.json() as any;

                const rawTranscript = detail?.transcript;
                let transcript: string | undefined;
                if (Array.isArray(rawTranscript)) {
                    transcript = rawTranscript
                        .map((t: any) => {
                            const who = t.role || t.speaker || 'unknown';
                            const text = t.message ?? t.text ?? t.content ?? '';
                            return `${who}: ${text}`;
                        })
                        .join('\n');
                } else if (typeof rawTranscript === 'string') {
                    transcript = rawTranscript;
                }

                const summary: string | undefined =
                    (typeof detail?.analysis?.transcript_summary === 'string' ? detail.analysis.transcript_summary : undefined) ??
                    (typeof detail?.summary === 'string' ? detail.summary : undefined);

                const duration = Number(
                    detail?.metadata?.call_duration_secs ??
                    detail?.metadata?.call_duration_seconds ??
                    detail?.call_duration_secs
                );

                const phoneRaw: string | undefined =
                    detail?.metadata?.phone_call?.external_number ||
                    detail?.metadata?.phone_number ||
                    detail?.metadata?.phone;

                if (savedWithoutPhone.has(conversationId)) {
                    // Backfill only the phone — leave transcript/summary/duration
                    // untouched to preserve any staff edits or fields already set
                    // by the post-call webhook.
                    if (!phoneRaw) { skipped++; continue; }
                    await recordVoiceCall(req.tenantId!, {
                        conversation_id: conversationId,
                        phone: normalizeItalianPhone(phoneRaw),
                    });
                    backfilled++;
                } else {
                    await recordVoiceCall(req.tenantId!, {
                        conversation_id: conversationId,
                        phone: phoneRaw ? normalizeItalianPhone(phoneRaw) : undefined,
                        duration_seconds: Number.isFinite(duration) ? Math.trunc(duration) : undefined,
                        transcript,
                        summary,
                    });
                    imported++;
                }
            } catch (err) {
                console.warn('[ElevenLabs] sync detail failed for', conversationId, err);
                failed++;
            }
        }

        res.json({ imported, backfilled, skipped, failed, total_fetched: conversations.length });
    } catch (err) {
        console.error('POST /voice-calls/sync error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// ============================================
// FEATURE FLAGS (app_settings)
// ============================================
// Boolean toggles managed from the Settings page. Used to pause the public
// booking form and the voice agent without redeploying. Reads hit the DB
// directly — the endpoints they gate are low-volume (a handful per minute
// at most), so caching isn't worth the complexity.

type FeatureFlagKey = 'public_bookings_enabled' | 'voice_agent_enabled' | 'voice_bookings_suspended' | 'voice_double_seating_enabled' | 'pay_at_table_enabled' | 'table_orders_enabled' | 'ai_messages_enabled' | 'digital_menu_enabled' | 'passe_enabled';
const FEATURE_FLAG_KEYS: FeatureFlagKey[] = ['public_bookings_enabled', 'voice_agent_enabled', 'voice_bookings_suspended', 'voice_double_seating_enabled', 'pay_at_table_enabled', 'table_orders_enabled', 'ai_messages_enabled', 'digital_menu_enabled', 'passe_enabled'];

async function getFeatureFlag(tenantId: number, key: FeatureFlagKey, fallback: boolean): Promise<boolean> {
    try {
        const result = await queryWithRetry('SELECT value FROM app_settings WHERE tenant_id = $1 AND key = $2', [tenantId, key]);
        if (result.rowCount === 0) return fallback;
        return Boolean(result.rows[0].value);
    } catch (err) {
        console.error(`[feature-flag] failed to read ${key}, falling back to ${fallback}:`, err);
        return fallback;
    }
}

const FEATURE_FLAG_DEFAULTS: Record<FeatureFlagKey, boolean> = {
    public_bookings_enabled: false,
    voice_agent_enabled: true,
    voice_bookings_suspended: false,
    // Spento di default: il doppio turno (secondo giro sullo stesso tavolo
    // nello stesso shift) dipende dallo stile di servizio della serata — oggi
    // lo decide lo staff a mano. Acceso, i percorsi voce valutano
    // l'occupazione per sovrapposizione di finestre orarie invece che per
    // intero turno (elevenlabsService/roomOccupancyService).
    voice_double_seating_enabled: false,
    // Off by default: the pay-at-table + split-bill flow depends on Revolut
    // being configured and the QR link being physically distributed at the
    // table. Owner opts in from Settings once ready.
    pay_at_table_enabled: false,
    // Off by default: il modulo comande resta spento finché non c'è una UI
    // che lo usi (PR 3). Gli endpoint esistono ma rispondono 403.
    table_orders_enabled: false,
    // Off by default: il menu digitale pubblico si accende dal QR modal
    // della pagina Menu quando il ristoratore è pronto a esporlo.
    digital_menu_enabled: false,
    // Spento finché il gestore non scrive le regole della casa: senza base di
    // conoscenza il modello non avrebbe da cosa rispondere.
    ai_messages_enabled: false,
    // Acceso di default: è il flusso storico (il passe lancia e serve). Nei
    // ristoranti senza passe si spegne da Impostazioni → Sala e cucina: la
    // pagina Passe sparisce dal menu e i verbi chiama/servito passano alla
    // comanda del cameriere. È solo UI: le route restano aperte a entrambi
    // i permessi, il flag decide chi ha il bottone davanti.
    passe_enabled: true,
};

app.get('/settings/features', authenticate, async (req, res) => {
    try {
        const result = await queryWithRetry(
            'SELECT key, value FROM app_settings WHERE tenant_id = $1 AND key = ANY($2)',
            [req.tenantId!, FEATURE_FLAG_KEYS]
        );
        const flags: Record<string, boolean> = { ...FEATURE_FLAG_DEFAULTS };
        for (const row of result.rows) {
            flags[row.key] = Boolean(row.value);
        }
        // Senza l'add-on venduto il flag operativo si maschera a false: ogni
        // superficie della SPA che lo legge (Pagamenti, prenotazioni, card
        // Impostazioni) vede il modulo spento da UN punto solo, senza dover
        // conoscere gli entitlement una per una.
        if (!(await isFeatureEnabledForTenant(req.tenantId!, 'pay_at_table'))) {
            flags.pay_at_table_enabled = false;
        }
        res.json(flags);
    } catch (err) {
        console.error('Error fetching feature flags:', err);
        res.status(500).json({ error: 'Failed to fetch feature flags' });
    }
});

// Channel-specific settings — numeric or free-text. Booleans stay in
// /settings/features so existing FeatureFlags typing isn't polluted. Add new
// fields by extending the key/default map and the PUT validator below.
const VOICE_LARGE_GROUP_KEY = 'voice_large_group_threshold';
const VOICE_LARGE_GROUP_DEFAULT = 8;
const VOICE_SUSPENSION_CALLBACK_KEY = 'voice_bookings_suspension_callback_time';
const VOICE_SUSPENSION_CALLBACK_DEFAULT = '19:00';
// Messaggio iniziale di Sofia, testo libero. Vuoto ⇒ default hardcoded nel
// webhook init-conversation (vedi renderVoiceFirstMessage). Cap difensivo per
// evitare payload assurdi verso ElevenLabs.
const VOICE_FIRST_MESSAGE_KEY = 'voice_first_message';
const VOICE_FIRST_MESSAGE_MAX = 500;

async function getVoiceFirstMessage(tenantId: number): Promise<string> {
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, VOICE_FIRST_MESSAGE_KEY]
        );
        const raw = result.rows[0]?.text_value;
        return typeof raw === 'string' ? raw : '';
    } catch (err) {
        console.error(`[channel-settings] failed to read ${VOICE_FIRST_MESSAGE_KEY}:`, err);
        return '';
    }
}

async function getVoiceLargeGroupThreshold(tenantId: number): Promise<number> {
    try {
        const result = await queryWithRetry(
            'SELECT int_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, VOICE_LARGE_GROUP_KEY]
        );
        const raw = result.rows[0]?.int_value;
        const n = Number(raw);
        if (Number.isFinite(n) && n >= 1 && n <= 50) return n;
        return VOICE_LARGE_GROUP_DEFAULT;
    } catch (err) {
        console.error(`[channel-settings] failed to read ${VOICE_LARGE_GROUP_KEY}, falling back to ${VOICE_LARGE_GROUP_DEFAULT}:`, err);
        return VOICE_LARGE_GROUP_DEFAULT;
    }
}

async function getVoiceSuspensionCallbackTime(tenantId: number): Promise<string> {
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, VOICE_SUSPENSION_CALLBACK_KEY]
        );
        const raw = result.rows[0]?.text_value;
        if (typeof raw === 'string' && HHMM_RE.test(raw)) return raw;
        return VOICE_SUSPENSION_CALLBACK_DEFAULT;
    } catch (err) {
        console.error(`[channel-settings] failed to read ${VOICE_SUSPENSION_CALLBACK_KEY}, falling back to ${VOICE_SUSPENSION_CALLBACK_DEFAULT}:`, err);
        return VOICE_SUSPENSION_CALLBACK_DEFAULT;
    }
}

const VOICE_SUSPENSION_SCHEDULE_KEY = 'voice_bookings_suspension_schedule';
const PUBLIC_BOOKINGS_BLOCKS_KEY = 'public_bookings_blocks';
const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
type ScheduledSuspension = { date: string; start_time: string; end_time: string; callback_time?: string };
// Web-booking block: a specific date, optionally scoped to a single shift.
// `shift = 'ALL'` blocks the whole day. Keeps the operator's mental model
// aligned with how they think about the service (turno, non timestamp).
type PublicBookingBlock = { date: string; shift: 'LUNCH' | 'DINNER' | 'ALL' };
const PUBLIC_BLOCK_SHIFTS = new Set(['LUNCH', 'DINNER', 'ALL']);

function isValidPublicBookingBlock(e: any): e is PublicBookingBlock {
    if (!e || typeof e !== 'object') return false;
    if (typeof e.date !== 'string' || !ISO_DATE_RE.test(e.date)) return false;
    if (typeof e.shift !== 'string' || !PUBLIC_BLOCK_SHIFTS.has(e.shift)) return false;
    return true;
}

async function getPublicBookingBlocks(tenantId: number): Promise<PublicBookingBlock[]> {
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, PUBLIC_BOOKINGS_BLOCKS_KEY]
        );
        const raw = result.rows[0]?.text_value;
        if (typeof raw !== 'string' || !raw.trim()) return [];
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(isValidPublicBookingBlock);
    } catch (err) {
        console.error(`[channel-settings] failed to read ${PUBLIC_BOOKINGS_BLOCKS_KEY}:`, err);
        return [];
    }
}

// Purge blocks whose date is already in the past so the settings screen
// doesn't accumulate stale rows over time. Runs opportunistically at read
// time — cheap since the array is small.
function pruneExpiredBlocks<T extends { date: string }>(blocks: T[]): T[] {
    const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit' });
    return blocks.filter(b => b.date >= today);
}

// Truthy when a booking for {date, shift} is refused by the operator via
// Settings → Prenotazioni web. A day-wide block (`shift = 'ALL'`) matches
// any shift on that date.
function isPublicBookingBlocked(date: string, shift: 'LUNCH' | 'DINNER', blocks: PublicBookingBlock[]): boolean {
    for (const b of blocks) {
        if (b.date !== date) continue;
        if (b.shift === 'ALL' || b.shift === shift) return true;
    }
    return false;
}

// Voice-booking block on the *requested* date: unlike the scheduled
// suspensions (which silence Sofia while the window is running), this blocks
// the target date the caller asks for — e.g. a fixed-menu holiday the staff
// wants to handle personally. Sofia stays on the phone and takes any other
// date; for a blocked one she invites the caller to ring back in the hours
// the operator wrote in `callback_hours`.
const VOICE_DATE_BLOCKS_KEY = 'voice_bookings_date_blocks';
type VoiceDateBlock = { date: string; shift: 'LUNCH' | 'DINNER' | 'ALL'; callback_hours?: string };

function isValidVoiceDateBlock(e: any): e is VoiceDateBlock {
    if (!e || typeof e !== 'object') return false;
    if (typeof e.date !== 'string' || !ISO_DATE_RE.test(e.date)) return false;
    if (typeof e.shift !== 'string' || !PUBLIC_BLOCK_SHIFTS.has(e.shift)) return false;
    if (e.callback_hours !== undefined && typeof e.callback_hours !== 'string') return false;
    return true;
}

async function getVoiceDateBlocks(tenantId: number): Promise<VoiceDateBlock[]> {
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, VOICE_DATE_BLOCKS_KEY]
        );
        const raw = result.rows[0]?.text_value;
        if (typeof raw !== 'string' || !raw.trim()) return [];
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(isValidVoiceDateBlock);
    } catch (err) {
        console.error(`[channel-settings] failed to read ${VOICE_DATE_BLOCKS_KEY}:`, err);
        return [];
    }
}

function findVoiceDateBlock(date: string, shift: 'LUNCH' | 'DINNER', blocks: VoiceDateBlock[]): VoiceDateBlock | null {
    for (const b of blocks) {
        if (b.date !== date) continue;
        if (b.shift === 'ALL' || b.shift === shift) return b;
    }
    return null;
}

// What Sofia reads to the caller when the requested date is blocked. The
// date readback keeps weekday+day coherent (same reason as check-availability);
// callback_hours is operator-written free text ("dalle 9:00 alle 12:00").
function buildVoiceDateBlockMessage(date: string, shift: 'LUNCH' | 'DINNER', block: VoiceDateBlock): string {
    const shiftLabel = block.shift === 'ALL' ? '' : (shift === 'LUNCH' ? ' a pranzo' : ' a cena');
    const when = block.callback_hours?.trim() || 'negli orari di apertura del ristorante';
    return `Per ${formatItalianDateReadback(date)}${shiftLabel} le prenotazioni vengono gestite personalmente dal nostro staff, quindi non posso registrarla io. La invitiamo a richiamare ${when} per parlare con un operatore. Grazie!`;
}

function isValidScheduleEntry(e: any): e is ScheduledSuspension {
    if (!e || typeof e !== 'object') return false;
    if (typeof e.date !== 'string' || !ISO_DATE_RE.test(e.date)) return false;
    if (typeof e.start_time !== 'string' || !HHMM_RE.test(e.start_time)) return false;
    if (typeof e.end_time !== 'string' || !HHMM_RE.test(e.end_time)) return false;
    if (e.start_time >= e.end_time) return false;
    if (e.callback_time !== undefined && (typeof e.callback_time !== 'string' || !HHMM_RE.test(e.callback_time))) return false;
    return true;
}

async function getVoiceSuspensionSchedule(tenantId: number): Promise<ScheduledSuspension[]> {
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, VOICE_SUSPENSION_SCHEDULE_KEY]
        );
        const raw = result.rows[0]?.text_value;
        if (typeof raw !== 'string' || !raw.trim()) return [];
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(isValidScheduleEntry);
    } catch (err) {
        console.error(`[channel-settings] failed to read ${VOICE_SUSPENSION_SCHEDULE_KEY}:`, err);
        return [];
    }
}

// Rome-anchored "YYYY-MM-DD" and "HH:MM" for the current instant. Used to
// decide whether a scheduled entry covers now. String comparison works
// because ISO date + zero-padded time are lexicographically ordered.
function getRomeNowParts(now: Date = new Date()): { date: string; time: string } {
    const d = now.toLocaleDateString('en-CA', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit' });
    const t = now.toLocaleTimeString('en-GB', { timeZone: 'Europe/Rome', hour: '2-digit', minute: '2-digit', hour12: false });
    return { date: d, time: t };
}

function pickActiveScheduleEntry(entries: ScheduledSuspension[], now: Date = new Date()): ScheduledSuspension | null {
    const { date, time } = getRomeNowParts(now);
    for (const e of entries) {
        if (e.date === date && time >= e.start_time && time < e.end_time) return e;
    }
    return null;
}

// Single source of truth for "is Sofia in suspension mode right now, and if
// so which callback time should she announce?". Combines the manual toggle
// (uses the default callback) with the scheduled entries (each entry can
// carry its own callback_time; falls back to end_time when absent). Manual
// toggle wins if both hit.
async function computeVoiceSuspensionState(tenantId: number): Promise<{ suspended: boolean; callbackTime: string }> {
    if (await getFeatureFlag(tenantId, 'voice_bookings_suspended', false)) {
        const callbackTime = await getVoiceSuspensionCallbackTime(tenantId);
        return { suspended: true, callbackTime };
    }
    const schedule = await getVoiceSuspensionSchedule(tenantId);
    const active = pickActiveScheduleEntry(schedule);
    if (active) return { suspended: true, callbackTime: active.callback_time || active.end_time };
    return { suspended: false, callbackTime: '' };
}

app.get('/settings/channels', authenticate, async (req, res) => {
    try {
        const [voiceThreshold, suspensionCallback, suspensionSchedule, publicBlocksRaw, voiceDateBlocksRaw, roomCaps, voiceFirstMessage] = await Promise.all([
            getVoiceLargeGroupThreshold(req.tenantId!),
            getVoiceSuspensionCallbackTime(req.tenantId!),
            getVoiceSuspensionSchedule(req.tenantId!),
            getPublicBookingBlocks(req.tenantId!),
            getVoiceDateBlocks(req.tenantId!),
            getRoomOccupancyCaps(req.tenantId!),
            getVoiceFirstMessage(req.tenantId!),
        ]);
        // Filter past blocks at read time; UI never has to worry about them.
        const publicBlocks = pruneExpiredBlocks(publicBlocksRaw);
        const voiceDateBlocks = pruneExpiredBlocks(voiceDateBlocksRaw);
        res.json({
            voice_large_group_threshold: voiceThreshold,
            voice_bookings_suspension_callback_time: suspensionCallback,
            voice_bookings_suspension_schedule: suspensionSchedule,
            public_bookings_blocks: publicBlocks,
            voice_bookings_date_blocks: voiceDateBlocks,
            room_occupancy_caps: roomCaps,
            voice_first_message: voiceFirstMessage,
        });
    } catch (err) {
        console.error('Error fetching channel settings:', err);
        res.status(500).json({ error: 'Failed to fetch channel settings' });
    }
});

app.put('/settings/channels', authenticate, requirePermission('settings:full'), async (req, res) => {
    const body = req.body ?? {};
    const updates: Array<{ key: string; column: 'int_value' | 'text_value'; value: number | string }> = [];

    if (body.voice_large_group_threshold !== undefined) {
        const n = Number(body.voice_large_group_threshold);
        if (!Number.isInteger(n) || n < 1 || n > 50) {
            return res.status(400).json({
                error: 'invalid_value',
                message: 'voice_large_group_threshold must be an integer between 1 and 50',
            });
        }
        updates.push({ key: VOICE_LARGE_GROUP_KEY, column: 'int_value', value: n });
    }

    if (body.voice_bookings_suspension_callback_time !== undefined) {
        const raw = String(body.voice_bookings_suspension_callback_time).trim();
        if (!HHMM_RE.test(raw)) {
            return res.status(400).json({
                error: 'invalid_value',
                message: 'voice_bookings_suspension_callback_time must be HH:MM (00-23:00-59)',
            });
        }
        updates.push({ key: VOICE_SUSPENSION_CALLBACK_KEY, column: 'text_value', value: raw });
    }

    if (body.voice_first_message !== undefined) {
        // Testo libero; stringa vuota = ripristina il default hardcoded.
        const raw = String(body.voice_first_message).trim();
        if (raw.length > VOICE_FIRST_MESSAGE_MAX) {
            return res.status(400).json({
                error: 'invalid_value',
                message: `voice_first_message must be at most ${VOICE_FIRST_MESSAGE_MAX} characters`,
            });
        }
        updates.push({ key: VOICE_FIRST_MESSAGE_KEY, column: 'text_value', value: raw });
    }

    if (body.public_bookings_blocks !== undefined) {
        if (!Array.isArray(body.public_bookings_blocks)) {
            return res.status(400).json({
                error: 'invalid_value',
                message: 'public_bookings_blocks must be an array',
            });
        }
        const normalizedBlocks: PublicBookingBlock[] = [];
        const seen = new Set<string>();
        for (const entry of body.public_bookings_blocks) {
            if (!entry || typeof entry !== 'object') {
                return res.status(400).json({ error: 'invalid_value', message: 'Each block entry must be an object' });
            }
            const date = String(entry.date ?? '').trim();
            const shift = String(entry.shift ?? '').trim().toUpperCase();
            if (!ISO_DATE_RE.test(date)) {
                return res.status(400).json({ error: 'invalid_value', message: `Block date must be YYYY-MM-DD (got "${date}")` });
            }
            if (!PUBLIC_BLOCK_SHIFTS.has(shift)) {
                return res.status(400).json({ error: 'invalid_value', message: `Block shift must be LUNCH, DINNER or ALL (got "${shift}")` });
            }
            // Dedupe on (date, shift). A day-wide ALL block subsumes LUNCH/
            // DINNER entries on the same date — drop the redundant ones.
            const key = `${date}|${shift}`;
            if (seen.has(key)) continue;
            seen.add(key);
            normalizedBlocks.push({ date, shift: shift as PublicBookingBlock['shift'] });
        }
        // Second pass: if an ALL entry exists for a date, remove any LUNCH/
        // DINNER entries for the same date.
        const daysWithAll = new Set(normalizedBlocks.filter(b => b.shift === 'ALL').map(b => b.date));
        const deduped = normalizedBlocks.filter(b => !(daysWithAll.has(b.date) && b.shift !== 'ALL'));
        // Chronological order for stable UI display.
        deduped.sort((a, b) => (a.date === b.date ? a.shift.localeCompare(b.shift) : a.date.localeCompare(b.date)));
        updates.push({ key: PUBLIC_BOOKINGS_BLOCKS_KEY, column: 'text_value', value: JSON.stringify(deduped) });
    }

    if (body.voice_bookings_date_blocks !== undefined) {
        if (!Array.isArray(body.voice_bookings_date_blocks)) {
            return res.status(400).json({
                error: 'invalid_value',
                message: 'voice_bookings_date_blocks must be an array',
            });
        }
        const normalizedVoiceBlocks: VoiceDateBlock[] = [];
        const seenVoice = new Set<string>();
        for (const entry of body.voice_bookings_date_blocks) {
            if (!entry || typeof entry !== 'object') {
                return res.status(400).json({ error: 'invalid_value', message: 'Each voice block entry must be an object' });
            }
            const date = String(entry.date ?? '').trim();
            const shift = String(entry.shift ?? '').trim().toUpperCase();
            const callbackHours = entry.callback_hours === undefined || entry.callback_hours === null
                ? ''
                : String(entry.callback_hours).trim();
            if (!ISO_DATE_RE.test(date)) {
                return res.status(400).json({ error: 'invalid_value', message: `Voice block date must be YYYY-MM-DD (got "${date}")` });
            }
            if (!PUBLIC_BLOCK_SHIFTS.has(shift)) {
                return res.status(400).json({ error: 'invalid_value', message: `Voice block shift must be LUNCH, DINNER or ALL (got "${shift}")` });
            }
            if (callbackHours.length > 120) {
                return res.status(400).json({ error: 'invalid_value', message: 'Voice block callback_hours must be at most 120 characters' });
            }
            // Same dedupe rules as the web blocks: (date, shift) unique, and a
            // day-wide ALL entry subsumes the per-shift ones on that date.
            const key = `${date}|${shift}`;
            if (seenVoice.has(key)) continue;
            seenVoice.add(key);
            const normalizedEntry: VoiceDateBlock = { date, shift: shift as VoiceDateBlock['shift'] };
            if (callbackHours) normalizedEntry.callback_hours = callbackHours;
            normalizedVoiceBlocks.push(normalizedEntry);
        }
        const voiceDaysWithAll = new Set(normalizedVoiceBlocks.filter(b => b.shift === 'ALL').map(b => b.date));
        const voiceDeduped = normalizedVoiceBlocks.filter(b => !(voiceDaysWithAll.has(b.date) && b.shift !== 'ALL'));
        voiceDeduped.sort((a, b) => (a.date === b.date ? a.shift.localeCompare(b.shift) : a.date.localeCompare(b.date)));
        updates.push({ key: VOICE_DATE_BLOCKS_KEY, column: 'text_value', value: JSON.stringify(voiceDeduped) });
    }

    if (body.room_occupancy_caps !== undefined) {
        if (!Array.isArray(body.room_occupancy_caps)) {
            return res.status(400).json({
                error: 'invalid_value',
                message: 'room_occupancy_caps must be an array',
            });
        }
        const normalizedCaps: RoomOccupancyCap[] = [];
        const seenRooms = new Set<number>();
        for (const entry of body.room_occupancy_caps) {
            if (!entry || typeof entry !== 'object') {
                return res.status(400).json({ error: 'invalid_value', message: 'Each room cap entry must be an object' });
            }
            const roomId = Number(entry.room_id);
            const percent = Number(entry.percent);
            const basis = String(entry.basis ?? 'TABLES').trim().toUpperCase();
            if (!Number.isInteger(roomId) || roomId <= 0) {
                return res.status(400).json({ error: 'invalid_value', message: `Cap room_id must be a positive integer (got "${entry.room_id}")` });
            }
            if (!Number.isInteger(percent) || percent < 1 || percent > 100) {
                return res.status(400).json({ error: 'invalid_value', message: `Cap percent must be an integer between 1 and 100 (got "${entry.percent}")` });
            }
            if (basis !== 'TABLES' && basis !== 'SEATS') {
                return res.status(400).json({ error: 'invalid_value', message: `Cap basis must be TABLES or SEATS (got "${entry.basis}")` });
            }
            // Last write wins on duplicates so the UI never has to dedupe.
            if (seenRooms.has(roomId)) {
                const idx = normalizedCaps.findIndex(c => c.room_id === roomId);
                normalizedCaps[idx] = { room_id: roomId, percent, basis };
                continue;
            }
            seenRooms.add(roomId);
            normalizedCaps.push({ room_id: roomId, percent, basis });
        }
        // Reject caps pointing at rooms that no longer exist: a stale entry
        // would silently never apply and the operator would think it does.
        if (normalizedCaps.length > 0) {
            try {
                const known = await queryWithRetry('SELECT id FROM rooms WHERE id = ANY($1::int[]) AND tenant_id = $2', [normalizedCaps.map(c => c.room_id), req.tenantId!]);
                const knownIds = new Set<number>(known.rows.map((r: any) => Number(r.id)));
                const unknown = normalizedCaps.filter(c => !knownIds.has(c.room_id)).map(c => c.room_id);
                if (unknown.length > 0) {
                    return res.status(400).json({ error: 'invalid_value', message: `Sale inesistenti: ${unknown.join(', ')}` });
                }
            } catch (err) {
                console.error('Error validating room occupancy caps:', err);
                return res.status(500).json({ error: 'Failed to validate room occupancy caps' });
            }
        }
        normalizedCaps.sort((a, b) => a.room_id - b.room_id);
        updates.push({ key: ROOM_OCCUPANCY_CAPS_KEY, column: 'text_value', value: JSON.stringify(normalizedCaps) });
    }

    if (body.voice_bookings_suspension_schedule !== undefined) {
        if (!Array.isArray(body.voice_bookings_suspension_schedule)) {
            return res.status(400).json({
                error: 'invalid_value',
                message: 'voice_bookings_suspension_schedule must be an array',
            });
        }
        const normalized: ScheduledSuspension[] = [];
        for (const entry of body.voice_bookings_suspension_schedule) {
            if (!entry || typeof entry !== 'object') {
                return res.status(400).json({ error: 'invalid_value', message: 'Each schedule entry must be an object' });
            }
            const date = String(entry.date ?? '').trim();
            const start = String(entry.start_time ?? '').trim();
            const end = String(entry.end_time ?? '').trim();
            const callbackRaw = entry.callback_time === undefined || entry.callback_time === null
                ? ''
                : String(entry.callback_time).trim();
            if (!ISO_DATE_RE.test(date)) {
                return res.status(400).json({ error: 'invalid_value', message: `Schedule entry date must be YYYY-MM-DD (got "${date}")` });
            }
            if (!HHMM_RE.test(start) || !HHMM_RE.test(end)) {
                return res.status(400).json({ error: 'invalid_value', message: 'Schedule entry start_time and end_time must be HH:MM' });
            }
            if (start >= end) {
                return res.status(400).json({ error: 'invalid_value', message: `Schedule entry start_time must be before end_time (${date} ${start}-${end})` });
            }
            if (callbackRaw && !HHMM_RE.test(callbackRaw)) {
                return res.status(400).json({ error: 'invalid_value', message: `Schedule entry callback_time must be HH:MM (got "${callbackRaw}")` });
            }
            const normalizedEntry: ScheduledSuspension = { date, start_time: start, end_time: end };
            if (callbackRaw) normalizedEntry.callback_time = callbackRaw;
            normalized.push(normalizedEntry);
        }
        // Sort chronologically so downstream reads/UI get a stable order.
        normalized.sort((a, b) => (a.date === b.date ? a.start_time.localeCompare(b.start_time) : a.date.localeCompare(b.date)));
        updates.push({ key: VOICE_SUSPENSION_SCHEDULE_KEY, column: 'text_value', value: JSON.stringify(normalized) });
    }

    if (updates.length === 0) {
        return res.status(400).json({ error: 'no_updates', message: 'No channel settings supplied' });
    }

    try {
        for (const u of updates) {
            const sql = `INSERT INTO app_settings (tenant_id, key, ${u.column}, updated_at)
                         VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                         ON CONFLICT (tenant_id, key) DO UPDATE
                           SET ${u.column} = EXCLUDED.${u.column}, updated_at = CURRENT_TIMESTAMP`;
            await queryWithRetry(sql, [req.tenantId!, u.key, u.value]);
        }
        const [voiceThreshold, suspensionCallback, suspensionSchedule, publicBlocksRaw, voiceDateBlocksRaw, roomCaps, voiceFirstMessage] = await Promise.all([
            getVoiceLargeGroupThreshold(req.tenantId!),
            getVoiceSuspensionCallbackTime(req.tenantId!),
            getVoiceSuspensionSchedule(req.tenantId!),
            getPublicBookingBlocks(req.tenantId!),
            getVoiceDateBlocks(req.tenantId!),
            getRoomOccupancyCaps(req.tenantId!),
            getVoiceFirstMessage(req.tenantId!),
        ]);
        const publicBlocks = pruneExpiredBlocks(publicBlocksRaw);
        const voiceDateBlocks = pruneExpiredBlocks(voiceDateBlocksRaw);
        res.json({
            voice_large_group_threshold: voiceThreshold,
            voice_bookings_suspension_callback_time: suspensionCallback,
            voice_bookings_suspension_schedule: suspensionSchedule,
            public_bookings_blocks: publicBlocks,
            voice_bookings_date_blocks: voiceDateBlocks,
            room_occupancy_caps: roomCaps,
            voice_first_message: voiceFirstMessage,
        });
    } catch (err) {
        console.error('Error updating channel settings:', err);
        res.status(500).json({ error: 'Failed to update channel settings' });
    }
});

// Live occupancy per room, used by Settings → Canali di prenotazione to show
// the operator how full each sala is right now against its configured cap.
// Read-only: no side effects, safe for any authenticated user to poll.
app.get('/settings/rooms-occupancy', authenticate, async (req, res) => {
    const dateParam = typeof req.query.date === 'string' ? req.query.date : '';
    const date = ISO_DATE_RE.test(dateParam)
        ? dateParam
        : new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit' });
    try {
        const [lunch, dinner] = await Promise.all([
            computeRoomOccupancy(req.tenantId!, date, Shift.LUNCH),
            computeRoomOccupancy(req.tenantId!, date, Shift.DINNER),
        ]);
        // One row per room carrying both shifts: the settings card renders a
        // single line per sala, so joining here keeps the UI dumb.
        const dinnerById = new Map(dinner.map(r => [r.room_id, r]));
        const rooms = lunch.map(r => ({
            room_id: r.room_id,
            room_name: r.room_name,
            is_closed: r.is_closed,
            capacity_tables: r.capacity_tables,
            capacity_seats: r.capacity_seats,
            lunch: {
                used_tables: r.used_tables,
                used_seats: r.used_seats,
                percent_tables: r.percent_tables,
                percent_seats: r.percent_seats,
                at_cap: r.at_cap,
                closed_for_shift: r.closed_for_shift,
            },
            dinner: (() => {
                const d = dinnerById.get(r.room_id);
                return {
                    used_tables: d?.used_tables ?? 0,
                    used_seats: d?.used_seats ?? 0,
                    percent_tables: d?.percent_tables ?? 0,
                    percent_seats: d?.percent_seats ?? 0,
                    at_cap: d?.at_cap ?? false,
                    closed_for_shift: d?.closed_for_shift ?? false,
                };
            })(),
        }));
        res.json({ date, rooms });
    } catch (err) {
        console.error('Error fetching room occupancy:', err);
        res.status(500).json({ error: 'Failed to fetch room occupancy' });
    }
});

// ---------------------------------------------------------------------------
// LEGAL SETTINGS (app_settings → key 'legal_config', stored as a JSON blob)
// Per-tenant identity + configuration used to generate the app's legal
// documents (privacy policy, voice notice, cookie policy + banner, terms).
// Multi-tenant/SaaS ready: everything is data, no hard-coded restaurant info.
// ---------------------------------------------------------------------------
const LEGAL_CONFIG_KEY = 'legal_config';
// Operating mode for the legal layer:
//   'simple'   → only the strict legal minimum (no marketing / non-essential).
//   'advanced' → full: marketing consents, audience, analytics cookies, terms.
const LEGAL_MODES = ['simple', 'advanced'] as const;
type LegalMode = typeof LEGAL_MODES[number];
const LEGAL_MODE_DEFAULT: LegalMode = 'advanced';
// Whitelisted string fields. Unknown keys are ignored on write.
const LEGAL_STRING_FIELDS = [
    'legal_mode',          // 'simple' | 'advanced'
    'company_name',        // Ragione sociale
    'company_address',     // Sede legale
    'vat_number',          // Partita IVA
    'fiscal_code',         // Codice fiscale (facoltativo)
    'privacy_email',       // E-mail per richieste privacy
    'privacy_phone',       // Telefono
    'dpo_name',            // Nome DPO (facoltativo)
    'dpo_contact',         // Contatto DPO (facoltativo)
    'website_url',         // Sito / canale di prenotazione online
    'app_name',            // Nome applicazione mostrato (default RistoManager)
    'voice_business_name', // Nome pronunciato nell'avviso vocale
    'business_name',       // Nome pubblico del ristorante (firme, email, pagina prenota)
    'business_tagline',    // Sottotitolo nel footer delle email e della pagina prenota
    'public_phone',        // Telefono mostrato ai clienti (messaggi ed email)
    'public_whatsapp',     // Numero WhatsApp mostrato ai clienti
    'public_address',      // Indirizzo del locale mostrato ai clienti (pagina prenota).
                           // NON è company_address: la sede legale può essere
                           // lo studio del commercialista in un'altra città.
    'maps_url',            // Link "Come raggiungerci" (Google Maps)
    'logo_url',            // Logo del ristorante (pagina prenota). Scritto
                           // dalle route /settings/logo: /public/media/<token>
                           // dopo un upload, o un asset statico (es. il
                           // /prenota/logo.png storico del Frantoio).
    'logo_dark_url',       // Variante per tema scuro (artwork chiaro), come
                           // le email con logo.png/logo-dark.png. Facoltativa:
                           // senza, il CRM ripiega sulla piastra chiara.
    'data_processors',     // Elenco responsabili/fornitori (testo multiriga)
    'retention_customer',  // Conservazione dati cliente (es. "24 mesi")
    'retention_calls',     // Conservazione registrazioni chiamate (es. "6 mesi")
    'retention_marketing', // Conservazione dati marketing (es. "fino a revoca")
    'extra_eu_note',       // Nota trasferimenti extra-UE
    'governing_law',       // Legge applicabile / foro competente
    'last_updated',        // Data ultimo aggiornamento (ISO, gestita lato client)
] as const;
// Whitelisted boolean fields.
const LEGAL_BOOL_FIELDS = [
    'uses_analytics_cookies', // Il sito usa cookie analitici/di terze parti
    'records_calls',          // Le chiamate sono registrate
    'ask_health_consent',     // Chiedi il consenso allergie/dati sanitari in prenotazione
] as const;

function emptyLegalConfig(): Record<string, string | boolean> {
    const out: Record<string, string | boolean> = {};
    for (const k of LEGAL_STRING_FIELDS) out[k] = '';
    for (const k of LEGAL_BOOL_FIELDS) out[k] = false;
    out.legal_mode = LEGAL_MODE_DEFAULT;
    // Default ON: preserves the previous always-on allergy-consent behaviour
    // for tenants without a stored value.
    out.ask_health_consent = true;
    return out;
}

function normalizeLegalMode(v: unknown): LegalMode {
    return (typeof v === 'string' && (LEGAL_MODES as readonly string[]).includes(v)) ? (v as LegalMode) : LEGAL_MODE_DEFAULT;
}

async function getLegalConfig(tenantId: number): Promise<Record<string, string | boolean>> {
    const base = emptyLegalConfig();
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, LEGAL_CONFIG_KEY]
        );
        const raw = result.rows[0]?.text_value;
        if (typeof raw === 'string' && raw.trim()) {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object') {
                for (const k of LEGAL_STRING_FIELDS) {
                    if (typeof parsed[k] === 'string') base[k] = parsed[k];
                }
                for (const k of LEGAL_BOOL_FIELDS) {
                    if (typeof parsed[k] === 'boolean') base[k] = parsed[k];
                }
            }
        }
    } catch (err) {
        console.error('[legal-settings] failed to read legal_config:', err);
    }
    base.legal_mode = normalizeLegalMode(base.legal_mode);
    return base;
}

app.get('/settings/legal', authenticate, async (req, res) => {
    try {
        res.json(await getLegalConfig(req.tenantId!));
    } catch (err) {
        console.error('GET /settings/legal error:', err);
        res.status(500).json({ error: 'Failed to fetch legal settings' });
    }
});

app.put('/settings/legal', authenticate, requirePermission('settings:full'), async (req, res) => {
    // Whole handler wrapped so a throw in getLegalConfig()/DB never escapes to
    // Express's default (HTML, non-JSON) error page — which surfaces on the
    // client as an opaque "Request failed". The real cause is echoed in `detail`.
    try {
        const body = req.body ?? {};
        if (typeof body !== 'object' || Array.isArray(body)) {
            return res.status(400).json({ error: 'invalid_value', message: 'Body must be an object' });
        }
        const current = await getLegalConfig(req.tenantId!);
        const next: Record<string, string | boolean> = { ...current };
        for (const k of LEGAL_STRING_FIELDS) {
            if (k in body) {
                if (typeof body[k] !== 'string') {
                    return res.status(400).json({ error: 'invalid_value', message: `${k} must be a string` });
                }
                // Cap length defensively; legal blurbs can be long but not unbounded.
                next[k] = String(body[k]).slice(0, 5000);
            }
        }
        for (const k of LEGAL_BOOL_FIELDS) {
            if (k in body) {
                if (typeof body[k] !== 'boolean') {
                    return res.status(400).json({ error: 'invalid_value', message: `${k} must be a boolean` });
                }
                next[k] = body[k];
            }
        }
        // legal_mode must be one of the known modes; anything else falls back safely.
        next.legal_mode = normalizeLegalMode(next.legal_mode);
        await queryWithRetry(
            `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
             VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
             ON CONFLICT (tenant_id, key) DO UPDATE
               SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
            [req.tenantId!, LEGAL_CONFIG_KEY, JSON.stringify(next)]
        );
        // I messaggi leggono l'identità dalla cache: senza refresh il nuovo
        // nome comparirebbe solo alla scadenza del TTL.
        await refreshBusinessIdentity(req.tenantId!);
        res.json(next);
    } catch (err: any) {
        console.error('PUT /settings/legal error:', err);
        res.status(500).json({ error: 'Failed to update legal settings', detail: err?.message });
    }
});

// Logo del ristorante (pagina prenota). I byte stanno in outbound_media
// (token pubblico non indovinabile, stesso storage degli allegati) e in
// legal_config resta solo il path: l'upload sostituisce, la DELETE toglie.
// Niente SVG: servito same-origin col content-type salvato, un SVG con
// script dentro sarebbe XSS sull'origine del backend.
const LOGO_MEDIA_RE = /^\/public\/media\/([A-Za-z0-9_-]{20,64})$/;
// Due varianti, come le email: 'light' è il logo normale, 'dark' l'artwork
// chiaro per il tema scuro.
const LOGO_VARIANT_FIELDS = { light: 'logo_url', dark: 'logo_dark_url' } as const;
type LogoVariant = keyof typeof LOGO_VARIANT_FIELDS;
const logoVariantFrom = (raw: unknown): LogoVariant => (raw === 'dark' ? 'dark' : 'light');

const setLegalLogoUrl = async (tenantId: number, variant: LogoVariant, logoUrl: string): Promise<void> => {
    const current = await getLegalConfig(tenantId);
    const next = { ...current, [LOGO_VARIANT_FIELDS[variant]]: logoUrl };
    await queryWithRetry(
        `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
         VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
         ON CONFLICT (tenant_id, key) DO UPDATE
           SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
        [tenantId, LEGAL_CONFIG_KEY, JSON.stringify(next)]
    );
    await refreshBusinessIdentity(tenantId);
};
const deleteLogoMedia = async (tenantId: number, logoUrl: string): Promise<void> => {
    const m = typeof logoUrl === 'string' ? logoUrl.match(LOGO_MEDIA_RE) : null;
    if (!m) return; // asset statico (es. /prenota/logo.png): non si tocca
    await queryWithRetry(`DELETE FROM outbound_media WHERE tenant_id = $1 AND token = $2`, [tenantId, m[1]])
        .catch(err => console.warn('[logo] cleanup media fallito:', (err as any)?.message || err));
};

app.post('/settings/logo', authenticate, requirePermission('settings:full'), async (req: any, res) => {
    try {
        const contentType = String(req.body?.content_type || '').toLowerCase().split(';')[0].trim();
        const dataB64 = String(req.body?.data || '');
        if (!contentType || !dataB64) {
            return res.status(400).json({ error: 'content_type e data sono obbligatori' });
        }
        if (!/^image\/(png|jpeg|webp)$/.test(contentType)) {
            return res.status(415).json({ error: `Formato non supportato: ${contentType}. Usa PNG, JPG o WebP.` });
        }
        const buf = Buffer.from(dataB64.replace(/^data:[^,]+,/, ''), 'base64');
        if (buf.length === 0) return res.status(400).json({ error: 'File vuoto' });
        if (buf.length > 2 * 1024 * 1024) {
            return res.status(413).json({ error: 'File troppo grande: massimo 2 MB' });
        }
        const variant = logoVariantFrom(req.body?.variant);
        const previous = String((await getLegalConfig(req.tenantId!))[LOGO_VARIANT_FIELDS[variant]] || '');
        const token = crypto.randomBytes(32).toString('base64url');
        await queryWithRetry(
            `INSERT INTO outbound_media (tenant_id, token, content_type, filename, bytes, size_bytes, created_by_user_id)
             VALUES ($1, $2, $3, $4, $5, $6, $7)`,
            [req.tenantId!, token, contentType, variant === 'dark' ? 'logo-dark' : 'logo', buf, buf.length, req.user?.userId ?? null]
        );
        const logoUrl = `/public/media/${token}`;
        await setLegalLogoUrl(req.tenantId!, variant, logoUrl);
        await deleteLogoMedia(req.tenantId!, previous);
        res.status(201).json({ logo_url: logoUrl, variant });
    } catch (err: any) {
        console.error('POST /settings/logo error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

app.delete('/settings/logo', authenticate, requirePermission('settings:full'), async (req: any, res) => {
    try {
        const variant = logoVariantFrom(req.query?.variant);
        const previous = String((await getLegalConfig(req.tenantId!))[LOGO_VARIANT_FIELDS[variant]] || '');
        await setLegalLogoUrl(req.tenantId!, variant, '');
        await deleteLogoMedia(req.tenantId!, previous);
        res.json({ ok: true });
    } catch (err: any) {
        console.error('DELETE /settings/logo error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// ---------------------------------------------------------------------------
// TABLE ASSIGNMENT AI PROMPT (app_settings → key 'table_assignment_ai_prompt')
// Testo libero scritto dal ristoratore: descrive le dinamiche MANUALI di
// sala di oggi (quando unire/dividere tavoli, come gestire gruppi grandi,
// come ottimizzare l'occupancy nelle serate piene). Non sostituisce la
// logica di assegnazione esistente, la affianca — vedi
// maybeSuggestTableAssignment più in basso (card dev board #26). Prompt
// vuoto = proposta AI spenta.
// ---------------------------------------------------------------------------
const TABLE_ASSIGNMENT_AI_PROMPT_KEY = 'table_assignment_ai_prompt';
const TABLE_ASSIGNMENT_AI_PROMPT_MAX = 4000;

async function getTableAssignmentAiPrompt(tenantId: number): Promise<string> {
    try {
        const result = await queryWithRetry(
            'SELECT text_value FROM app_settings WHERE tenant_id = $1 AND key = $2',
            [tenantId, TABLE_ASSIGNMENT_AI_PROMPT_KEY]
        );
        const raw = result.rows[0]?.text_value;
        return typeof raw === 'string' ? raw : '';
    } catch (err) {
        console.error(`[table-assignment-ai-prompt] failed to read ${TABLE_ASSIGNMENT_AI_PROMPT_KEY}:`, err);
        return '';
    }
}

app.get('/settings/table-assignment-ai-prompt', authenticate, async (req, res) => {
    try {
        res.json({ prompt: await getTableAssignmentAiPrompt(req.tenantId!) });
    } catch (err) {
        console.error('GET /settings/table-assignment-ai-prompt error:', err);
        res.status(500).json({ error: 'Failed to fetch table assignment AI prompt' });
    }
});

app.put('/settings/table-assignment-ai-prompt', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const body = req.body ?? {};
        if (typeof body.prompt !== 'string') {
            return res.status(400).json({ error: 'invalid_value', message: 'prompt must be a string' });
        }
        const raw = body.prompt.slice(0, TABLE_ASSIGNMENT_AI_PROMPT_MAX);
        await queryWithRetry(
            `INSERT INTO app_settings (tenant_id, key, text_value, updated_at)
             VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
             ON CONFLICT (tenant_id, key) DO UPDATE
               SET text_value = EXCLUDED.text_value, updated_at = CURRENT_TIMESTAMP`,
            [req.tenantId!, TABLE_ASSIGNMENT_AI_PROMPT_KEY, raw]
        );
        res.json({ prompt: raw });
    } catch (err: any) {
        console.error('PUT /settings/table-assignment-ai-prompt error:', err);
        res.status(500).json({ error: 'Failed to update table assignment AI prompt', detail: err?.message });
    }
});

// ---------------------------------------------------------------------------
// TABLE ASSIGNMENT AI — la proposta (card dev board #26)
// Quando una prenotazione nasce senza tavolo da un canale self-service (sito,
// WhatsApp, Sofia — vedi le chiamate a suggestTableAssignment/
// maybeSuggestTableAssignment), si legge il prompt sopra + lo stato reale del
// servizio (tavoli aperti, unioni attive, altre prenotazioni con tavolo) e si
// chiede a Claude un'assegnazione. La proposta finisce in
// table_assignment_suggestions e viaggia via socket: la sala la vede in lista
// prenotazioni e la conferma in un tap, o la ignora. Mai scrittura silenziosa
// sulla prenotazione — quella la fa solo la conferma umana qui sotto.
// ---------------------------------------------------------------------------

function tableAssignmentSuggestionRow(r: any) {
    return {
        id: r.id,
        reservation_id: r.reservation_id,
        table_id: r.table_id,
        table_name: r.table_name ?? null,
        merge_with_table_ids: r.merge_with_table_ids || [],
        summary: r.summary,
        status: r.status,
        created_at: r.created_at,
    };
}

async function maybeSuggestTableAssignment(tenantId: number, reservationId: number): Promise<void> {
    try {
        const prompt = await getTableAssignmentAiPrompt(tenantId);
        if (!prompt.trim()) return; // prompt vuoto = feature spenta
        if (!tableAssignmentAgent.isAgentConfigured()) return;

        const resvRes = await queryWithRetry(
            `SELECT id, customer_name, reservation_time, shift, guests, children, notes, table_id, reservation_status
               FROM reservations WHERE id = $1 AND tenant_id = $2`,
            [reservationId, tenantId]
        );
        const reservation = resvRes.rows[0];
        // Nel frattempo qualcuno potrebbe aver già assegnato un tavolo a mano,
        // o annullato la prenotazione: la proposta non servirebbe più.
        if (!reservation || reservation.table_id != null) return;
        if (['CANCELLED', 'DECLINED'].includes(reservation.reservation_status)) return;

        const eventDate = new Date(reservation.reservation_time).toISOString().substring(0, 10);
        const timeLabel = getRomeTimePart(reservation.reservation_time);

        const [tablesRes, mergesRes, occupancyRes] = await Promise.all([
            queryWithRetry(
                `SELECT t.id, t.name, t.seats, t.room_id, r.name AS room_name
                   FROM tables t
                   JOIN rooms r ON r.id = t.room_id AND r.tenant_id = t.tenant_id
                  WHERE t.tenant_id = $1 AND r.is_closed = false
                  ORDER BY r.name, t.name`,
                [tenantId]
            ),
            queryWithRetry(
                `SELECT primary_id, merged_ids FROM table_merges WHERE tenant_id = $1 AND date = $2 AND shift = $3`,
                [tenantId, eventDate, reservation.shift]
            ),
            queryWithRetry(
                `SELECT table_id, customer_name, guests, reservation_time
                   FROM reservations
                  WHERE tenant_id = $1 AND DATE(reservation_time) = $2::date AND shift = $3
                    AND table_id IS NOT NULL AND id <> $4
                    AND COALESCE(reservation_status, 'CONFIRMED') NOT IN ('CANCELLED', 'DECLINED')`,
                [tenantId, eventDate, reservation.shift, reservationId]
            ),
        ]);

        const tables = tablesRes.rows;
        if (tables.length === 0) return;

        const result = await tableAssignmentAgent.suggestTableAssignment({
            prompt,
            reservation: {
                customer_name: reservation.customer_name,
                guests: reservation.guests,
                children: reservation.children || 0,
                time: timeLabel,
                shift: reservation.shift,
                notes: reservation.notes,
            },
            tables,
            merges: mergesRes.rows,
            occupancy: occupancyRes.rows.map((o: any) => ({
                table_id: o.table_id,
                customer_name: o.customer_name,
                guests: o.guests,
                time: getRomeTimePart(o.reservation_time),
            })),
        });

        // Telemetria per la pagina Consumi AI, come dashboard_report/
        // suggest_reply/whatsapp_agent. Best-effort.
        if (result.usage) {
            const u = result.usage;
            queryWithRetry(
                `INSERT INTO ai_token_usage (provider, feature, model, prompt_tokens, output_tokens, total_tokens, tenant_id)
                 VALUES ('anthropic', 'table_assignment', $1, $2, $3, $4, $5)`,
                [u.model, u.promptTokens, u.outputTokens, u.totalTokens, tenantId]
            ).catch(err => console.error('ai_token_usage insert (table_assignment) failed:', err));
        }

        if (!result.proposal) {
            if (result.reason) console.log(`[table-assignment-ai] nessuna proposta per prenotazione #${reservationId}: ${result.reason}`);
            return;
        }

        // Il tavolo (e l'eventuale unione) proposti devono esistere davvero e
        // reggere la capienza, senza conflitti con altre prenotazioni: il
        // modello ragiona sui dati che gli passiamo ma non ci si fida
        // ciecamente prima di scrivere una proposta che lo staff vedrà.
        const idsInvolved = [result.proposal.tableId, ...result.proposal.mergeWithTableIds];
        const involvedTables = tables.filter((t: any) => idsInvolved.includes(t.id));
        if (involvedTables.length !== idsInvolved.length) {
            console.warn(`[table-assignment-ai] proposta scartata (tavolo inesistente) per prenotazione #${reservationId}`, result.proposal);
            return;
        }
        const totalSeats = involvedTables.reduce((sum: number, t: any) => sum + (t.seats || 0), 0);
        if (totalSeats < reservation.guests) {
            console.warn(`[table-assignment-ai] proposta scartata (capienza insufficiente) per prenotazione #${reservationId}`, result.proposal);
            return;
        }
        const conflicts = await findTableConflicts(tenantId, eventDate, reservation.shift, idsInvolved);
        if (conflicts.length > 0) {
            console.warn(`[table-assignment-ai] proposta scartata (conflitto) per prenotazione #${reservationId}`, result.proposal);
            return;
        }

        // Una proposta pendente per prenotazione: quella vecchia decade,
        // altrimenti lo staff si trova due suggerimenti in contrasto.
        await queryWithRetry(
            `UPDATE table_assignment_suggestions SET status = 'SUPERSEDED', resolved_at = CURRENT_TIMESTAMP
              WHERE tenant_id = $1 AND reservation_id = $2 AND status = 'PENDING'`,
            [tenantId, reservationId]
        );
        const ins = await queryWithRetry(
            `INSERT INTO table_assignment_suggestions (tenant_id, reservation_id, table_id, merge_with_table_ids, summary)
             VALUES ($1, $2, $3, $4, $5) RETURNING *`,
            [tenantId, reservationId, result.proposal.tableId, result.proposal.mergeWithTableIds, result.proposal.summary]
        );
        const tableName = involvedTables.find((t: any) => t.id === result.proposal!.tableId)?.name ?? null;
        const suggestion = tableAssignmentSuggestionRow({ ...ins.rows[0], table_name: tableName });
        if (socketService) socketService.broadcastToAll(tenantId, 'tableAssignmentSuggestion:created', suggestion);
    } catch (err: any) {
        console.error('[table-assignment-ai] suggestion failed:', err?.message || err);
    }
}

// GET /table-assignment-suggestions[?date=YYYY-MM-DD&shift=LUNCH|DINNER]
// Solo le proposte pendenti: la lista prenotazioni non ha motivo di sapere
// di quelle già risolte. Senza date/shift torna tutte le pendenti del
// tenant — sono poche per natura (una per prenotazione senza tavolo), la
// lista le tiene aggiornate via socket una volta caricate.
app.get('/table-assignment-suggestions', authenticate, async (req, res) => {
    try {
        const { date, shift } = req.query;
        if ((date && !shift) || (shift && !date)) {
            return res.status(400).json({ error: 'date and shift must be provided together' });
        }
        if (shift && shift !== 'LUNCH' && shift !== 'DINNER') {
            return res.status(400).json({ error: 'shift must be LUNCH or DINNER' });
        }
        const params: any[] = [req.tenantId!];
        let scopeFilter = '';
        if (date && shift) {
            params.push(date, shift);
            scopeFilter = `AND DATE(r.reservation_time) = $2::date AND r.shift = $3`;
        }
        const result = await queryWithRetry(
            `SELECT tas.*, t.name AS table_name
               FROM table_assignment_suggestions tas
               JOIN reservations r ON r.id = tas.reservation_id AND r.tenant_id = tas.tenant_id
               JOIN tables t ON t.id = tas.table_id AND t.tenant_id = tas.tenant_id
              WHERE tas.tenant_id = $1 AND tas.status = 'PENDING'
                ${scopeFilter}
              ORDER BY tas.created_at DESC`,
            params
        );
        res.json(result.rows.map(tableAssignmentSuggestionRow));
    } catch (err) {
        console.error('GET /table-assignment-suggestions error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Conferma la proposta: SOLO qui si scrive davvero sulla prenotazione (ed
// eventualmente su table_merges). Fino a questo tap è solo un suggerimento.
app.post('/table-assignment-suggestions/:id/confirm', authenticate, requirePermission('reservations:full'), async (req, res) => {
    const client = await pool.connect();
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) { client.release(); return res.status(400).json({ error: 'id non valido' }); }

        await client.query('BEGIN');
        const sugRes = await client.query(
            `SELECT * FROM table_assignment_suggestions WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
            [id, req.tenantId!]
        );
        const suggestion = sugRes.rows[0];
        if (!suggestion) { await client.query('ROLLBACK'); return res.status(404).json({ error: 'Proposta non trovata' }); }
        if (suggestion.status !== 'PENDING') {
            await client.query('ROLLBACK');
            return res.status(409).json({ error: 'already_resolved', status: suggestion.status });
        }

        const resvRes = await client.query(
            `SELECT * FROM reservations WHERE id = $1 AND tenant_id = $2 FOR UPDATE`,
            [suggestion.reservation_id, req.tenantId!]
        );
        const reservation = resvRes.rows[0];
        if (!reservation) {
            await client.query(`UPDATE table_assignment_suggestions SET status = 'DISCARDED', resolved_at = CURRENT_TIMESTAMP, resolved_by_user_id = $2 WHERE id = $1`, [id, req.user?.userId ?? null]);
            await client.query('COMMIT');
            return res.status(404).json({ error: 'Prenotazione non trovata' });
        }
        if (reservation.table_id != null) {
            await client.query(`UPDATE table_assignment_suggestions SET status = 'DISCARDED', resolved_at = CURRENT_TIMESTAMP, resolved_by_user_id = $2 WHERE id = $1`, [id, req.user?.userId ?? null]);
            await client.query('COMMIT');
            return res.status(409).json({ error: 'already_assigned', message: 'La prenotazione ha già un tavolo assegnato.' });
        }

        // La sala potrebbe essere cambiata da quando la proposta è stata
        // generata (un altro tavolo occupato, la sala chiusa nel frattempo):
        // si riverifica prima di scrivere, non ci si fida della proposta.
        const idsInvolved = [suggestion.table_id, ...(suggestion.merge_with_table_ids || [])];
        if (await isTableInClosedRoom(req.tenantId!, suggestion.table_id)) {
            await client.query('ROLLBACK');
            return res.status(400).json({ error: 'La sala del tavolo suggerito è chiusa.' });
        }
        const eventDate = new Date(reservation.reservation_time).toISOString().substring(0, 10);
        const conflicts = await findTableConflicts(req.tenantId!, eventDate, reservation.shift, idsInvolved, {
            excludeReservationId: reservation.id,
        });
        if (conflicts.length > 0) {
            await client.query('ROLLBACK');
            return res.status(409).json({ error: buildConflictMessage(conflicts), conflicts });
        }

        const updRes = await client.query(
            `UPDATE reservations SET table_id = $1 WHERE id = $2 AND tenant_id = $3 RETURNING *`,
            [suggestion.table_id, reservation.id, req.tenantId!]
        );
        const updatedReservation = updRes.rows[0];

        let merge: any = null;
        if ((suggestion.merge_with_table_ids || []).length > 0) {
            const mergeRes = await client.query(
                `INSERT INTO table_merges (tenant_id, date, shift, primary_id, merged_ids)
                 VALUES ($1, $2, $3, $4, $5)
                 ON CONFLICT (date, shift, primary_id) DO UPDATE SET merged_ids = EXCLUDED.merged_ids
                 RETURNING id, date, shift, primary_id, merged_ids`,
                [req.tenantId!, eventDate, reservation.shift, suggestion.table_id, suggestion.merge_with_table_ids]
            );
            merge = mergeRes.rows[0];
        }

        await client.query(
            `UPDATE table_assignment_suggestions SET status = 'CONFIRMED', resolved_at = CURRENT_TIMESTAMP, resolved_by_user_id = $2 WHERE id = $1`,
            [id, req.user?.userId ?? null]
        );
        await client.query('COMMIT');

        if (req.user) {
            LogService.logActivity(
                req.tenantId!, req.user.userId, req.user.email, req.user.email,
                ActivityAction.UPDATE, ResourceType.RESERVATION, reservation.id, reservation.customer_name,
                { table_assignment_ai_suggestion_id: id, table_id: suggestion.table_id, merge_with_table_ids: suggestion.merge_with_table_ids }
            );
        }
        if (socketService) {
            socketService.broadcastReservationUpdated(req.tenantId!, updatedReservation);
            if (merge) socketService.broadcastTableMergeCreated(req.tenantId!, merge);
            // Gli altri terminali collegati devono togliere il chip: senza
            // questo evento resterebbe visibile finché non ricaricano.
            socketService.broadcastToAll(req.tenantId!, 'tableAssignmentSuggestion:resolved', tableAssignmentSuggestionRow({ ...suggestion, status: 'CONFIRMED' }));
        }

        res.json({ reservation: updatedReservation, merge });
    } catch (err: any) {
        try { await client.query('ROLLBACK'); } catch { /* noop */ }
        console.error('POST /table-assignment-suggestions/:id/confirm error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    } finally {
        client.release();
    }
});

app.post('/table-assignment-suggestions/:id/dismiss', authenticate, requirePermission('reservations:full'), async (req, res) => {
    try {
        const id = parseInt(req.params.id, 10);
        if (!Number.isFinite(id)) return res.status(400).json({ error: 'id non valido' });
        const r = await queryWithRetry(
            `UPDATE table_assignment_suggestions SET status = 'DISMISSED', resolved_at = CURRENT_TIMESTAMP, resolved_by_user_id = $2
              WHERE id = $1 AND tenant_id = $3 AND status = 'PENDING' RETURNING *`,
            [id, req.user?.userId ?? null, req.tenantId!]
        );
        if (r.rows.length === 0) return res.status(409).json({ error: 'Proposta non più in attesa' });
        if (socketService) {
            socketService.broadcastToAll(req.tenantId!, 'tableAssignmentSuggestion:resolved', tableAssignmentSuggestionRow(r.rows[0]));
        }
        res.json({ ok: true });
    } catch (err: any) {
        console.error('POST /table-assignment-suggestions/:id/dismiss error:', err);
        res.status(500).json({ error: 'Internal server error' });
    }
});

app.put('/settings/features', authenticate, requirePermission('settings:full'), async (req, res) => {
    const body = req.body ?? {};
    const updates: Array<{ key: FeatureFlagKey; value: boolean }> = [];
    for (const key of FEATURE_FLAG_KEYS) {
        if (key in body) {
            if (typeof body[key] !== 'boolean') {
                return res.status(400).json({ error: 'invalid_value', message: `${key} must be boolean` });
            }
            updates.push({ key, value: body[key] });
        }
    }
    if (updates.length === 0) {
        return res.status(400).json({ error: 'no_updates', message: 'No flag updates supplied' });
    }
    try {
        for (const { key, value } of updates) {
            await queryWithRetry(
                `INSERT INTO app_settings (tenant_id, key, value, updated_at)
                 VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                 ON CONFLICT (tenant_id, key) DO UPDATE
                   SET value = EXCLUDED.value, updated_at = CURRENT_TIMESTAMP`,
                [req.tenantId!, key, value]
            );
        }
        const result = await queryWithRetry(
            'SELECT key, value FROM app_settings WHERE tenant_id = $1 AND key = ANY($2)',
            [req.tenantId!, FEATURE_FLAG_KEYS]
        );
        const flags: Record<string, boolean> = { ...FEATURE_FLAG_DEFAULTS };
        for (const row of result.rows) {
            flags[row.key] = Boolean(row.value);
        }
        // Le voci di menu legate ai flag (Comande/Cucina/Passe) si aggiornano
        // in tempo reale su tutti i dispositivi connessi, incluso chi ha
        // premuto l'interruttore.
        try { socketService?.broadcastToAll(req.tenantId!, 'features:updated', flags); } catch (_) {}
        res.json(flags);
    } catch (err) {
        console.error('Error updating feature flags:', err);
        res.status(500).json({ error: 'Failed to update feature flags' });
    }
});

