// Token di instradamento del tenant (Fase C2): il webhook_token va incollato
// negli URL dei provider (ElevenLabs, Twilio, Vonage, Resend), il
// print_agent_token nella config dell'agente di stampa. Endpoint separato da
// /settings/entitlements, che risponde i soli tre boolean e ha chi ci fa
// asserzioni sopra. settings:full: i token equivalgono a credenziali.
app.get('/settings/webhook-info', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const r = await queryWithRetry(
            'SELECT webhook_token, print_agent_token, slug FROM tenants WHERE id = $1',
            [req.tenantId!]
        );
        const webhookToken: string | null = r.rows[0]?.webhook_token ?? null;
        const printAgentToken: string | null = r.rows[0]?.print_agent_token ?? null;
        const tenantSlug: string | null = r.rows[0]?.slug ?? null;
        // Domini custom del tenant (Fase C3): mostrati accanto all'URL di
        // prenotazione così chi configura il DNS vede cosa punta già qui.
        const domainsRes = await queryWithRetry(
            'SELECT domain, purpose FROM tenant_domains WHERE tenant_id = $1 ORDER BY domain',
            [req.tenantId!]
        );
        // Base pubblica dei webhook: in produzione i provider chiamano il
        // dominio del backend, quindi l'host della richiesta (dietro proxy,
        // trust-proxy è già attivo) è quello giusto anche in locale.
        const base = `${req.protocol}://${req.get('host')}`;
        const webhookBase = webhookToken ? `${base}/webhook/t/${webhookToken}` : null;
        res.json({
            webhook_token: webhookToken,
            print_agent_token: printAgentToken,
            webhook_base_url: webhookBase,
            booking_url: tenantSlug ? `${base}/prenota/${tenantSlug}` : null,
            domains: domainsRes.rows,
            examples: webhookBase ? {
                elevenlabs_init_conversation: `${webhookBase}/elevenlabs/init-conversation`,
                elevenlabs_post_call: `${webhookBase}/elevenlabs/post-call`,
                twilio_whatsapp: `${webhookBase}/twilio-whatsapp`,
                twilio_whatsapp_status: `${webhookBase}/twilio-whatsapp-status`,
                vonage_inbound: `${webhookBase}/vonage-inbound`,
                resend_inbound: `${webhookBase}/resend-inbound`,
                openapi_fiscale: `${webhookBase}/openapi-fiscale`,
            } : null,
        });
    } catch (err) {
        console.error('GET /settings/webhook-info error:', err);
        res.status(500).json({ error: 'Failed to fetch webhook info' });
    }
});

// ============================================
// PANNELLO PIATTAFORMA — PROVISIONING TENANT (Fase D1)
// ============================================
// Endpoint /admin/tenants: stanno SOPRA i tenant, quindi fuori da
// requirePermission (che è per-tenant per costruzione). Due vie d'ingresso
// (Fase D2): un JWT con ruolo PLATFORM_ADMIN — utenti creati SOLO a mano via
// SQL, nessuna route di signup — oppure il token di piattaforma da env, che
// resta come bootstrap (serve per creare il primo platform admin e per gli
// script). Prima si tenta il JWT, poi si ripiega sull'env: così il 503
// "funzionalità spenta" scatta solo quando non esiste NESSUNA via valida.
// createSchema (congelato, db.ts) ricrea a OGNI boot i CHECK su users.role e
// role_permissions.role con la lista storica a 6 ruoli, e gira PRIMA delle
// migration — che essendo già applicate non ri-allargano niente. Senza questo
// re-assert il ruolo PLATFORM_ADMIN sopravviverebbe un solo boot: la
// migration 1787133785535_platform-admin-role resta la fonte versionata del
// cambiamento, questa funzione (stessa SQL, idempotente: agisce solo se il
// CHECK non contiene già PLATFORM_ADMIN) lo difende dal ri-restringimento.
// Limite noto: se esiste già una riga con role='PLATFORM_ADMIN', la ADD
// CONSTRAINT a 6 ruoli di createSchema fallisce e fa rollback dell'intera
// transazione di createSchema — il CHECK largo sopravvive, ma quel boot
// salta seed e scheduler. La sanatoria vera è aggiornare le due ALTER in
// db.ts quando verrà scongelato.
// Re-assert delle policy RLS a OGNI boot, dopo createSchema e le migration.
// Due ragioni per cui non basta una migration:
//  1. createSchema (congelato) ricrea la policy vecchia su media_library a
//     ogni avvio: una formula cambiata solo via migration regredirebbe al
//     boot successivo. Stesso problema dei CHECK ruoli qui sotto.
//  2. La passata dinamica copre anche le tabelle nate DOPO la B4 senza una
//     policy propria: prima restavano le uniche leggibili da tutti.
// La formula ha tre modi, decisi da GUC di sessione/database:
//  - contesto tenant (app.tenant_id, messo da AsyncLocalStorage in db.ts):
//    isolamento rigido, da sempre;
//  - nessun contesto + app.rls_strict spento: fallback permissivo — il
//    comportamento storico, finché il flip non viene deciso;
//  - nessun contesto + app.rls_strict acceso: passa SOLO chi ha dichiarato
//    app.rls_bypass (boot, migration, scheduler): tutto il resto fallisce
//    CHIUSO. Il flip è un ALTER DATABASE ... SET app.rls_strict = 'on',
//    reversibile all'istante con RESET — niente deploy.
const ensureRlsPolicies = async (): Promise<void> => {
    await queryWithRetry(`
        DO $$
        DECLARE t RECORD;
        BEGIN
            FOR t IN
                SELECT tablename
                  FROM pg_tables
                 WHERE schemaname = 'public'
                   AND tablename NOT IN ('pgmigrations', 'tenants')
            LOOP
                IF NOT EXISTS (
                    SELECT 1 FROM information_schema.columns
                     WHERE table_schema = 'public'
                       AND table_name = t.tablename
                       AND column_name = 'tenant_id'
                ) THEN
                    RAISE WARNING 'RLS saltata: % non ha tenant_id', t.tablename;
                    CONTINUE;
                END IF;
                EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t.tablename);
                EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t.tablename);
                EXECUTE format('DROP POLICY IF EXISTS tenant_isolation ON %I', t.tablename);
                EXECUTE format(
                    'CREATE POLICY tenant_isolation ON %I '
                    || 'USING (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::bigint '
                    ||   'OR (NULLIF(current_setting(''app.tenant_id'', true), '''') IS NULL '
                    ||     'AND (current_setting(''app.rls_strict'', true) IS DISTINCT FROM ''on'' '
                    ||       'OR current_setting(''app.rls_bypass'', true) = ''on''))) '
                    || 'WITH CHECK (tenant_id = NULLIF(current_setting(''app.tenant_id'', true), '''')::bigint '
                    ||   'OR (NULLIF(current_setting(''app.tenant_id'', true), '''') IS NULL '
                    ||     'AND (current_setting(''app.rls_strict'', true) IS DISTINCT FROM ''on'' '
                    ||       'OR current_setting(''app.rls_bypass'', true) = ''on'')))',
                    t.tablename
                );
            END LOOP;
        END $$;
    `);
};

// Riallinea i CHECK su users.role e role_permissions.role alla lista COMPLETA
// dei ruoli. Serve perché createSchema (baseline congelata, db.ts) ri-esegue a
// ogni boot le ALTER che li ricreano con la lista storica a sei ruoli, e gira
// PRIMA delle migration — che essendo già applicate non ri-allargano niente.
// Senza questo passaggio il primo boot dopo la creazione di un utente con un
// ruolo nuovo farebbe fallire l'intera transazione di createSchema (la ADD
// CONSTRAINT valida le righe esistenti), cioè il server non partirebbe.
//
// Le migration restano la fonte versionata di ogni allargamento
// (platform-admin-role, ruolo-cassa); questo è il presidio che lo difende dal
// ri-restringimento a ogni avvio.
//
// La guardia cerca il ruolo aggiunto PIÙ DI RECENTE: un CHECK che lo contiene
// è stato scritto da questo stesso codice, quindi ha già la lista intera.
// Aggiungendo un ruolo si aggiorna la lista E il nome nella guardia.
const ROLE_CHECK_SQL_LIST = "''PLATFORM_ADMIN'', ''OWNER'', ''GENERAL_MANAGER'', ''MANAGER'', ''RECEPTION'', ''WAITER'', ''KITCHEN'', ''CASSA''";

const ensureRoleChecks = async (): Promise<void> => {
    await queryWithRetry(`
        DO $$
        DECLARE c RECORD;
        BEGIN
            FOR c IN
                SELECT conrelid::regclass AS tbl, conname
                  FROM pg_constraint
                 WHERE contype = 'c'
                   AND conrelid IN ('users'::regclass, 'role_permissions'::regclass)
                   AND pg_get_constraintdef(oid) ~ 'role.*''OWNER'''
                   AND pg_get_constraintdef(oid) !~ 'CASSA'
            LOOP
                EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I', c.tbl, c.conname);
                EXECUTE format(
                    'ALTER TABLE %s ADD CONSTRAINT %I CHECK (role IN (${ROLE_CHECK_SQL_LIST}))',
                    c.tbl, c.conname
                );
            END LOOP;
        END $$;
    `);
};

const platformAdminAuth = (req: express.Request, res: express.Response, next: express.NextFunction) => {
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
        const payload = AuthService.verifyAccessToken(authHeader.substring(7));
        if (payload && payload.role === UserRole.PLATFORM_ADMIN) {
            // L'identità finisce in req.user per l'audit (impersonation):
            // niente req.tenantId, questi endpoint non hanno un tenant.
            req.user = payload;
            return runAsPlatform(() => next());
        }
        // Bearer presente ma non da platform admin: si prova comunque la via
        // env — un client potrebbe mandare entrambi gli header.
    }
    const expected = process.env.PLATFORM_ADMIN_TOKEN || '';
    if (!expected) {
        // Env assente = funzionalità spenta, non "accesso libero": senza
        // token configurato (e senza JWT valido qui sopra) questi endpoint
        // non devono esistere.
        return res.status(503).json({ error: 'platform_admin_disabled', message: 'PLATFORM_ADMIN_TOKEN non configurato.' });
    }
    const provided = String(req.header('X-Platform-Admin-Token') ?? '');
    // Confronto timing-safe: si hashano entrambi i lati per pareggiare le
    // lunghezze (timingSafeEqual esige buffer uguali, e la lunghezza del
    // token non deve trapelare dal tempo di risposta).
    const a = crypto.createHash('sha256').update(provided).digest();
    const b = crypto.createHash('sha256').update(expected).digest();
    if (!crypto.timingSafeEqual(a, b)) {
        return res.status(401).json({ error: 'invalid_platform_admin_token' });
    }
    runAsPlatform(() => next());
};

app.post('/admin/tenants', platformAdminAuth, async (req, res) => {
    const body = req.body ?? {};
    // Le feature richieste si validano qui (l'endpoint conosce HTTP, il
    // servizio no): solo i tre nomi noti, solo boolean.
    const features: Partial<Record<TenantFeature, boolean>> = {};
    if (body.features !== undefined) {
        if (typeof body.features !== 'object' || body.features === null || Array.isArray(body.features)) {
            return res.status(400).json({ error: 'invalid_features', message: 'features deve essere un oggetto {voice|whatsapp|web_booking: boolean}' });
        }
        for (const [key, value] of Object.entries(body.features)) {
            if (!(TENANT_FEATURES as readonly string[]).includes(key) || typeof value !== 'boolean') {
                return res.status(400).json({ error: 'invalid_features', message: `Feature non valida: ${String(key).slice(0, 40)}` });
            }
            features[key as TenantFeature] = value;
        }
    }
    try {
        const result = await provisionTenant({
            slug: body.slug,
            name: body.name,
            timezone: body.timezone,
            owner_email: body.owner_email,
            owner_full_name: body.owner_full_name,
            features,
        });
        // La password temporanea esce SOLO da questa risposta: chi provisiona
        // la consegna all'OWNER a voce/di persona. Niente email di invito —
        // la casella SMTP del nuovo tenant non esiste ancora (arriva col
        // wizard di onboarding, quando il tenant ha una casella sua).
        res.status(201).json({
            tenant: result.tenant,
            owner_temp_password: result.ownerTempPassword,
            webhook_token: result.tokens.webhook_token,
            print_agent_token: result.tokens.print_agent_token,
            booking_url: `${req.protocol}://${req.get('host')}/prenota/${result.tenant.slug}`,
        });
    } catch (err) {
        if (err instanceof ProvisioningError) {
            const conflict = err.code === 'slug_conflict' || err.code === 'email_conflict';
            return res.status(conflict ? 409 : 400).json({ error: err.code, message: err.message });
        }
        console.error('POST /admin/tenants error:', err);
        res.status(500).json({ error: 'Failed to provision tenant' });
    }
});

// URL del customer sul Dashboard Stripe. La modalità (test/live) si deduce
// dal prefisso della chiave: un id di test aperto sull'URL live darebbe un
// "customer non trovato" che sembra un dato perso.
const stripeDashboardCustomerUrl = (customerId: string | null): string | null => {
    if (!customerId) return null;
    const testMode = (process.env.STRIPE_SECRET_KEY || '').startsWith('sk_test');
    return `https://dashboard.stripe.com/${testMode ? 'test/' : ''}customers/${customerId}`;
};

app.get('/admin/tenants', platformAdminAuth, async (_req, res) => {
    try {
        // Feature attive come array di nomi e conteggio utenti in una query:
        // è la vista "lista tenant" del futuro pannello D2, non un report.
        const result = await queryWithRetry(
            `SELECT t.id, t.slug, t.name, t.status, t.billing_status, t.stripe_customer_id, t.created_at,
                    COALESCE(
                        array_agg(f.feature ORDER BY f.feature) FILTER (WHERE f.enabled),
                        '{}'
                    ) AS features,
                    (SELECT COUNT(*)::int FROM users u WHERE u.tenant_id = t.id) AS user_count
             FROM tenants t
             LEFT JOIN tenant_features f ON f.tenant_id = t.id
             GROUP BY t.id
             ORDER BY t.id`
        );
        res.json(result.rows.map((r: any) => ({
            id: Number(r.id),
            slug: r.slug,
            name: r.name,
            status: r.status,
            // NULL = tenant non a pagamento (grandfathered): il pannello lo
            // distingue da un pagante moroso.
            billing_status: r.billing_status,
            // Link diretto al customer sul Dashboard Stripe; null per i
            // tenant senza billing.
            stripe_customer_url: stripeDashboardCustomerUrl(r.stripe_customer_id ?? null),
            created_at: r.created_at,
            features: r.features,
            user_count: r.user_count,
        })));
    } catch (err) {
        console.error('GET /admin/tenants error:', err);
        res.status(500).json({ error: 'Failed to list tenants' });
    }
});

// Riepilogo billing per la testata del pannello: MRR dalla verità Stripe
// (le subscription attive, normalizzate al mese) + conteggi dei tenant per
// stato billing dal nostro DB. Un solo giro per apertura pannello: niente
// cache, la lista subscription di una piattaforma giovane è corta.
app.get('/admin/billing/summary', platformAdminAuth, async (_req, res) => {
    if (!isBillingEnabled()) {
        return res.status(503).json({ error: 'billing_disabled', message: 'STRIPE_SECRET_KEY non configurata' });
    }
    try {
        const counts = await queryWithRetry(
            `SELECT billing_status, COUNT(*)::int AS n
               FROM tenants GROUP BY billing_status`
        );
        let paying = 0, pastDue = 0, trialing = 0, grandfathered = 0;
        for (const row of counts.rows) {
            const n = Number(row.n);
            if (row.billing_status === null) grandfathered += n;
            else if (row.billing_status === 'past_due') { pastDue += n; paying += n; }
            else if (row.billing_status === 'trialing') trialing += n;
            else if (row.billing_status === 'active') paying += n;
        }

        // MRR: somma degli item delle subscription attive e in past_due
        // (Stripe le conta nel MRR finché non muoiono), annuale diviso 12.
        const stripe = getStripe();
        let mrrCents = 0;
        for (const status of ['active', 'past_due'] as const) {
            for await (const sub of stripe.subscriptions.list({ status, limit: 100 })) {
                for (const item of sub.items.data) {
                    const price = item.price;
                    if (!price?.recurring || typeof price.unit_amount !== 'number') continue;
                    const qty = item.quantity ?? 1;
                    const amount = price.unit_amount * qty;
                    mrrCents += price.recurring.interval === 'year'
                        ? Math.round(amount / 12)
                        : price.recurring.interval === 'month'
                            ? amount
                            : 0;
                }
            }
        }

        res.json({
            mrr_cents: mrrCents,
            paying_tenants: paying,
            past_due_tenants: pastDue,
            trialing_tenants: trialing,
            grandfathered_tenants: grandfathered,
        });
    } catch (err: any) {
        console.error('GET /admin/billing/summary error:', err?.message || err);
        res.status(502).json({ error: 'stripe_error', message: 'Riepilogo Stripe non disponibile' });
    }
});

app.patch('/admin/tenants/:id', platformAdminAuth, async (req, res) => {
    const tenantId = Number(req.params.id);
    if (!Number.isInteger(tenantId) || tenantId <= 0) {
        return res.status(400).json({ error: 'invalid_tenant_id' });
    }
    const body = req.body ?? {};
    const status: string | undefined = body.status;
    if (status !== undefined && status !== 'active' && status !== 'suspended') {
        return res.status(400).json({ error: 'invalid_status', message: "status deve essere 'active' o 'suspended'" });
    }
    const featureUpdates: Array<{ feature: TenantFeature; enabled: boolean }> = [];
    if (body.features !== undefined) {
        if (typeof body.features !== 'object' || body.features === null || Array.isArray(body.features)) {
            return res.status(400).json({ error: 'invalid_features', message: 'features deve essere un oggetto {voice|whatsapp|web_booking: boolean}' });
        }
        for (const [key, value] of Object.entries(body.features)) {
            if (!(TENANT_FEATURES as readonly string[]).includes(key) || typeof value !== 'boolean') {
                return res.status(400).json({ error: 'invalid_features', message: `Feature non valida: ${String(key).slice(0, 40)}` });
            }
            featureUpdates.push({ feature: key as TenantFeature, enabled: value });
        }
    }
    if (status === undefined && featureUpdates.length === 0) {
        return res.status(400).json({ error: 'no_updates', message: 'Niente da aggiornare: status e/o features' });
    }
    try {
        const exists = await queryWithRetry('SELECT slug FROM tenants WHERE id = $1', [tenantId]);
        if (exists.rows.length === 0) {
            return res.status(404).json({ error: 'tenant_not_found' });
        }
        if (status !== undefined) {
            await queryWithRetry(
                `UPDATE tenants SET status = $2, updated_at = CURRENT_TIMESTAMP WHERE id = $1`,
                [tenantId, status]
            );
            // La risoluzione slug/dominio filtra su status='active' ma è
            // cache-ata: senza invalidazione una sospensione lascerebbe la
            // pagina pubblica viva fino allo scadere del TTL.
            tenantSlugCache.delete(String(exists.rows[0].slug));
            for (const [domain, entry] of tenantDomainCache) {
                if (entry.hit.tenantId === tenantId) tenantDomainCache.delete(domain);
            }
        }
        for (const { feature, enabled } of featureUpdates) {
            await queryWithRetry(
                `INSERT INTO tenant_features (tenant_id, feature, enabled, updated_at)
                 VALUES ($1, $2, $3, CURRENT_TIMESTAMP)
                 ON CONFLICT (tenant_id, feature) DO UPDATE
                   SET enabled = EXCLUDED.enabled, updated_at = CURRENT_TIMESTAMP`,
                [tenantId, feature, enabled]
            );
        }
        if (featureUpdates.length > 0) {
            // Stessa regola del PUT /settings/entitlements: il toggle vale
            // subito, non allo scadere del TTL della cache.
            invalidateTenantFeaturesCache(tenantId);
        }
        const tenantRes = await queryWithRetry(
            'SELECT id, slug, name, status, timezone, created_at FROM tenants WHERE id = $1',
            [tenantId]
        );
        res.json({
            tenant: { ...tenantRes.rows[0], id: Number(tenantRes.rows[0].id) },
            features: await getTenantFeatures(tenantId),
        });
    } catch (err) {
        console.error('PATCH /admin/tenants/:id error:', err);
        res.status(500).json({ error: 'Failed to update tenant' });
    }
});

// Impersonation (Fase D2): il platform admin entra in un tenant come il suo
// primo OWNER attivo. Il token emesso è un access token normale — stesso
// secret, stesso payload — quindi `authenticate` e tutte le route scoped lo
// accettano senza codice dedicato; è però corto (15 min) e porta il claim
// impersonated_by per l'audit. NESSUN refresh token: la sessione non può
// rinnovarsi per costruzione (il refresh esige un token firmato col secret
// di refresh, che qui non viene emesso). L'ingresso resta tracciato
// nell'activity log del tenant bersaglio: l'OWNER vede che la piattaforma
// è entrata, e chi.
app.post('/admin/tenants/:id/impersonate', platformAdminAuth, async (req, res) => {
    const tenantId = Number(req.params.id);
    if (!Number.isInteger(tenantId) || tenantId <= 0) {
        return res.status(400).json({ error: 'invalid_tenant_id' });
    }
    try {
        const tenantRes = await queryWithRetry('SELECT id, slug FROM tenants WHERE id = $1', [tenantId]);
        if (tenantRes.rows.length === 0) {
            return res.status(404).json({ error: 'tenant_not_found' });
        }
        // Il primo OWNER attivo per id: deterministico, ed è l'account che il
        // provisioning D1 crea per primo.
        const ownerRes = await queryWithRetry(
            `SELECT id, email, role FROM users
              WHERE tenant_id = $1 AND role = 'OWNER' AND is_active = TRUE
              ORDER BY id LIMIT 1`,
            [tenantId]
        );
        if (ownerRes.rows.length === 0) {
            return res.status(404).json({ error: 'owner_not_found', message: 'Il tenant non ha un OWNER attivo da impersonare.' });
        }
        const owner = ownerRes.rows[0];
        // Chi impersona: l'email del JWT di piattaforma, o 'env-token' se
        // l'ingresso è avvenuto col token di bootstrap da env.
        const impersonatedBy = req.user?.email ?? 'env-token';
        const accessToken = AuthService.generateImpersonationToken(
            {
                userId: owner.id,
                email: owner.email,
                role: owner.role as UserRole,
                tenantId,
            },
            impersonatedBy
        );
        // user_id NULL: l'admin di piattaforma non è un utente del tenant.
        // Azione LOGIN (l'enum ActivityAction è chiuso, niente IMPERSONATE):
        // i dettagli dicono che è un'impersonation e da parte di chi.
        await LogService.logActivity(
            tenantId,
            null,
            impersonatedBy,
            'Platform admin',
            ActivityAction.LOGIN,
            ResourceType.AUTH,
            owner.id,
            owner.email,
            { impersonation: true, impersonated_by: impersonatedBy, target_email: owner.email }
        );
        res.json({
            accessToken,
            expires_in_seconds: AuthService.IMPERSONATION_TTL_SECONDS,
            user: { email: owner.email, role: owner.role },
            tenant: { id: tenantId, slug: tenantRes.rows[0].slug },
        });
    } catch (err) {
        console.error('POST /admin/tenants/:id/impersonate error:', err);
        res.status(500).json({ error: 'Failed to impersonate tenant' });
    }
});

// ============================================
// BILLING STRIPE (Fase D3)
// ============================================
// Lean e webhook-driven: gli endpoint admin generano solo gli URL di
// checkout/portal (nessun form carta da noi), lo stato del tenant lo detta
// il webhook via applySubscriptionState (services/billingService.ts).
// Tutto risponde 503 billing_disabled finché le env Stripe non ci sono:
// il Frantoio (grandfathered, billing_status NULL) non è toccato.

// Traduzione BillingError → HTTP: la fa la route, il servizio non conosce
// gli status code.
const billingErrorToResponse = (res: express.Response, err: unknown, routeLabel: string): void => {
    if (err instanceof BillingError) {
        const status = err.code === 'billing_disabled' ? 503
            : err.code === 'tenant_not_found' ? 404
            : err.code === 'stripe_customer_missing' ? 409
            : err.code === 'no_subscription' ? 409
            : 400;
        res.status(status).json({ error: err.code, message: err.message });
        return;
    }
    console.error(`${routeLabel} error:`, err);
    res.status(500).json({ error: 'billing_error' });
};

app.post('/admin/tenants/:id/billing/checkout', platformAdminAuth, async (req, res) => {
    const tenantId = Number(req.params.id);
    if (!Number.isInteger(tenantId) || tenantId <= 0) {
        return res.status(400).json({ error: 'invalid_tenant_id' });
    }
    const body = req.body ?? {};
    let prices: string[] | undefined;
    if (body.prices !== undefined) {
        if (!Array.isArray(body.prices) || body.prices.length === 0
            || body.prices.some((p: unknown) => typeof p !== 'string' || !p)) {
            return res.status(400).json({ error: 'invalid_prices', message: 'prices deve essere un array non vuoto di price id Stripe' });
        }
        prices = body.prices;
    }
    // Le pagine di ritorno vivono sul backend stesso (GET qui sotto): chi
    // apre il checkout è l'admin di piattaforma in un'altra scheda — basta
    // una riga che dica com'è andata, senza UI dedicata.
    const origin = `${req.protocol}://${req.get('host')}`;
    const successUrl = typeof body.success_url === 'string' && body.success_url ? body.success_url : `${origin}/admin/billing/success`;
    const cancelUrl = typeof body.cancel_url === 'string' && body.cancel_url ? body.cancel_url : `${origin}/admin/billing/cancel`;
    try {
        const session = await createCheckoutSession(tenantId, { prices, successUrl, cancelUrl });
        res.json({ url: session.url, session_id: session.sessionId });
    } catch (err) {
        billingErrorToResponse(res, err, 'POST /admin/tenants/:id/billing/checkout');
    }
});

app.post('/admin/tenants/:id/billing/portal', platformAdminAuth, async (req, res) => {
    const tenantId = Number(req.params.id);
    if (!Number.isInteger(tenantId) || tenantId <= 0) {
        return res.status(400).json({ error: 'invalid_tenant_id' });
    }
    const body = req.body ?? {};
    const origin = `${req.protocol}://${req.get('host')}`;
    const returnUrl = typeof body.return_url === 'string' && body.return_url ? body.return_url : `${origin}/admin/billing/return`;
    try {
        const session = await createPortalSession(tenantId, returnUrl);
        res.json({ url: session.url });
    } catch (err) {
        billingErrorToResponse(res, err, 'POST /admin/tenants/:id/billing/portal');
    }
});

// Picker add-on del pannello: accende/spegne moduli sulla subscription del
// tenant (item aggiunti/rimossi con prorazione). Le feature a DB si
// allineano subito dallo stato Stripe risultante — il webhook che seguirà è
// una conferma, non un'attesa.
app.patch('/admin/tenants/:id/billing/addons', platformAdminAuth, async (req, res) => {
    const tenantId = Number(req.params.id);
    if (!Number.isInteger(tenantId) || tenantId <= 0) {
        return res.status(400).json({ error: 'invalid_tenant_id' });
    }
    const raw = (req.body ?? {}).features;
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
        return res.status(400).json({ error: 'invalid_features', message: 'features deve essere un oggetto {feature: boolean}' });
    }
    const desired: Partial<Record<TenantFeature, boolean>> = {};
    for (const [key, value] of Object.entries(raw)) {
        if (!(TENANT_FEATURES as readonly string[]).includes(key)) {
            return res.status(400).json({ error: 'invalid_features', message: `Feature non valida: ${String(key).slice(0, 40)}` });
        }
        if (typeof value !== 'boolean') {
            return res.status(400).json({ error: 'invalid_features', message: `Valore non booleano per ${key}` });
        }
        desired[key as TenantFeature] = value;
    }
    if (Object.keys(desired).length === 0) {
        return res.status(400).json({ error: 'invalid_features', message: 'Nessuna feature da aggiornare' });
    }
    try {
        const applied = await updateSubscriptionAddons(tenantId, desired);
        res.json({
            billing_status: applied.billingStatus,
            features: await getTenantFeatures(tenantId),
        });
    } catch (err) {
        billingErrorToResponse(res, err, 'PATCH /admin/tenants/:id/billing/addons');
    }
});

// Pagine di ritorno di checkout e portal. Prima non esistevano e Stripe
// atterrava su "Cannot GET /admin/billing/success" — pagamento riuscito,
// faccia di errore. Una riga di esito e nient'altro: chi arriva qui è
// l'admin con il pannello aperto nell'altra scheda.
const billingReturnPage = (title: string, message: string): string => `<!doctype html>
<html lang="it"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>${title}</title>
<style>body{margin:0;min-height:100vh;display:flex;align-items:center;justify-content:center;font-family:-apple-system,system-ui,sans-serif;background:#ededf1;color:#1c1c21}main{text-align:center;padding:32px}h1{font-size:22px;margin:0 0 8px}p{font-size:15px;color:#5c5c66;margin:0}</style>
</head><body><main><h1>${title}</h1><p>${message}</p></main></body></html>`;

app.get('/admin/billing/success', (_req, res) => {
    res.type('html').send(billingReturnPage(
        'Abbonamento attivato',
        'Il webhook Stripe sta aggiornando il cliente. Puoi chiudere questa scheda e tornare al pannello.'
    ));
});
app.get('/admin/billing/cancel', (_req, res) => {
    res.type('html').send(billingReturnPage(
        'Pagamento annullato',
        'Nessun addebito. Puoi chiudere questa scheda e riprovare dal pannello.'
    ));
});
app.get('/admin/billing/return', (_req, res) => {
    res.type('html').send(billingReturnPage(
        'Fatturazione aggiornata',
        'Le modifiche fatte nel portal arrivano al pannello via webhook. Puoi chiudere questa scheda.'
    ));
});

// Webhook Stripe: l'UNICA via con cui lo stato della subscription entra nel
// DB. Stripe firma i byte esatti del payload: la verifica usa req.rawBody
// (catturato dal verify hook di express.json in testa al file), MAI il body
// già parsato — una ri-serializzazione riordina le chiavi e rompe la firma.
app.post('/webhook/stripe', async (req, res) => runAsPlatform(async () => {
    if (!process.env.STRIPE_WEBHOOK_SECRET || !isBillingEnabled()) {
        // Env assente = funzionalità spenta, stessa semantica del pannello
        // piattaforma: l'endpoint non deve esistere finché non è configurato.
        return res.status(503).json({ error: 'billing_disabled', message: 'STRIPE_WEBHOOK_SECRET/STRIPE_SECRET_KEY non configurate.' });
    }
    const rawBody = (req as any).rawBody as Buffer | undefined;
    if (!rawBody) {
        return res.status(400).json({ error: 'missing_body' });
    }
    let event;
    try {
        event = constructWebhookEvent(rawBody, String(req.headers['stripe-signature'] ?? ''));
    } catch (err: any) {
        console.warn('[billing] firma webhook Stripe non valida:', err?.message || err);
        return res.status(400).json({ error: 'invalid_signature' });
    }
    try {
        switch (event.type) {
            case 'customer.subscription.created':
            case 'customer.subscription.updated':
            case 'customer.subscription.deleted': {
                const subscription = event.data.object as unknown as SubscriptionLike;
                // deleted = subscription rimossa: si tratta come canceled
                // qualunque status porti l'oggetto, il tenant va sospeso.
                const effective = event.type === 'customer.subscription.deleted'
                    ? { ...subscription, status: 'canceled' }
                    : subscription;
                const applied = await applySubscriptionState(effective);
                if (applied && applied.tenantStatusChanged) {
                    // Stessa invalidazione della PATCH admin: la risoluzione
                    // slug/dominio filtra su status='active' ma è cache-ata —
                    // senza questo una sospensione lascerebbe la pagina
                    // pubblica viva fino allo scadere del TTL.
                    tenantSlugCache.delete(applied.slug);
                    for (const [domain, entry] of tenantDomainCache) {
                        if (entry.hit.tenantId === applied.tenantId) tenantDomainCache.delete(domain);
                    }
                }
                // Avviso ai platform admin sulla TRANSIZIONE a past_due (non
                // a ogni retry Stripe: i webhook della stessa morosità
                // arrivano più volte). Il tag deduplica anche lato centro
                // notifiche. La sospensione vera (canceled/unpaid) non ha
                // bisogno di push: la fa già la sync spegnendo il tenant.
                if (applied && applied.billingStatus === 'past_due' && applied.previousBillingStatus !== 'past_due') {
                    pushSendToPlatformAdmins({
                        category: 'billing',
                        title: 'Pagamento non riuscito',
                        body: `${applied.name}: abbonamento in past_due, Stripe sta ritentando l'addebito.`,
                        url: '/?view=PLATFORM',
                        tag: `billing-past-due-${applied.tenantId}`,
                    }).catch(err => console.warn('[billing] push past_due fallita:', (err as any)?.message || err));
                }
                break;
            }
            default:
                // Ogni altro evento si acka e basta: invoice.*, checkout.*…
                // arrivano comunque (Stripe manda tutto ciò che è abilitato)
                // ma la verità che ci serve è nella subscription.
                break;
        }
        res.json({ received: true });
    } catch (err) {
        console.error('POST /webhook/stripe error:', err);
        // 500 esplicito: Stripe ritenta con backoff, e un errore transitorio
        // del DB non deve far perdere l'evento.
        res.status(500).json({ error: 'webhook_processing_failed' });
    }
}));

// ============================================
// INTEGRATION SETTINGS (Revolut)
// ============================================
// GET returns a masked snapshot (last 4 chars of secrets + booleans) so the
// UI can render the current state without leaking credentials. PUT accepts
// partial updates: any field left out is preserved. Sending an empty string
// clears that field back to the env-var fallback.
app.get('/settings/integrations/revolut', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const status = await getRevolutConfigStatus(req.tenantId!);

        // integration_settings may not exist yet on a brand-new deploy where
        // the schema-init CTE that creates it hasn't finished running. Treat
        // any error here as "no metadata" so the card renders anyway with the
        // env-fallback status.
        let updatedAt: string | null = null;
        let updatedByEmail: string | null = null;
        try {
            const meta = await queryWithRetry(
                `SELECT updated_at, updated_by_user_id FROM integration_settings WHERE tenant_id = $1 AND provider = 'revolut'`,
                [req.tenantId!]
            );
            const row = meta.rows[0];
            if (row) {
                updatedAt = row.updated_at ?? null;
                if (row.updated_by_user_id) {
                    const u = await queryWithRetry(`SELECT email FROM users WHERE id = $1`, [row.updated_by_user_id]);
                    updatedByEmail = u.rows[0]?.email ?? null;
                }
            }
        } catch (metaErr: any) {
            console.warn('[Revolut] integration_settings metadata unavailable:', metaErr?.message || metaErr);
        }

        res.json({
            ...status,
            updated_at: updatedAt,
            updated_by: updatedByEmail,
        });
    } catch (err: any) {
        console.error('GET /settings/integrations/revolut error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

app.put('/settings/integrations/revolut', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const body = req.body ?? {};
        const updates: Record<string, string | null> = {};

        if (body.environment !== undefined) {
            if (body.environment !== 'sandbox' && body.environment !== 'production') {
                return res.status(400).json({ error: 'invalid_environment' });
            }
            updates.environment = body.environment;
        }
        // Empty string is a legit signal to CLEAR the DB value (fall back to
        // env). Undefined means "leave alone". null is treated the same as
        // empty string.
        const nullableString = (v: unknown): string | null | undefined => {
            if (v === undefined) return undefined;
            if (v === null) return null;
            if (typeof v !== 'string') return undefined;
            const trimmed = v.trim();
            return trimmed === '' ? null : trimmed;
        };
        const apiKey = nullableString(body.api_key);
        if (apiKey !== undefined) updates.api_key = apiKey;
        const webhookSecret = nullableString(body.webhook_secret);
        if (webhookSecret !== undefined) updates.webhook_secret = webhookSecret;
        const apiVersion = nullableString(body.api_version);
        if (apiVersion !== undefined) updates.api_version = apiVersion;

        if (Object.keys(updates).length === 0) {
            return res.status(400).json({ error: 'no_updates' });
        }

        // Build an UPSERT: on first save the row doesn't exist yet so we need
        // to insert with the provided fields (defaulting environment to
        // 'sandbox') and, on conflict, update only the columns we were asked
        // to change.
        const providedCols = Object.keys(updates);
        const providedVals = providedCols.map(c => updates[c]);
        const userId = req.user?.userId ?? null;

        // Insert: fill known columns; for columns not provided, insert NULL
        // (environment defaults to 'sandbox' via the table default).
        // La PK è (tenant_id, provider): la riga è del ristorante, e gli
        // indici dei placeholder scalano di uno per il tenant in testa.
        const insertCols = ['tenant_id', 'provider', ...providedCols, 'updated_by_user_id', 'updated_at'];
        const insertPlaceholders = insertCols.map((_, i) => `$${i + 1}`).join(', ');
        const insertValues = [req.tenantId!, 'revolut', ...providedVals, userId, new Date()];

        const updateSet = [
            ...providedCols.map((c, i) => `${c} = $${i + 3}`),
            `updated_by_user_id = $${providedCols.length + 3}`,
            `updated_at = CURRENT_TIMESTAMP`,
        ].join(', ');

        await queryWithRetry(
            `INSERT INTO integration_settings (${insertCols.join(', ')})
             VALUES (${insertPlaceholders})
             ON CONFLICT (tenant_id, provider) DO UPDATE SET ${updateSet}`,
            insertValues
        );

        invalidateRevolutConfigCache();

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.UPDATE,
                ResourceType.SETTINGS,
                undefined,
                `Integrazione Revolut aggiornata (${updates.environment || 'campi credenziali'})`
            );
        }

        const status = await getRevolutConfigStatus(req.tenantId!);
        res.json({ ...status, updated_at: new Date().toISOString(), updated_by: req.user?.email ?? null });
    } catch (err: any) {
        console.error('PUT /settings/integrations/revolut error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// ============================================
// INTEGRATION SETTINGS (SumUp)
// ============================================
// Same contract as the Revolut endpoints above — GET returns a masked
// snapshot, PUT takes partial updates and treats an empty string as "clear
// back to the env fallback" — with one addition: SumUp credentials are stored
// per environment (production uses api_key + sumup_merchant_code, sandbox
// uses its own pair), because SumUp serves both from the same host and tells
// them apart by the key. `environment` picks which pair is live, so an
// operator can keep sandbox credentials around and flip back to test.
app.get('/settings/integrations/sumup', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const status = await getSumUpConfigStatus(req.tenantId!);
        const activeProvider = await getActivePaymentProvider(req.tenantId!);

        // Same defensive read as the Revolut card: on a brand-new deploy the
        // schema-init may not have created the table yet, and the card should
        // still render off the env fallbacks.
        let updatedAt: string | null = null;
        let updatedByEmail: string | null = null;
        try {
            const meta = await queryWithRetry(
                `SELECT updated_at, updated_by_user_id FROM integration_settings WHERE tenant_id = $1 AND provider = 'sumup'`,
                [req.tenantId!]
            );
            const row = meta.rows[0];
            if (row) {
                updatedAt = row.updated_at ?? null;
                if (row.updated_by_user_id) {
                    const u = await queryWithRetry(`SELECT email FROM users WHERE id = $1`, [row.updated_by_user_id]);
                    updatedByEmail = u.rows[0]?.email ?? null;
                }
            }
        } catch (metaErr: any) {
            console.warn('[SumUp] integration_settings metadata unavailable:', metaErr?.message || metaErr);
        }

        res.json({
            ...status,
            active_provider: activeProvider,
            is_active_provider: activeProvider === 'sumup',
            // The URL SumUp calls back on. Shown read-only in the card so the
            // operator can sanity-check it against CRM_APP_BASE_URL; the
            // token itself is never rendered.
            callback_url: status.has_callback_secret ? `${publicBaseUrl()}/webhook/sumup/•••` : null,
            updated_at: updatedAt,
            updated_by: updatedByEmail,
        });
    } catch (err: any) {
        console.error('GET /settings/integrations/sumup error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

app.put('/settings/integrations/sumup', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const body = req.body ?? {};
        const updates: Record<string, string | null> = {};

        if (body.environment !== undefined) {
            if (body.environment !== 'sandbox' && body.environment !== 'production') {
                return res.status(400).json({ error: 'invalid_environment' });
            }
            updates.environment = body.environment;
        }

        // Empty string clears the DB value (falling back to env); undefined
        // means "leave alone"; null behaves like empty string.
        const nullableString = (v: unknown): string | null | undefined => {
            if (v === undefined) return undefined;
            if (v === null) return null;
            if (typeof v !== 'string') return undefined;
            const trimmed = v.trim();
            return trimmed === '' ? null : trimmed;
        };

        const fieldMap: Array<[string, string]> = [
            ['api_key', 'api_key'],                                   // production secret key
            ['merchant_code', 'sumup_merchant_code'],                 // production merchant code
            ['sandbox_api_key', 'sumup_sandbox_api_key'],
            ['sandbox_merchant_code', 'sumup_sandbox_merchant_code'],
            ['callback_secret', 'webhook_secret'],
        ];
        for (const [bodyKey, column] of fieldMap) {
            const value = nullableString(body[bodyKey]);
            if (value !== undefined) updates[column] = value;
        }

        // Switching the active gateway is part of the same card, but it lives
        // in app_settings rather than on this row — handle it separately so a
        // provider-only save doesn't trip the "no updates" guard.
        let providerChange: PaymentProvider | null = null;
        if (body.set_active !== undefined) {
            if (typeof body.set_active !== 'boolean') {
                return res.status(400).json({ error: 'invalid_set_active' });
            }
            providerChange = body.set_active ? 'sumup' : 'revolut';
        }

        if (Object.keys(updates).length === 0 && providerChange === null) {
            return res.status(400).json({ error: 'no_updates' });
        }

        // The callback token is ours to mint — SumUp doesn't hand one out —
        // so generate it the first time credentials are saved rather than
        // asking the operator to invent a secret. Without it we can't
        // register a return_url and payments would only settle on reconcile.
        if (Object.keys(updates).length > 0 && updates.webhook_secret === undefined) {
            const existing = await getSumUpConfigStatus(req.tenantId!);
            if (!existing.has_callback_secret) {
                updates.webhook_secret = crypto.randomBytes(24).toString('hex');
            }
        }

        if (Object.keys(updates).length > 0) {
            // UPSERT so the first save works before the row exists; on
            // conflict only the columns we were asked to change are touched.
            const providedCols = Object.keys(updates);
            const providedVals = providedCols.map(c => updates[c]);
            const userId = req.user?.userId ?? null;

            // PK (tenant_id, provider): vedi il PUT Revolut qui sopra.
            const insertCols = ['tenant_id', 'provider', ...providedCols, 'updated_by_user_id', 'updated_at'];
            const insertPlaceholders = insertCols.map((_, i) => `$${i + 1}`).join(', ');
            const insertValues = [req.tenantId!, 'sumup', ...providedVals, userId, new Date()];

            const updateSet = [
                ...providedCols.map((c, i) => `${c} = $${i + 3}`),
                `updated_by_user_id = $${providedCols.length + 3}`,
                `updated_at = CURRENT_TIMESTAMP`,
            ].join(', ');

            await queryWithRetry(
                `INSERT INTO integration_settings (${insertCols.join(', ')})
                 VALUES (${insertPlaceholders})
                 ON CONFLICT (tenant_id, provider) DO UPDATE SET ${updateSet}`,
                insertValues
            );
            invalidateSumUpConfigCache();
        }

        if (providerChange) {
            // Refuse to route live payments at a gateway that can't take
            // them — the failure would otherwise only show up on the guest's
            // checkout link.
            if (!(await isProviderConfigured(req.tenantId!, providerChange))) {
                return res.status(400).json({
                    error: `${providerLabel(providerChange)} non è configurato: completa le credenziali prima di attivarlo`,
                });
            }
            await setActivePaymentProvider(req.tenantId!, providerChange);
        }

        if (req.user) {
            const what = providerChange
                ? `provider attivo: ${providerLabel(providerChange)}`
                : (updates.environment || 'campi credenziali');
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.UPDATE,
                ResourceType.SETTINGS,
                undefined,
                `Integrazione SumUp aggiornata (${what})`
            );
        }

        const status = await getSumUpConfigStatus(req.tenantId!);
        const activeProvider = await getActivePaymentProvider(req.tenantId!);
        res.json({
            ...status,
            active_provider: activeProvider,
            is_active_provider: activeProvider === 'sumup',
            callback_url: status.has_callback_secret ? `${publicBaseUrl()}/webhook/sumup/•••` : null,
            updated_at: new Date().toISOString(),
            updated_by: req.user?.email ?? null,
        });
    } catch (err: any) {
        console.error('PUT /settings/integrations/sumup error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

// Which gateway new payments are created with. Split out from the two
// integration cards so either of them (and any future provider) can read and
// flip it without knowing about the other.
// GET is auth-only, not settings:full: the reservation modal labels its
// deposit box with the gateway that will actually take the money ("Richiedi
// acconto (SumUp)"), and that box is used by staff who can't see Settings.
// Nothing here is secret — just which gateway is live and whether it's ready.
// PUT stays admin-only.
app.get('/settings/payments/provider', authenticate, async (req, res) => {
    try {
        const active = await getActivePaymentProvider(req.tenantId!);
        const configured: Record<string, boolean> = {};
        for (const provider of PAYMENT_PROVIDERS) {
            configured[provider] = await isProviderConfigured(req.tenantId!, provider);
        }
        // Per-flow overrides (caparre e conti al tavolo): override = scelta
        // esplicita o null (= segue il globale), effective = provider che
        // verrà davvero usato per il prossimo incasso di quel flusso.
        const overrides = await getPaymentProviderOverrides(req.tenantId!);
        const flows: Record<string, { override: PaymentProvider | null; effective: PaymentProvider; label: string }> = {};
        for (const flow of PAYMENT_FLOWS) {
            const effective = overrides[flow] ?? active;
            flows[flow] = { override: overrides[flow] ?? null, effective, label: providerLabel(effective) };
        }
        res.json({
            provider: active,
            label: providerLabel(active),
            providers: PAYMENT_PROVIDERS,
            configured,
            flows,
        });
    } catch (err: any) {
        console.error('GET /settings/payments/provider error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

app.put('/settings/payments/provider', authenticate, requirePermission('settings:full'), async (req, res) => {
    try {
        const provider = req.body?.provider;
        const flow = req.body?.flow;

        // Con `flow` la scelta vale solo per quel flusso (caparre o conti);
        // provider null rimuove l'override e il flusso torna al globale.
        if (flow !== undefined) {
            if (!isPaymentFlow(flow)) {
                return res.status(400).json({ error: 'invalid_flow' });
            }
            if (provider !== null && !isPaymentProvider(provider)) {
                return res.status(400).json({ error: 'invalid_provider' });
            }
            if (provider !== null && !(await isProviderConfigured(req.tenantId!, provider))) {
                return res.status(400).json({
                    error: `${providerLabel(provider)} non è configurato: completa le credenziali prima di attivarlo`,
                });
            }
            await setPaymentProviderForFlow(req.tenantId!, flow, provider);
            const flowLabel = flow === 'deposit' ? 'caparre' : 'conti al tavolo';
            if (req.user) {
                LogService.logActivity(
                    req.tenantId!,
                    req.user.userId,
                    req.user.email,
                    req.user.email,
                    ActivityAction.UPDATE,
                    ResourceType.SETTINGS,
                    undefined,
                    provider === null
                        ? `Provider ${flowLabel}: segue il predefinito`
                        : `Provider ${flowLabel}: ${providerLabel(provider)}`
                );
            }
            return res.json({ flow, provider });
        }

        if (!isPaymentProvider(provider)) {
            return res.status(400).json({ error: 'invalid_provider' });
        }
        if (!(await isProviderConfigured(req.tenantId!, provider))) {
            return res.status(400).json({
                error: `${providerLabel(provider)} non è configurato: completa le credenziali prima di attivarlo`,
            });
        }
        await setActivePaymentProvider(req.tenantId!, provider);

        if (req.user) {
            LogService.logActivity(
                req.tenantId!,
                req.user.userId,
                req.user.email,
                req.user.email,
                ActivityAction.UPDATE,
                ResourceType.SETTINGS,
                undefined,
                `Provider pagamenti attivo: ${providerLabel(provider)}`
            );
        }
        res.json({ provider });
    } catch (err: any) {
        console.error('PUT /settings/payments/provider error:', err);
        res.status(500).json({ error: 'Internal server error', detail: err?.message });
    }
});

